CREATE FUNCTION public.apply_manual_stock_adjustment(p_product_id uuid, p_quantity integer, p_type text, p_reason text DEFAULT 'Ajuste Manual'::text, p_adjustment_origin text DEFAULT 'manual_service'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return public.apply_inventory_stock_adjustment(
    p_product_id,
    p_quantity,
    p_type,
    'count',
    p_reason,
    now(),
    p_adjustment_origin
  );
end;
$$;


--
-- TOC entry 2033 (class 1255 OID 236752)
-- Name: apply_whatsapp_job_action(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_whatsapp_job_action(p_job_id uuid, p_action text, p_external_message_id text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job record;
  v_status_code text;
  v_status_id uuid;
  v_description text;
begin
  select * into v_job
  from public.mechanic_jobs
  where id = p_job_id;

  if not found then
    raise exception 'Job not found: %', p_job_id;
  end if;

  case lower(p_action)
    when 'approve_quote', 'approve_budget', 'approve_estimate' then
      v_status_code := 'EN_CURSO';
      v_description := 'Customer approved the work via WhatsApp';
    when 'reject_quote', 'reject_budget', 'reject_estimate' then
      v_status_code := 'CANCELADO';
      v_description := 'Customer rejected the work via WhatsApp';
    when 'confirm_delivery' then
      v_status_code := 'ENTREGADO';
      v_description := 'Customer confirmed delivery via WhatsApp';
    when 'cancel_delivery' then
      v_status_code := 'FINALIZADO';
      v_description := 'Customer asked to keep the job open for delivery follow-up';
    else
      raise exception 'Unsupported WhatsApp job action: %', p_action;
  end case;

  select id into v_status_id
  from public.job_statuses
  where tenant_id = v_job.tenant_id
    and code = v_status_code
    and is_active = true
  order by sort_order
  limit 1;

  if v_status_id is null then
    raise exception 'Status % not found for tenant %', v_status_code, v_job.tenant_id;
  end if;

  update public.mechanic_jobs
  set status = v_status_code,
      status_id = v_status_id,
      approved_by_customer = case
        when lower(p_action) in ('approve_quote', 'approve_budget', 'approve_estimate') then true
        else approved_by_customer
      end,
      approved_at = case
        when lower(p_action) in ('approve_quote', 'approve_budget', 'approve_estimate') then coalesce(approved_at, now())
        else approved_at
      end,
      requires_approval = case
        when lower(p_action) in ('approve_quote', 'approve_budget', 'approve_estimate', 'reject_quote', 'reject_budget', 'reject_estimate') then false
        else requires_approval
      end,
      quotation_status = case
        when job_type = 'quotation' and lower(p_action) in ('approve_quote', 'approve_budget', 'approve_estimate') then 'approved'
        when job_type = 'quotation' and lower(p_action) in ('reject_quote', 'reject_budget', 'reject_estimate') then 'rejected'
        else quotation_status
      end,
      updated_at = now()
  where id = p_job_id;

  perform public.log_mechanic_job_timeline(
    p_job_id,
    'whatsapp_action',
    null,
    lower(p_action),
    v_description
  );

  return jsonb_build_object(
    'job_id', p_job_id,
    'action', lower(p_action),
    'status_code', v_status_code,
    'status_id', v_status_id,
    'external_message_id', p_external_message_id,
    'payload', p_payload
  );
end;
$$;


--
-- TOC entry 1946 (class 1255 OID 62219)
-- Name: auto_add_low_stock_to_purchase_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_add_low_stock_to_purchase_list() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_supplier_id uuid;
  v_supplier_name text;
  v_rotation_kpi numeric(5,2);
  v_avg_daily_consumption numeric(10,2);
  v_days_since_last_purchase integer;
  v_suggested_qty integer;
  v_priority numeric(5,2);
  v_lead_time_days integer;
  v_estimated_stockout_date timestamp with time zone;
  v_current_stock integer;
begin
  -- Sync inventory_qty to match stock_quantity (stock_quantity is source of truth)
  if NEW.stock_quantity != NEW.inventory_qty then
    NEW.inventory_qty := NEW.stock_quantity;
  end if;
  
  v_current_stock := coalesce(NEW.stock_quantity, NEW.inventory_qty, 0);
  
  -- AUTO-REMOVAL: If stock is now ABOVE minimum level, remove from pending list
  if v_current_stock > NEW.min_stock_level then
    delete from smart_purchase_list
    where product_id = NEW.id
    and status = 'pending'
    and tenant_id = NEW.tenant_id;
    
    if found then
      raise notice '🗑️ Auto-removed product % (%) from purchase list - stock restored to %', NEW.name, NEW.sku, v_current_stock;
    end if;
    
    return NEW;
  end if;
  
  -- AUTO-ADD: Trigger when stock is at or below minimum level
  if v_current_stock <= NEW.min_stock_level then
    
    -- Check if product is already in the purchase list with pending/ordered status
    if exists (
      select 1 from smart_purchase_list
      where product_id = NEW.id
      and status in ('pending', 'ordered')
      and tenant_id = NEW.tenant_id
    ) then
      -- Already in list, just update the current stock
      update smart_purchase_list
      set current_stock = v_current_stock,
          updated_at = now()
      where product_id = NEW.id
      and status in ('pending', 'ordered')
      and tenant_id = NEW.tenant_id;
      
      return NEW;
    end if;
    
    -- Get supplier info
    select s.id, s.name into v_supplier_id, v_supplier_name
    from suppliers s
    where s.tenant_id = NEW.tenant_id
    and s.is_active = true
    order by s.created_at asc
    limit 1;
    
    -- Calculate rotation KPI (sales per day over last 30 days)
    -- NOTE: sales_invoices stores items in JSONB 'items' column, not a separate table
    -- Use text comparison to avoid UUID casting errors with null/empty product_ids
    select 
      coalesce(sum((item->>'quantity')::numeric), 0)::numeric / 30.0
    into v_avg_daily_consumption
    from sales_invoices si,
         jsonb_array_elements(si.items) as item
    where item->>'product_id' = NEW.id::text
    and si.tenant_id = NEW.tenant_id
    and si.date >= now() - interval '30 days'
    and si.status in ('confirmed', 'paid');
    
    v_rotation_kpi := coalesce(v_avg_daily_consumption * 100, 0);
    
    -- Days since last purchase
    -- NOTE: purchase_invoices stores items in JSONB 'items' column
    -- Use text comparison to avoid UUID casting errors with null/empty product_ids
    select extract(day from now() - max(pi.date))::integer
    into v_days_since_last_purchase
    from purchase_invoices pi,
         jsonb_array_elements(pi.items) as item
    where item->>'product_id' = NEW.id::text
    and pi.tenant_id = NEW.tenant_id;
    
    v_days_since_last_purchase := coalesce(v_days_since_last_purchase, 999);
    
    -- Lead time (use 7 days default)
    v_lead_time_days := 7;
    
    -- Calculate suggested quantity
    v_suggested_qty := greatest(
      NEW.max_stock_level - v_current_stock,
      ceil(coalesce(v_avg_daily_consumption, 0.1) * v_lead_time_days * 1.5)::integer,
      1
    );
    
    -- Calculate priority (0-100 scale)
    v_priority := least(100, greatest(0,
      (case when v_current_stock = 0 then 50 else 0 end) +
      (case when v_current_stock <= NEW.min_stock_level * 0.5 then 25 else 0 end) +
      least(v_rotation_kpi, 25)
    ));
    
    -- Estimate stockout date
    if v_avg_daily_consumption > 0 then
      v_estimated_stockout_date := now() + (v_current_stock / v_avg_daily_consumption) * interval '1 day';
    end if;
    
    -- Insert into purchase list with CORRECT column name: suggested_quantity
    insert into smart_purchase_list (
      tenant_id,
      product_id,
      product_name,
      product_sku,
      supplier_id,
      supplier_name,
      suggested_quantity,  -- FIXED: was suggested_qty
      status,
      priority,
      rotation_kpi,
      days_since_last_purchase,
      current_stock,
      min_stock_level,
      avg_daily_consumption,
      lead_time_days,
      estimated_stockout_date,
      notes,
      added_date
    ) values (
      NEW.tenant_id,
      NEW.id,
      NEW.name,
      NEW.sku,
      v_supplier_id,
      v_supplier_name,
      v_suggested_qty,
      'pending',
      v_priority,
      v_rotation_kpi,
      v_days_since_last_purchase,
      v_current_stock,
      NEW.min_stock_level,
      v_avg_daily_consumption,
      v_lead_time_days,
      v_estimated_stockout_date,
      'Auto-added: stock at or below minimum level',
      now()
    );
    
    raise notice '✅ Auto-added product % (%) to purchase list with priority %', NEW.name, NEW.sku, v_priority;
  end if;
  
  return NEW;
end;
$$;


