  return OLD;
end;
$$;


--
-- TOC entry 1763 (class 1255 OID 83554)
-- Name: cleanup_old_backups(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_backups(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_keep_count int;
  v_auto_delete boolean;
  v_deleted_count int := 0;
  v_backup_ids uuid[];
begin
  -- Get retention settings
  select keep_last_n_backups, auto_delete_old 
  into v_keep_count, v_auto_delete
  from backup_schedules
  where tenant_id = p_tenant_id;
  
  if not found or not v_auto_delete then
    return jsonb_build_object('success', true, 'deleted_count', 0, 'message', 'Auto-delete disabled');
  end if;
  
  -- Get IDs of backups to delete (keep newest N, delete older)
  select array_agg(id) into v_backup_ids
  from (
    select id
    from database_backups
    where tenant_id = p_tenant_id
      and status = 'completed'
    order by created_at desc
    offset v_keep_count
  ) old_backups;
  
  if v_backup_ids is not null then
    delete from database_backups
    where id = any(v_backup_ids);
    
    get diagnostics v_deleted_count = row_count;
  end if;
  
  return jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count,
    'kept_count', v_keep_count
  );
end;
$$;


--
-- TOC entry 1506 (class 1255 OID 157875)
-- Name: confirm_invoice_approval(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_invoice_approval(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_customer_id uuid;
BEGIN
  -- Get invoice customer
  SELECT customer_id INTO v_customer_id
  FROM public.sales_invoices
  WHERE id = p_invoice_id;

  -- Check permissions (must be the customer or an admin/employee)
  -- Employees are checked via user_profiles usually, but here we focus on Customer approval
  IF v_customer_id != auth.uid() THEN
     -- Check if employee
     IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid()) THEN
        RAISE EXCEPTION 'Not authorized to approve this invoice';
     END IF;
  END IF;

  -- Update status
  UPDATE public.sales_invoices
  SET status = 'confirmed'
  WHERE id = p_invoice_id;
END;
$$;


--
-- TOC entry 1485 (class 1255 OID 136478)
-- Name: confirm_online_order_payment(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_online_order_payment(p_order_id uuid, p_payment_reference text DEFAULT NULL::text, p_payment_date timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_order record;
  v_invoice record;
  v_payment_method_id uuid;
  v_payment_id uuid;
begin
  -- Get order with tenant context
  select * into v_order
  from online_orders
  where id = p_order_id
    and tenant_id = public.user_tenant_id();
  
  if not found then
    raise exception 'Order not found or access denied: %', p_order_id;
  end if;
  
  if v_order.sales_invoice_id is null then
    raise exception 'Order has no invoice. Call process_online_order first.';
  end if;
  
  select * into v_invoice
  from sales_invoices
  where id = v_order.sales_invoice_id;
  
  if not found then
    raise exception 'Invoice not found: %', v_order.sales_invoice_id;
  end if;
  
  if v_invoice.status = 'paid' then
    raise notice 'Invoice already paid';
    return null;
  end if;
  
  -- Get payment method
  select id into v_payment_method_id
  from payment_methods
  where tenant_id = v_order.tenant_id
    and lower(code) = lower(coalesce(v_order.payment_method, 'transfer'))
    and is_active = true
  limit 1;
  
  if v_payment_method_id is null then
    select id into v_payment_method_id
    from payment_methods
    where tenant_id = v_order.tenant_id
      and lower(code) in ('transfer', 'transferencia', 'bank_transfer')
      and is_active = true
    limit 1;
  end if;
  
  if v_payment_method_id is null then
    raise exception 'No payment method found for tenant %', v_order.tenant_id;
  end if;
  
  -- Update invoice to confirmed
  update sales_invoices
  set 
    status = 'confirmed',
    updated_at = now()
  where id = v_invoice.id
    and status != 'paid';
  
  -- Create payment record
  -- FIX: Changed 'payment_date' to 'date' (correct column name in sales_payments)
  insert into sales_payments (
    tenant_id,
    invoice_id,
    invoice_reference,
    payment_method_id,
    amount,
    date,  -- FIX: was 'payment_date'
    reference,
    notes
  ) values (
    v_order.tenant_id,
    v_invoice.id,
    v_invoice.invoice_number,
    v_payment_method_id,
    v_order.total,
    p_payment_date,
    p_payment_reference,
    'Confirmación manual - Transferencia bancaria - Pedido #' || v_order.order_number
  )
  returning id into v_payment_id;
  
  -- Update order payment status
  update online_orders
  set 
    payment_status = 'paid',
    paid_at = p_payment_date,
    payment_reference = coalesce(p_payment_reference, payment_reference),
    updated_at = now()
  where id = p_order_id;
  
  raise notice 'Payment confirmed for order % (invoice %)', 
    v_order.order_number, v_invoice.invoice_number;
  
  return v_payment_id;
end;
$$;


--
-- TOC entry 1061 (class 1255 OID 175616)
-- Name: confirm_payroll_voucher(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_payroll_voucher(p_voucher_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  -- Get current status
  SELECT status INTO v_status
  FROM public.payroll_vouchers
  WHERE id = p_voucher_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payroll voucher not found';
  END IF;
  
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'Only draft vouchers can be confirmed. Current status: %', v_status;
  END IF;
  
  -- Update to confirmed
  UPDATE public.payroll_vouchers
  SET status = 'confirmed',
      updated_at = now()
  WHERE id = p_voucher_id;
  
  RETURN true;
END;
$$;


--
-- TOC entry 1996 (class 1255 OID 26284)
-- Name: consume_mechanic_job_inventory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_mechanic_job_inventory(p_job_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_reference text;
  v_item record;
  v_job_number text;
begin
  if p_job_id is null then
    return;
  end if;

  -- Get job number
  select job_number into v_job_number
  from mechanic_jobs
  where id = p_job_id;

  v_reference := concat('mechanic_job:', p_job_id::text);

  -- Check if inventory already consumed
  if exists (
    select 1 from stock_movements
    where reference = v_reference and type = 'OUT'
  ) then
    raise notice 'Inventory already consumed for job %', v_job_number;
    return;
  end if;

  -- Consume inventory for each item
  for v_item in
    select 
      product_id,
      product_name,
      quantity
    from mechanic_job_items
    where job_id = p_job_id
      and product_id is not null
  loop
    -- Create stock movement
    insert into stock_movements (
      product_id,
      type,
      quantity,
      reference,
      notes,
      date,
      created_at
    ) values (
      v_item.product_id,
      'OUT',
      v_item.quantity,
      v_reference,
      'Mechanic Job ' || v_job_number || ': ' || v_item.product_name,
      now(),
      now()
    );

    -- Update product inventory
    update products
    set 
      inventory_qty = inventory_qty - v_item.quantity::integer,
      stock_quantity = stock_quantity - v_item.quantity::integer,
      updated_at = now()
    where id = v_item.product_id;

    raise notice 'Consumed % x % for job %', v_item.quantity, v_item.product_name, v_job_number;
  end loop;
end;
$$;


