--
-- TOC entry 1367 (class 1255 OID 19391)
-- Name: consume_sales_invoice_inventory(public.sales_invoices); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_sales_invoice_inventory(p_invoice public.sales_invoices) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item record;
  v_resolved_product_id uuid;
  v_quantity_int integer;
  v_status text;
  v_reference text;
  v_net_quantity integer;
  v_items_count integer;
  v_is_set boolean;
  v_component record;
  v_qty_to_deduct integer;
  v_set_name text;
begin
  perform set_config('app.skip_stock_adjustment_trigger', 'true', true);

  if p_invoice.id is null then
    raise notice 'consume_sales_invoice_inventory: invoice ID is null';
    return;
  end if;

  v_status := lower(coalesce(p_invoice.status, 'draft'));

  if v_status = any (array['draft','borrador','cancelled','cancelado','cancelada','anulado','anulada']) then
    return;
  end if;

  v_reference := concat('sales_invoice:', p_invoice.id::text);
  select coalesce(sum(quantity), 0)::integer
    into v_net_quantity
    from public.stock_movements
   where reference = v_reference;

  if v_net_quantity < 0 then
    return;
  end if;

  select jsonb_array_length(coalesce(p_invoice.items, '[]'::jsonb))
    into v_items_count;

  for v_item in
    select
      nullif(item->>'product_id', '')::uuid as product_id,
      (item->>'product_sku')::text as product_sku,
      coalesce(nullif(item->>'purchase_treatment', ''), 'inventory')::text as purchase_treatment,
      (item->>'quantity')::numeric as quantity
    from jsonb_array_elements(coalesce(p_invoice.items, '[]'::jsonb)) item
  loop
    v_resolved_product_id := v_item.product_id;

    if v_resolved_product_id is null and v_item.product_sku is not null and v_item.product_sku != '' then
      select id
        into v_resolved_product_id
        from public.products
       where sku = v_item.product_sku
       limit 1;
    end if;

    v_quantity_int := coalesce(v_item.quantity::int, 0);

    if v_resolved_product_id is null or v_quantity_int <= 0 then
      continue;
    end if;

    if v_item.purchase_treatment = 'workshop_consumable' then
      continue;
    end if;

    select is_set, name
      into v_is_set, v_set_name
      from public.products
     where id = v_resolved_product_id
       and coalesce(track_stock, true) = true;

    if not found then
      continue;
    end if;

    if v_is_set then
      for v_component in
        select component_product_id, quantity_in_set
          from public.product_set_components
         where set_product_id = v_resolved_product_id
      loop
        v_qty_to_deduct := v_quantity_int * v_component.quantity_in_set;

        update public.products
           set inventory_qty = coalesce(inventory_qty, 0) - v_qty_to_deduct,
               stock_quantity = greatest(coalesce(stock_quantity, 0) - v_qty_to_deduct, 0),
               updated_at = now()
         where id = v_component.component_product_id;

        if found then
          insert into public.stock_movements (
            tenant_id, id, product_id, warehouse_id, type, movement_type, quantity,
            reference, notes, date, created_at, updated_at
          ) values (
            p_invoice.tenant_id,
            gen_random_uuid(),
            v_component.component_product_id,
            null,
            'OUT',
            'sales_invoice_component',
            -v_qty_to_deduct,
            v_reference,
            format(
              'Salida por venta de Set "%s" (Factura %s)',
              v_set_name,
              coalesce(nullif(p_invoice.invoice_number, ''), p_invoice.id::text)
            ),
            coalesce(p_invoice.date, now()),
            now(),
            now()
          );
        end if;
      end loop;
    else
      update public.products
         set inventory_qty = coalesce(inventory_qty, 0) - v_quantity_int,
             stock_quantity = greatest(coalesce(stock_quantity, 0) - v_quantity_int, 0),
             updated_at = now()
       where id = v_resolved_product_id
         and coalesce(is_service, false) = false
         and coalesce(track_stock, true) = true;

      if found then
        insert into public.stock_movements (
          tenant_id, id, product_id, warehouse_id, type, movement_type, quantity,
          reference, notes, date, created_at, updated_at
        ) values (
          p_invoice.tenant_id,
          gen_random_uuid(),
          v_resolved_product_id,
          null,
          'OUT',
          'sale',
          -v_quantity_int,
          v_reference,
          concat('Salida por venta (Factura ', coalesce(nullif(p_invoice.invoice_number, ''), p_invoice.id::text), ')'),
          coalesce(p_invoice.date, now()),
          now(),
          now()
        );
      end if;
    end if;
  end loop;

  raise notice 'consume_sales_invoice_inventory: completed for invoice %', p_invoice.id;
end;
$$;


--
-- TOC entry 1396 (class 1255 OID 237978)
-- Name: convert_product_inventory_to_non_stock(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_product_inventory_to_non_stock(p_product_id uuid, p_target_purchase_treatment text DEFAULT 'workshop_consumable'::text, p_target_product_type text DEFAULT 'product'::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_product public.products;
  v_target_purchase_treatment text := coalesce(nullif(p_target_purchase_treatment, ''), 'inventory');
  v_target_product_type text := coalesce(nullif(p_target_product_type, ''), 'product');
  v_existing_stock integer := 0;
  v_inventory_value numeric(14,2) := 0;
  v_effective_reason text;
  v_description text;
  v_reference text;
  v_inventory_account_id uuid;
  v_workshop_consumables_account_id uuid;
  v_entry_id uuid;
  v_original_state jsonb;
  v_original_product_snapshot jsonb;
begin
  if p_product_id is null then
    raise exception 'Product ID is required';
  end if;

  if v_target_purchase_treatment not in ('inventory', 'workshop_consumable') then
    raise exception 'Invalid target purchase_treatment: %', v_target_purchase_treatment;
  end if;

  if v_target_product_type not in ('product', 'service') then
    raise exception 'Invalid target product_type: %', v_target_product_type;
  end if;

  select *
    into v_product
    from public.products
   where id = p_product_id
     and tenant_id = public.user_tenant_id()
   for update;

  if not found then
    raise exception 'Product not found or not accessible';
  end if;

  if coalesce(v_product.product_type, 'product') = 'service'
     or coalesce(v_product.purchase_treatment, 'inventory') <> 'inventory'
     or coalesce(v_product.track_stock, true) = false then
    raise exception 'Product % is not currently a stock-tracked inventory item', v_product.name;
  end if;

  if v_target_product_type = 'product'
     and v_target_purchase_treatment = 'inventory' then
    raise exception 'Target state still tracks inventory; conversion is not required';
  end if;

  v_existing_stock := greatest(
    coalesce(v_product.inventory_qty, 0),
    coalesce(v_product.stock_quantity, 0)
  );

  if v_existing_stock <= 0 then
    raise exception 'Product % has no stock to convert', v_product.name;
  end if;

  v_inventory_value := round(v_existing_stock * greatest(coalesce(v_product.cost, 0), 0), 2);
  v_effective_reason := coalesce(
    nullif(trim(p_reason), ''),
    case
      when v_target_product_type = 'service' then 'Conversión de inventario a servicio'
      else 'Conversión de inventario a consumible de taller'
    end
  );
  v_description := format('%s - %s', v_effective_reason, v_product.name);
  v_reference := format('product_conversion:%s:%s', v_product.id, extract(epoch from clock_timestamp())::bigint);
  v_original_state := jsonb_build_object(
    'purchase_treatment', coalesce(v_product.purchase_treatment, 'inventory'),
    'product_type', coalesce(v_product.product_type, 'product'),
    'track_stock', coalesce(v_product.track_stock, true),
    'inventory_qty', coalesce(v_product.inventory_qty, 0),
    'stock_quantity', coalesce(v_product.stock_quantity, 0),
    'min_stock_level', coalesce(v_product.min_stock_level, 0),
    'max_stock_level', coalesce(v_product.max_stock_level, 0)
  );
  v_original_product_snapshot := to_jsonb(v_product);

  perform set_config('app.skip_stock_adjustment_trigger', 'true', true);

  update public.products
     set inventory_qty = 0,
         stock_quantity = 0,
         updated_at = now()
   where id = v_product.id;

  insert into public.stock_adjustments (
    tenant_id,
    product_id,
    adjustment_type,
    quantity,
    stock_before,
    stock_after,
    reason,
    reference,
    created_by,
    created_at
  ) values (
    v_product.tenant_id,
    v_product.id,
    'correction',
    -v_existing_stock,
    v_existing_stock,
    0,
    v_effective_reason,
    v_reference,
    auth.uid(),
    now()
  );

  if v_inventory_value > 0 then
    v_inventory_account_id := public.ensure_account(
      v_product.tenant_id,
      '1105',
      'Inventarios',
      'asset',
      'currentAsset',
      'Valor del inventario de productos',
      null
    );

    v_workshop_consumables_account_id := public.ensure_account(
      v_product.tenant_id,
      '5101',
      'Consumibles de Taller',
      'expense',
      'costOfGoodsSold',
      'Materiales y consumibles de uso rápido aplicados directamente en el taller',
      null
    );

    v_entry_id := gen_random_uuid();

    insert into public.journal_entries (
      id,
      tenant_id,
      entry_number,
      entry_date,
      description,
      type,
      source_module,
      source_reference,
      status,
      total_debit,
      total_credit,
      created_at,
      updated_at
    ) values (
      v_entry_id,
      v_product.tenant_id,
      public.get_next_document_number(v_product.tenant_id, 'journal_entry'),
      now(),
      v_description,
      'adjustment',
      'product_conversion',
      v_product.id::text,
      'posted',
      v_inventory_value,
      v_inventory_value,
      now(),
      now()
    );

    insert into public.journal_lines (
      id,
      entry_id,
      account_id,
      tenant_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_entry_id,
      v_workshop_consumables_account_id,
      v_product.tenant_id,
      '5101',
      'Consumibles de Taller',
      v_description,
      v_inventory_value,
      0,
      now(),
      now()
    );

    insert into public.journal_lines (
      id,
      entry_id,
      account_id,
      tenant_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_entry_id,
      v_inventory_account_id,
      v_product.tenant_id,
      '1105',
      'Inventarios',
      v_description,
      0,
      v_inventory_value,
      now(),
      now()
    );
  end if;

  update public.products
     set purchase_treatment = v_target_purchase_treatment,
         product_type = v_target_product_type,
         updated_at = now()
   where id = v_product.id
   returning * into v_product;

  insert into public.user_activity_log (
    tenant_id,
    user_id,
    action,
    details,
    performed_by,
    created_at
  ) values (
    v_product.tenant_id,
    auth.uid(),
    'product_conversion',
    jsonb_build_object(
      'product_id', v_product.id,
      'product_name', v_product.name,
      'conversion_reference', v_reference,
      'conversion_reason', v_effective_reason,
      'target_purchase_treatment', v_target_purchase_treatment,
      'target_product_type', v_target_product_type,
      'converted_quantity', v_existing_stock,
      'inventory_value', v_inventory_value,
      'journal_entry_id', v_entry_id,
      'original_state', v_original_state,
      'original_product_snapshot', v_original_product_snapshot,
      'converted_state', jsonb_build_object(
        'purchase_treatment', coalesce(v_product.purchase_treatment, 'inventory'),
        'product_type', coalesce(v_product.product_type, 'product'),
        'track_stock', coalesce(v_product.track_stock, true),
        'inventory_qty', coalesce(v_product.inventory_qty, 0),
        'stock_quantity', coalesce(v_product.stock_quantity, 0),
        'min_stock_level', coalesce(v_product.min_stock_level, 0),
        'max_stock_level', coalesce(v_product.max_stock_level, 0)
      ),
      'restored', false
    ),
    auth.uid(),
    now()
  );

  perform set_config('app.skip_stock_adjustment_trigger', '', true);

  return jsonb_build_object(
    'product', to_jsonb(v_product),
    'converted_quantity', v_existing_stock,
    'inventory_value', v_inventory_value,
    'reference', v_reference,
    'journal_entry_id', v_entry_id
  );
exception
  when others then
    perform set_config('app.skip_stock_adjustment_trigger', '', true);
    raise;
end;
$$;


--
-- TOC entry 1756 (class 1255 OID 102073)
-- Name: create_adhoc_item_for_task(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_adhoc_item_for_task(p_task_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_task record;
  v_item_id uuid;
  v_syncing_flag text;
begin
  -- Prevent circular sync
  v_syncing_flag := current_setting('app.syncing_task_to_item', true);
  if v_syncing_flag = 'true' then
    raise notice 'create_adhoc_item_for_task: skipping due to circular sync prevention';
    return null;
  end if;
  
  -- Get task details
  select * into v_task
  from mechanic_job_tasks
  where id = p_task_id;
  
  if not found or not v_task.is_adhoc or v_task.adhoc_price is null then
    return null;
  end if;
  
  -- Check if item already exists
  if v_task.adhoc_item_id is not null then
    return v_task.adhoc_item_id;
  end if;
  
  -- Set sync flag
  perform pg_catalog.set_config('app.syncing_task_to_item', 'true', true);
  
  -- Create mechanic_job_item
  insert into mechanic_job_items (
    tenant_id,
    job_id,
    product_name,
    quantity,
    unit_price,
    total_price
  ) values (
    v_task.tenant_id,
    v_task.job_id,
    'Ad-hoc: ' || v_task.task_name,
    1,
    v_task.adhoc_price,
    v_task.adhoc_price
  )
  returning id into v_item_id;
  
  -- Link task to item
  update mechanic_job_tasks
  set adhoc_item_id = v_item_id
  where id = p_task_id;
  
  -- Clear sync flag
  perform pg_catalog.set_config('app.syncing_task_to_item', '', true);
  
  raise notice 'Created ad-hoc item % for task %', v_item_id, p_task_id;
  return v_item_id;
end;
$$;


--
-- TOC entry 1958 (class 1255 OID 83549)
-- Name: create_backup(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_backup(p_tenant_id uuid, p_backup_name text, p_backup_type text DEFAULT 'manual'::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_backup_id uuid;
  v_backup_data jsonb;
  v_summary jsonb;
  v_product_count int;
  v_product_category_count int;
  v_customer_count int;
  v_supplier_count int;
  v_sales_invoice_count int;
  v_purchase_invoice_count int;
  v_employee_count int;
  v_journal_entry_count int;
  v_mechanic_job_count int;
  v_bike_count int;
  v_product_brand_count int;
  v_bike_brand_count int;
  v_bike_model_count int;
  v_online_order_count int;
  v_website_banner_count int;
  v_backup_size bigint;
begin
  -- Collect summary statistics
  select count(*) into v_product_count from products where tenant_id = p_tenant_id;
  select count(*) into v_product_category_count from product_categories where tenant_id = p_tenant_id;
  select count(*) into v_customer_count from customers where tenant_id = p_tenant_id;
  select count(*) into v_supplier_count from suppliers where tenant_id = p_tenant_id;
  select count(*) into v_sales_invoice_count from sales_invoices where tenant_id = p_tenant_id;
  select count(*) into v_purchase_invoice_count from purchase_invoices where tenant_id = p_tenant_id;
  select count(*) into v_employee_count from employees where tenant_id = p_tenant_id;
  select count(*) into v_journal_entry_count from journal_entries where tenant_id = p_tenant_id;
  select count(*) into v_mechanic_job_count from mechanic_jobs where tenant_id = p_tenant_id;
  select count(*) into v_bike_count from bikes where tenant_id = p_tenant_id;
  select count(*) into v_product_brand_count from product_brands where tenant_id = p_tenant_id;
  select count(*) into v_bike_brand_count from bike_brands where tenant_id = p_tenant_id;
  select count(*) into v_bike_model_count from bike_models where tenant_id = p_tenant_id;
  select count(*) into v_online_order_count from online_orders where tenant_id = p_tenant_id;
  select count(*) into v_website_banner_count from website_banners where tenant_id = p_tenant_id;
  
  -- Build summary object
  v_summary := jsonb_build_object(
    'products', v_product_count,
    'product_categories', v_product_category_count,
    'customers', v_customer_count,
    'suppliers', v_supplier_count,
    'sales_invoices', v_sales_invoice_count,
    'purchase_invoices', v_purchase_invoice_count,
    'employees', v_employee_count,
    'journal_entries', v_journal_entry_count,
    'mechanic_jobs', v_mechanic_job_count,
    'bikes', v_bike_count,
    'product_brands', v_product_brand_count,
    'bike_brands', v_bike_brand_count,
    'bike_models', v_bike_model_count,
    'online_orders', v_online_order_count,
    'website_banners', v_website_banner_count,
    'captured_at', now()
  );
  
  -- Collect backup data (all tenant tables)
  v_backup_data := jsonb_build_object(
    'products', (select jsonb_agg(to_jsonb(t.*)) from products t where tenant_id = p_tenant_id),
    'product_categories', (select jsonb_agg(to_jsonb(t.*)) from product_categories t where tenant_id = p_tenant_id),
    'customers', (select jsonb_agg(to_jsonb(t.*)) from customers t where tenant_id = p_tenant_id),
    'suppliers', (select jsonb_agg(to_jsonb(t.*)) from suppliers t where tenant_id = p_tenant_id),
    'sales_invoices', (select jsonb_agg(to_jsonb(t.*)) from sales_invoices t where tenant_id = p_tenant_id),
    'sales_payments', (select jsonb_agg(to_jsonb(t.*)) from sales_payments t where tenant_id = p_tenant_id),
    'purchase_invoices', (select jsonb_agg(to_jsonb(t.*)) from purchase_invoices t where tenant_id = p_tenant_id),
    'purchase_payments', (select jsonb_agg(to_jsonb(t.*)) from purchase_payments t where tenant_id = p_tenant_id),
    'employees', (select jsonb_agg(to_jsonb(t.*)) from employees t where tenant_id = p_tenant_id),
    'employee_contracts', (select jsonb_agg(to_jsonb(t.*)) from employee_contracts t where tenant_id = p_tenant_id),
    'attendance_records', (select jsonb_agg(to_jsonb(t.*)) from attendance_records t where tenant_id = p_tenant_id),
    'accounts', (select jsonb_agg(to_jsonb(t.*)) from accounts t where tenant_id = p_tenant_id),
    'journal_entries', (select jsonb_agg(to_jsonb(t.*)) from journal_entries t where tenant_id = p_tenant_id),
    'journal_lines', (select jsonb_agg(to_jsonb(t.*)) from journal_lines t where entry_id in (select id from journal_entries where tenant_id = p_tenant_id)),
    'stock_movements', (select jsonb_agg(to_jsonb(t.*)) from stock_movements t where tenant_id = p_tenant_id),
    'company_settings', (select jsonb_agg(to_jsonb(t.*)) from company_settings t where tenant_id = p_tenant_id),
    'payment_methods', (select jsonb_agg(to_jsonb(t.*)) from payment_methods t where tenant_id = p_tenant_id),
    'bikes', (select jsonb_agg(to_jsonb(t.*)) from bikes t where tenant_id = p_tenant_id),
    'mechanic_jobs', (select jsonb_agg(to_jsonb(t.*)) from mechanic_jobs t where tenant_id = p_tenant_id),
    'mechanic_job_items', (select jsonb_agg(to_jsonb(t.*)) from mechanic_job_items t where job_id in (select id from mechanic_jobs where tenant_id = p_tenant_id)),
    'mechanic_job_timeline', (select jsonb_agg(to_jsonb(t.*)) from mechanic_job_timeline t where job_id in (select id from mechanic_jobs where tenant_id = p_tenant_id)),
    'product_brands', (select jsonb_agg(to_jsonb(t.*)) from product_brands t where tenant_id = p_tenant_id),
    'bike_brands', (select jsonb_agg(to_jsonb(t.*)) from bike_brands t where tenant_id = p_tenant_id),
    'bike_models', (select jsonb_agg(to_jsonb(t.*)) from bike_models t where tenant_id = p_tenant_id),
    'website_settings', (select jsonb_agg(to_jsonb(t.*)) from website_settings t where tenant_id = p_tenant_id),
    'website_banners', (select jsonb_agg(to_jsonb(t.*)) from website_banners t where tenant_id = p_tenant_id),
    'website_content', (select jsonb_agg(to_jsonb(t.*)) from website_content t where tenant_id = p_tenant_id),
    'website_blocks', (select jsonb_agg(to_jsonb(t.*)) from website_blocks t where tenant_id = p_tenant_id),
    'featured_products', (select jsonb_agg(to_jsonb(t.*)) from featured_products t where tenant_id = p_tenant_id),
    'online_orders', (select jsonb_agg(to_jsonb(t.*)) from online_orders t where tenant_id = p_tenant_id),
    'online_order_items', (select jsonb_agg(to_jsonb(t.*)) from online_order_items t where order_id in (select id from online_orders where tenant_id = p_tenant_id))
  );
  
  -- Calculate backup size
  v_backup_size := length(v_backup_data::text);
  
  -- Insert backup record
  insert into database_backups (
    tenant_id,
    backup_name,
    backup_type,
    status,
    backup_data,
    summary,
    backup_size_bytes,
    notes,
    created_by
  ) values (
    p_tenant_id,
    p_backup_name,
    p_backup_type,
    'completed',
    v_backup_data,
    v_summary,
    v_backup_size,
    p_notes,
    auth.uid()
  ) returning id into v_backup_id;
  
  return jsonb_build_object(
    'success', true,
    'backup_id', v_backup_id,
    'summary', v_summary,
    'size_mb', round((v_backup_size / 1024.0 / 1024.0)::numeric, 2)
  );
exception
  when others then
    -- Log failed backup
    insert into database_backups (
      tenant_id,
      backup_name,
      backup_type,
      status,
      backup_data,
      error_message,
      created_by
    ) values (
      p_tenant_id,
      p_backup_name,
      p_backup_type,
      'failed',
      '{}'::jsonb,
      SQLERRM,
      auth.uid()
    );
    
    return jsonb_build_object(
      'success', false,
      'error', SQLERRM
    );
end;
$$;


--
-- TOC entry 1111 (class 1255 OID 161412)
-- Name: create_employee_salary_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_employee_salary_account() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_parent_account_id UUID;
  v_next_code TEXT;
  v_new_account_id UUID;
  v_child_count INTEGER;
BEGIN
  -- Find the 6101 parent account for this tenant (Sueldos y Salarios)
  SELECT id INTO v_parent_account_id
  FROM accounts
  WHERE tenant_id = NEW.tenant_id
    AND code = '6101';
  
  -- If not found, we can't create a sub-account, so just return
  IF v_parent_account_id IS NULL THEN
    RAISE NOTICE '⚠️ Account 6101 not found for tenant %, skipping salary account creation', NEW.tenant_id;
    RETURN NEW;
  END IF;
  
  -- Calculate next sub-account code (6101-01, 6101-02, etc.)
  SELECT COUNT(*) INTO v_child_count
  FROM accounts
  WHERE tenant_id = NEW.tenant_id
    AND parent_id = v_parent_account_id;
  
  v_next_code := '6101-' || LPAD((v_child_count + 1)::TEXT, 2, '0');
  
  -- Create the salary sub-account
  INSERT INTO accounts (
    tenant_id,
    code,
    name,
    type,
    category,
    parent_id,
    description
  ) VALUES (
    NEW.tenant_id,
    v_next_code,
    'Salario - ' || NEW.first_name || ' ' || NEW.last_name,
    'expense',
    'operatingExpense',
    v_parent_account_id,
    'Cuenta de salario para empleado: ' || NEW.first_name || ' ' || NEW.last_name
  )
  RETURNING id INTO v_new_account_id;
  
  -- Update the employee with the new account reference
  NEW.salary_account_id := v_new_account_id;
  
  RAISE NOTICE '✅ Created salary account % for employee %', v_next_code, NEW.first_name || ' ' || NEW.last_name;
  
  RETURN NEW;
END;
$$;


--
-- TOC entry 909 (class 1255 OID 32705)
-- Name: create_expense_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_expense_journal_entry(p_expense_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_expense record;
  v_entry_id uuid := gen_random_uuid();
  v_exists boolean;
  v_liability_account_id uuid;
  v_liability_account_code text;
  v_liability_account_name text;
  v_tax_account_id uuid;
  v_tax_account_code text := '2120';
  v_tax_account_name text := 'IVA Crédito Fiscal';
  v_cash_account record;
  v_total numeric(14,2);
  v_tax_total numeric(14,2);
  v_credit_account_id uuid;
  v_credit_account_code text;
  v_credit_account_name text;
  v_description text;
  v_supplier text;
  v_document text;
  v_line record;
  v_line_count integer := 0;
  v_default_account record;
  v_is_payroll boolean := false;
begin
  select e.*
    into v_expense
    from public.expenses e
   where e.id = p_expense_id;

  if not found then
    return;
  end if;

  if lower(coalesce(v_expense.posting_status, 'draft')) <> 'posted' then
    return;
  end if;

  v_total := coalesce(v_expense.total_amount, 0);

  if v_total = 0 then
    return;
  end if;

  v_is_payroll := (
    v_expense.notes like 'Pago de salario%'
    or v_expense.notes like 'Salario:%'
    or v_expense.reference like 'Semana %'
  );

  select exists (
           select 1
             from public.journal_entries
            where source_module = 'expenses'
              and source_reference = v_expense.expense_number
         )
    into v_exists;

  if v_exists then
    perform public.delete_expense_journal_entry(p_expense_id);
  end if;

  if v_is_payroll then
    v_liability_account_code := '2106';
    v_liability_account_name := 'Sueldos por Pagar';
    v_liability_account_id := public.ensure_account(
      v_expense.tenant_id,
      v_liability_account_code,
      v_liability_account_name,
      'liability',
      'currentLiability',
      'Obligaciones pendientes de pago por remuneraciones al personal',
      null
    );
  else
    v_liability_account_code := '2105';
    v_liability_account_name := 'Cuentas por Pagar - Gastos';
    v_liability_account_id := coalesce(
      v_expense.liability_account_id,
      public.ensure_account(
        v_expense.tenant_id,
        v_liability_account_code,
        v_liability_account_name,
        'liability',
        'currentLiability',
        'Obligaciones por gastos pendientes de pago',
        null
      )
    );
  end if;

  select null::uuid as id, null::text as code, null::text as name
    into v_cash_account;

  if v_expense.payment_account_id is not null then
    select a.id, a.code, a.name
      into v_cash_account
      from public.accounts a
     where a.id = v_expense.payment_account_id;
  elsif v_expense.payment_method_id is not null then
    select a.id, a.code, a.name
      into v_cash_account
      from public.payment_methods pm
      join public.accounts a on a.id = pm.account_id
     where pm.id = v_expense.payment_method_id;
  end if;

  v_tax_account_id := public.ensure_account(
    v_expense.tenant_id,
    v_tax_account_code,
    v_tax_account_name,
    'asset',
    'currentAsset',
    'Crédito fiscal IVA soportado en compras',
    null
  );

  v_supplier := coalesce(nullif(v_expense.supplier_name, ''), 'Proveedor');
  v_document := coalesce(nullif(v_expense.document_number, ''), v_expense.expense_number);
  v_description := format('Gasto %s - %s', v_document, v_supplier);

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_expense.tenant_id,
    public.get_next_document_number(v_expense.tenant_id, 'journal_entry'),
    coalesce(v_expense.issue_date, now()),
    v_description,
    case when v_is_payroll then 'payroll' else 'purchase' end,
    'expenses',
    v_expense.expense_number,
    'posted',
    v_total,
    v_total,
    now(),
    now()
  );

  for v_line in
    select el.*
      from public.expense_lines el
     where el.expense_id = v_expense.id
     order by el.line_index, el.created_at
  loop
    v_line_count := v_line_count + 1;
    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_expense.tenant_id,
      v_entry_id,
      v_line.account_id,
      v_line.account_code,
      v_line.account_name,
      coalesce(nullif(v_line.description, ''), v_description),
      coalesce(v_line.subtotal, 0),
      0,
      now(),
      now()
    );
  end loop;

  if v_line_count = 0 then
    if v_expense.category_id is not null then
      select a.id, a.code, a.name
        into v_default_account
        from public.expense_categories ec
        join public.accounts a on a.id = ec.default_account_id
       where ec.id = v_expense.category_id;
    end if;

    if not found or v_default_account.id is null then
      select public.ensure_account(
               v_expense.tenant_id,
               '5200',
               'Gastos Generales',
               'expense',
               'operatingExpense',
               'Gastos generales y administrativos',
               null
             ) as id,
             '5200' as code,
             'Gastos Generales' as name
        into v_default_account;
    end if;

    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_expense.tenant_id,
      v_entry_id,
      v_default_account.id,
      v_default_account.code,
      v_default_account.name,
      v_description,
      coalesce(v_expense.subtotal, v_total - coalesce(v_expense.tax_amount, 0)),
      0,
      now(),
      now()
    );
  end if;

  v_tax_total := coalesce(v_expense.tax_amount, 0);
  if v_tax_total <> 0 then
    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_expense.tenant_id,
      v_entry_id,
      v_tax_account_id,
      v_tax_account_code,
      v_tax_account_name,
      format('IVA crédito gasto %s', v_document),
      v_tax_total,
      0,
      now(),
      now()
    );
  end if;

  if v_is_payroll then
    v_credit_account_id := v_liability_account_id;
    v_credit_account_code := v_liability_account_code;
    v_credit_account_name := v_liability_account_name;
  elsif lower(coalesce(v_expense.payment_status, 'pending')) = 'paid'
     and coalesce(v_expense.balance, 0) <= 0.01
     and v_cash_account.id is not null then
    v_credit_account_id := v_cash_account.id;
    v_credit_account_code := v_cash_account.code;
    v_credit_account_name := v_cash_account.name;
  else
    v_credit_account_id := v_liability_account_id;
    select code, name
      into v_credit_account_code, v_credit_account_name
      from public.accounts
     where id = v_credit_account_id;
  end if;

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_expense.tenant_id,
    v_entry_id,
    v_credit_account_id,
    v_credit_account_code,
    v_credit_account_name,
    v_description,
    0,
    v_total,
    now(),
    now()
  );
end;
$$;


--
-- TOC entry 1964 (class 1255 OID 32708)
-- Name: create_expense_payment_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_expense_payment_journal_entry(p_payment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_payment record;
  v_expense record;
  v_entry_id uuid := gen_random_uuid();
  v_exists boolean;
  v_liability_account_id uuid;
  v_liability_code text;
  v_liability_name text;
  v_cash_account record;
  v_description text;
  v_is_payroll boolean := false;
begin
  select ep.*
    into v_payment
    from public.expense_payments ep
   where ep.id = p_payment_id;

  if not found then
    return;
  end if;

  select e.*
    into v_expense
    from public.expenses e
   where e.id = v_payment.expense_id;

  if not found then
    return;
  end if;

  if lower(coalesce(v_expense.posting_status, 'draft')) <> 'posted' then
    return;
  end if;

  if coalesce(v_payment.amount, 0) = 0 then
    return;
  end if;

  v_is_payroll := (
    v_expense.notes like 'Pago de salario%'
    or v_expense.notes like 'Salario:%'
    or v_expense.reference like 'Semana %'
  );

  select exists (
           select 1
             from public.journal_entries
            where source_module = 'expense_payments'
              and source_reference = v_payment.id::text
         )
    into v_exists;

  if v_exists then
    perform public.delete_expense_payment_journal_entry(v_payment.id);
  end if;

  if v_is_payroll then
    v_liability_code := '2106';
    v_liability_name := 'Sueldos por Pagar';
  else
    v_liability_code := '2105';
    v_liability_name := 'Cuentas por Pagar - Gastos';
  end if;

  v_liability_account_id := coalesce(
    v_expense.liability_account_id,
    public.ensure_account(
      v_expense.tenant_id,
      v_liability_code,
      v_liability_name,
      'liability',
      'currentLiability',
      'Obligaciones por gastos',
      null
    )
  );

  if v_payment.payment_account_id is not null then
    select a.id, a.code, a.name
      into v_cash_account
      from public.accounts a
     where a.id = v_payment.payment_account_id;
  elsif v_payment.payment_method_id is not null then
    select a.id, a.code, a.name
      into v_cash_account
      from public.payment_methods pm
      join public.accounts a on a.id = pm.account_id
     where pm.id = v_payment.payment_method_id;
  end if;

  if v_cash_account.id is null then
    select a.id, a.code, a.name
      into v_cash_account
      from public.accounts a
     where a.code = '1101'
     limit 1;
  end if;

  v_description := format('Pago gasto %s', coalesce(v_expense.expense_number, v_expense.id::text));

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_expense.tenant_id,
    public.get_next_document_number(v_expense.tenant_id, 'journal_entry'),
    coalesce(v_payment.payment_date, now()),
    v_description,
    'payment',
    'expense_payments',
    v_payment.id::text,
    'posted',
    v_payment.amount,
    v_payment.amount,
    now(),
    now()
  );

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_expense.tenant_id,
    v_entry_id,
    v_liability_account_id,
    (select code from public.accounts where id = v_liability_account_id),
    (select name from public.accounts where id = v_liability_account_id),
    v_description,
    v_payment.amount,
    0,
    now(),
    now()
  );

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_expense.tenant_id,
    v_entry_id,
    v_cash_account.id,
    v_cash_account.code,
    v_cash_account.name,
    v_description,
    0,
    v_payment.amount,
    now(),
    now()
  );
end;
$$;


--
-- TOC entry 1793 (class 1255 OID 26496)
-- Name: create_invoice_from_mechanic_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_from_mechanic_job(p_job_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_job record;
  v_customer record;
  v_invoice_id uuid;
  v_invoice_number text;
  v_invoice_date timestamp with time zone;
  v_subtotal numeric(12,2) := 0;
  v_iva numeric(12,2) := 0;
  v_total numeric(12,2) := 0;
  v_items jsonb := '[]'::jsonb;
  v_item_counter integer := 0;
  v_job_item record;
  v_tenant_id uuid;
begin
  -- Get job details
  select * into v_job
  from public.mechanic_jobs
  where id = p_job_id;

  if not found then
    raise notice 'Job % not found', p_job_id;
    return null;
  end if;

  v_tenant_id := v_job.tenant_id;

  -- Ensure job totals are current before creating invoice
  perform public.recalculate_mechanic_job_costs(p_job_id);

  -- If invoice already exists, refresh it from the current job items and return it
  if v_job.invoice_id is not null then
    perform public.sync_job_to_invoice(p_job_id);
    raise notice 'Job % already has invoice %, synced existing invoice', p_job_id, v_job.invoice_id;
    return v_job.invoice_id;
  end if;

  -- Get customer details
  select * into v_customer
  from public.customers
  where id = v_job.customer_id;

  if not found then
    raise notice 'Customer % not found for job %', v_job.customer_id, p_job_id;
    return null;
  end if;

  -- Use arrival_date instead of created_at for invoice date
  v_invoice_date := coalesce(v_job.arrival_date, v_job.created_at);

  -- Add items (products + services) from mechanic_job_items
  for v_job_item in
    select
      mji.product_id,
      mji.service_product_id,
      mji.product_name,
      mji.product_sku,
      mji.quantity,
      mji.unit_price,
      mji.total_price,
      mji.item_type,
      mji.notes,
      mji.job_bike_id,
      coalesce(
        nullif(concat_ws(' ', b.brand, b.model), ''),
        'Bicicleta'
      ) as bike_name
    from public.mechanic_job_items mji
    left join public.mechanic_job_bikes mjb on mjb.id = mji.job_bike_id
    left join public.bikes b on b.id = mjb.bike_id
    where mji.job_id = p_job_id
    order by mji.created_at
  loop
    v_item_counter := v_item_counter + 1;

    v_items := v_items || jsonb_build_object(
      'id', gen_random_uuid()::text,
      'product_id', case when coalesce(v_job_item.item_type, 'product') = 'service'
                         then coalesce(v_job_item.service_product_id::text, '')
                         else coalesce(v_job_item.product_id::text, '')
                    end,
      'product_name', v_job_item.product_name,
      'product_sku', coalesce(v_job_item.product_sku, ''),
      'description', coalesce(v_job_item.notes, ''),
      'item_type', coalesce(v_job_item.item_type, 'product'),
      'is_catalog_product', case when v_job_item.item_type = 'adhoc' then false else true end,
      'quantity', v_job_item.quantity,
      'unit_price', v_job_item.unit_price,
      'discount', 0,
      'line_total', coalesce(v_job_item.total_price, v_job_item.quantity * v_job_item.unit_price, 0),
      'cost', 0,
      'job_bike_id', v_job_item.job_bike_id,
      'bike_name', v_job_item.bike_name
    );

    v_subtotal := v_subtotal + coalesce(v_job_item.total_price, v_job_item.quantity * v_job_item.unit_price, 0);
  end loop;

  -- Draft invoices can be created for future work planning.

  -- Calculate IVA based on job's tax treatment
  if v_job.tax_treatment = 'tax_included' then
    -- Tax included: net = subtotal ÷ 1.19, iva = subtotal - net
    v_iva := round(v_subtotal - (v_subtotal / 1.19), 2);
  else
    -- No tax: iva = 0
    v_iva := 0;
  end if;

  v_total := v_subtotal;

  -- Generate invoice number using new sequential system
  v_invoice_number := public.get_next_document_number(v_tenant_id, 'sales_invoice');

  -- Create the invoice with status 'draft' for user review
  insert into public.sales_invoices (
    tenant_id,
    invoice_number,
    customer_id,
    customer_name,
    customer_rut,
    date,
    due_date,
    reference,
    status,
    subtotal,
    iva_amount,
    net_amount,
    tax_treatment,
    total,
    paid_amount,
    balance,
    items,
    source,
    created_at,
    updated_at
  ) values (
    v_tenant_id,
    v_invoice_number,
    v_customer.id,
    v_customer.name,
    v_customer.rut,
    v_invoice_date,
    v_invoice_date + interval '30 days',
    'Pega ' || v_job.job_number,
    'draft',
    v_subtotal,
    v_iva,
    case
      when v_job.tax_treatment = 'tax_included' then v_subtotal / 1.19
      else v_subtotal
    end,
    v_job.tax_treatment,
    v_total,
    0,
    v_total,
    v_items,
    'mechanic_job',
    now(),
    now()
  ) returning id into v_invoice_id;

  -- Link invoice to job
  update public.mechanic_jobs
  set invoice_id = v_invoice_id,
      is_invoiced = true,
      updated_at = now()
  where id = p_job_id;

  raise notice 'Created draft invoice % for job % (customer: %, date: %, total: $%)',
    v_invoice_id, v_job.job_number, v_customer.name, v_invoice_date, v_total;

  return v_invoice_id;
end;
$_$;


--
-- TOC entry 1180 (class 1255 OID 26286)
-- Name: create_mechanic_job_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_mechanic_job_journal_entry(p_job_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job record;
  v_entry_id uuid;
  v_revenue_account_id uuid;
  v_cogs_account_id uuid;
  v_inventory_account_id uuid;
  v_tax_payable_account_id uuid;
  v_ar_account_id uuid;
begin
  if p_job_id is null then
    return;
  end if;

  -- Get job details
  select * into v_job
  from mechanic_jobs
  where id = p_job_id;

  if not found then
    raise notice 'Job % not found', p_job_id;
    return;
  end if;

  -- Don't create journal entry if already invoiced (invoice will handle it)
  if v_job.is_invoiced then
    raise notice 'Job % already invoiced, skipping journal entry', v_job.job_number;
    return;
  end if;

  -- Check if journal entry already exists
  if exists (
    select 1 from journal_entries
    where source_module = 'mechanic_jobs'
      and source_reference = p_job_id::text
  ) then
    raise notice 'Journal entry already exists for job %', v_job.job_number;
    return;
  end if;

  -- Get or create necessary accounts
  v_revenue_account_id := public.ensure_account('4100', 'Ingresos Operacionales', 'income', 'operatingIncome');
  v_cogs_account_id := public.ensure_account('5100', 'Costo de Ventas', 'expense', 'costOfGoodsSold');
  v_inventory_account_id := public.ensure_account('1105', 'Inventarios', 'asset', 'currentAsset');
  v_tax_payable_account_id := public.ensure_account('210200', 'IVA por Pagar', 'liability', 'currentLiability');
  v_ar_account_id := public.ensure_account('1130', 'Cuentas por Cobrar Comerciales', 'asset', 'currentAsset');

  -- Create journal entry
  insert into journal_entries (
    entry_number,
    entry_date,
    description,
    source_module,
    source_reference,
    status,
    created_at,
    updated_at
  ) values (
    public.get_next_document_number(v_job.tenant_id, 'journal_entry'),
    coalesce(v_job.completed_at, now()),
    'Mechanic Job ' || v_job.job_number || ' - ' || coalesce(v_job.diagnosis, 'Service completed'),
    'mechanic_jobs',
    v_job.job_number,
    'posted',
    now(),
    now()
  ) returning id into v_entry_id;

  -- Debit: Accounts Receivable (total including tax)
  insert into journal_lines (
    entry_id,
    account_id,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_ar_account_id,
    'Service Revenue - Job ' || v_job.job_number,
    v_job.total_cost,
    0,
    now(),
    now()
  );

  -- Credit: Service Revenue (subtotal minus discount)
  insert into journal_lines (
    entry_id,
    account_id,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_revenue_account_id,
    'Service Revenue - Job ' || v_job.job_number,
    0,
    v_job.final_cost - v_job.discount_amount,
    now(),
    now()
  );

  -- Credit: Tax Payable (IVA)
  if v_job.tax_amount > 0 then
    insert into journal_lines (
      entry_id,
      account_id,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      v_entry_id,
      v_tax_payable_account_id,
      'IVA - Job ' || v_job.job_number,
      0,
      v_job.tax_amount,
      now(),
      now()
    );
  end if;

  -- Debit: Cost of Services (parts cost)
  -- Credit: Inventory (parts cost)
  if v_job.parts_cost > 0 then
    insert into journal_lines (
      entry_id,
      account_id,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      v_entry_id,
      v_cogs_account_id,
      'COGS - Parts - Job ' || v_job.job_number,
      v_job.parts_cost,
      0,
      now(),
      now()
    );

    insert into journal_lines (
      entry_id,
      account_id,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      v_entry_id,
      v_inventory_account_id,
      'Inventory Reduction - Job ' || v_job.job_number,
      0,
      v_job.parts_cost,
      now(),
      now()
    );
  end if;

  raise notice 'Created journal entry for job %', v_job.job_number;
end;
$$;


--
-- TOC entry 1266 (class 1255 OID 21102)
-- Name: create_prepaid_purchase_confirmation_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_prepaid_purchase_confirmation_entry(p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_invoice RECORD;
  v_entry_id UUID;
  v_inv_transit_account_id UUID;  -- Inventario en Tránsito (1155)
  v_iva_account_id UUID;
  v_ap_account_id UUID;
BEGIN
  -- Get invoice data
  SELECT * INTO v_invoice
  FROM purchase_invoices
  WHERE id = p_invoice_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % not found', p_invoice_id;
  END IF;

  -- Get account IDs for prepayment model
  SELECT id INTO v_inv_transit_account_id FROM accounts WHERE code = '1155' LIMIT 1; -- Inventario en Tránsito
  SELECT id INTO v_iva_account_id FROM accounts WHERE code = '1140' LIMIT 1;         -- IVA Crédito Fiscal
  SELECT id INTO v_ap_account_id FROM accounts WHERE code = '2120' LIMIT 1;          -- Cuentas por Pagar

  IF v_inv_transit_account_id IS NULL OR v_iva_account_id IS NULL OR v_ap_account_id IS NULL THEN
    RAISE EXCEPTION 'Required accounts not found for prepayment (1155, 1140, 2120)';
  END IF;

  -- Create journal entry
  INSERT INTO journal_entries (
    id,
    entry_number,
    entry_date,
    entry_type,
    source_module,
    source_reference,
    status,
    notes,
    created_at
  )
  VALUES (
    gen_random_uuid(),
    'CONF-COMP-FC-' || v_invoice.invoice_number,
    v_invoice.confirmed_date,
    'purchase_confirmation',
    'purchase_invoices',
    p_invoice_id::TEXT,
    'posted',
    'Confirmación de compra prepagada - Factura ' || v_invoice.invoice_number,
    NOW()
  )
  RETURNING id INTO v_entry_id;

  -- Create journal lines
  -- DR: Inventario en Tránsito (subtotal)
  INSERT INTO journal_lines (id, journal_entry_id, account_id, debit, credit, description, created_at)
  VALUES (
    gen_random_uuid(),
    v_entry_id,
    v_inv_transit_account_id,
    v_invoice.subtotal,
    0,
    'Inventario en Tránsito - ' || COALESCE(v_invoice.supplier_name, 'Proveedor'),
    NOW()
  );

  -- DR: IVA Crédito Fiscal
  INSERT INTO journal_lines (id, journal_entry_id, account_id, debit, credit, description, created_at)
  VALUES (
    gen_random_uuid(),
    v_entry_id,
    v_iva_account_id,
    v_invoice.iva_amount,
    0,
    'IVA Crédito Fiscal',
    NOW()
  );

  -- CR: Cuentas por Pagar
  INSERT INTO journal_lines (id, journal_entry_id, account_id, debit, credit, description, created_at)
  VALUES (
    gen_random_uuid(),
    v_entry_id,
    v_ap_account_id,
    0,
    v_invoice.total,
    'Cuentas por Pagar - ' || COALESCE(v_invoice.supplier_name, 'Proveedor'),
    NOW()
  );

  RAISE NOTICE 'Created prepaid confirmation entry % for invoice %', v_entry_id, v_invoice.invoice_number;
  RETURN v_entry_id;
END;
$$;


--
-- TOC entry 1483 (class 1255 OID 21101)
-- Name: create_purchase_invoice_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_invoice_journal_entry(p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice RECORD;
  v_entry_id UUID := gen_random_uuid();
  v_exists BOOLEAN;
  v_inventory_account_code TEXT := '1150';
  v_inventory_account_name TEXT := 'Inventarios de Mercaderías';
  v_inventory_account_id UUID;
  v_iva_account_code TEXT := '1140';
  v_iva_account_name TEXT := 'IVA Crédito Fiscal';
  v_iva_account_id UUID;
  v_ap_account_code TEXT := '2120';
  v_ap_account_name TEXT := 'Cuentas por Pagar';
  v_ap_account_id UUID;
  v_entry_number TEXT;
BEGIN
  -- Get invoice data
  SELECT * INTO v_invoice
  FROM purchase_invoices
  WHERE id = p_invoice_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Purchase invoice % not found', p_invoice_id;
  END IF;

  -- Check if journal entry already exists
  SELECT EXISTS (
    SELECT 1
    FROM journal_entries
    WHERE source_module = 'purchase_invoices'
      AND source_reference = p_invoice_id::TEXT
  ) INTO v_exists;

  IF v_exists THEN
    RAISE NOTICE 'Journal entry already exists for purchase invoice %', p_invoice_id;
    RETURN NULL;
  END IF;

  -- Validate amounts
  IF v_invoice.total IS NULL OR v_invoice.total = 0 THEN
    RAISE NOTICE 'Purchase invoice % has zero total, skipping journal entry', p_invoice_id;
    RETURN NULL;
  END IF;

  -- Get account IDs using ensure_account
  v_inventory_account_id := public.ensure_account(
    v_inventory_account_code,
    v_inventory_account_name,
    'asset',
    'currentAsset',
    'Inventario disponible para la venta',
    NULL
  );

  v_iva_account_id := public.ensure_account(
    v_iva_account_code,
    v_iva_account_name,
    'asset',
    'currentAsset',
    'IVA recuperable en compras',
    NULL
  );

  v_ap_account_id := public.ensure_account(
    v_ap_account_code,
    v_ap_account_name,
    'liability',
    'currentLiability',
    'Cuentas por pagar a proveedores',
    NULL
  );

  IF v_inventory_account_id IS NULL OR v_iva_account_id IS NULL OR v_ap_account_id IS NULL THEN
    RAISE EXCEPTION 'Required accounts not found for purchase invoice';
  END IF;

  -- Generate entry number
  v_entry_number := CONCAT('PURCH-', TO_CHAR(NOW(), 'YYYYMMDDHH24MISS'));

  -- ✅ Using NEW column names (entry_date, entry_type, notes)
  INSERT INTO journal_entries (
    id,
    entry_number,
    entry_date,
    notes,
    entry_type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) VALUES (
    v_entry_id,
    v_entry_number,
    COALESCE(v_invoice.confirmed_date, v_invoice.invoice_date, NOW()),
    format('Compra según factura %s - %s', 
           COALESCE(v_invoice.invoice_number, v_invoice.id::TEXT),
           COALESCE(v_invoice.supplier_name, 'Proveedor')),
    'purchase',
    'purchase_invoices',
    p_invoice_id::TEXT,
    'posted',
    v_invoice.total,
    v_invoice.total,
    NOW(),
    NOW()
  );

  -- ✅ Using NEW column names (journal_entry_id, debit, credit)
  -- Line 1: Debit Inventory (subtotal)
  INSERT INTO journal_lines (
    id,
    journal_entry_id,
    account_id,
    debit,
    credit,
    description,
    created_at,
    updated_at
  ) VALUES (
    gen_random_uuid(),
    v_entry_id,
    v_inventory_account_id,
    COALESCE(v_invoice.subtotal, 0),
    0,
    format('Inventario - Factura %s', COALESCE(v_invoice.invoice_number, 'S/N')),
    NOW(),
    NOW()
  );

  -- Line 2: Debit IVA Crédito Fiscal (if iva_amount > 0)
  IF COALESCE(v_invoice.iva_amount, 0) > 0 THEN
    INSERT INTO journal_lines (
      id,
      journal_entry_id,
      account_id,
      debit,
      credit,
      description,
      created_at,
      updated_at
    ) VALUES (
      gen_random_uuid(),
      v_entry_id,
      v_iva_account_id,
      v_invoice.iva_amount,
      0,
      format('IVA Crédito Fiscal - Factura %s', COALESCE(v_invoice.invoice_number, 'S/N')),
      NOW(),
      NOW()
    );
  END IF;

  -- Line 3: Credit Accounts Payable (total)
  INSERT INTO journal_lines (
    id,
    journal_entry_id,
    account_id,
    debit,
    credit,
    description,
    created_at,
    updated_at
  ) VALUES (
    gen_random_uuid(),
    v_entry_id,
    v_ap_account_id,
    0,
    v_invoice.total,
    format('Cuentas por Pagar - %s', COALESCE(v_invoice.supplier_name, 'Proveedor')),
    NOW(),
    NOW()
  );

  RAISE NOTICE '✅ Created purchase journal entry % for invoice %', v_entry_number, v_invoice.invoice_number;
  RETURN v_entry_id;
END;
$$;


--
-- TOC entry 1387 (class 1255 OID 22576)
-- Name: create_purchase_invoice_journal_entry(public.purchase_invoices); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_invoice_journal_entry(p_invoice public.purchase_invoices) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_exists boolean;
  v_entry_id uuid := gen_random_uuid();
  v_inventory_account_id uuid;
  v_workshop_consumables_account_id uuid;
  v_iva_account_id uuid;
  v_payable_account_id uuid;
  v_description text;
  v_items jsonb := '[]'::jsonb;
  v_item record;
  v_inventory_subtotal numeric(12,2) := 0;
  v_workshop_subtotal numeric(12,2) := 0;
  v_total_item_subtotal numeric(12,2) := 0;
  v_scaled_subtotal numeric(12,2) := 0;
  v_subtotal_delta numeric(12,2) := 0;
begin
  raise notice '🔵 START create_purchase_invoice_journal_entry for invoice %', p_invoice.id;

  if p_invoice.id is null then
    raise notice '❌ Invoice ID is null, returning';
    return;
  end if;

  raise notice '✅ Invoice ID: %, tenant_id: %', p_invoice.id, p_invoice.tenant_id;

  select exists (
    select 1
    from public.journal_entries
    where source_module = 'purchase_invoices'
      and source_reference = p_invoice.invoice_number
  ) into v_exists;

  if v_exists then
    raise notice '⚠️ Entry already exists for invoice %, skipping', p_invoice.id;
    return;
  end if;

  raise notice '✅ No existing entry found, proceeding...';

  v_inventory_account_id := public.ensure_account(
    p_invoice.tenant_id,
    '1105',
    'Inventarios',
    'asset',
    'currentAsset',
    'Valor del inventario de productos',
    null
  );

  v_workshop_consumables_account_id := public.ensure_account(
    p_invoice.tenant_id,
    '5101',
    'Consumibles de Taller',
    'expense',
    'costOfGoodsSold',
    'Materiales y consumibles de uso rápido aplicados directamente en el taller',
    null
  );

  v_iva_account_id := public.ensure_account(
    p_invoice.tenant_id,
    '2120',
    'IVA Crédito Fiscal',
    'asset',
    'currentAsset',
    'IVA pagado en compras, recuperable',
    null
  );

  v_payable_account_id := public.ensure_account(
    p_invoice.tenant_id,
    '2101',
    'Cuentas por Pagar Proveedores',
    'liability',
    'currentLiability',
    'Obligaciones con proveedores',
    null
  );

  v_description := format('Factura compra %s - %s',
    p_invoice.invoice_number,
    coalesce(p_invoice.supplier_name, 'Proveedor')
  );

  v_items := coalesce(p_invoice.items, '[]'::jsonb);

  for v_item in
    select
      coalesce(nullif(item->>'purchase_treatment', ''), 'inventory')::text as purchase_treatment,
      greatest(
        (coalesce((item->>'quantity')::numeric, 0) *
         coalesce((item->>'unit_cost')::numeric, 0)) -
        coalesce((item->>'discount')::numeric, 0),
        0
      )::numeric(12,2) as line_subtotal
    from jsonb_array_elements(v_items) as item
  loop
    if coalesce(v_item.line_subtotal, 0) <= 0 then
      continue;
    end if;

    v_total_item_subtotal := v_total_item_subtotal + v_item.line_subtotal;

    if v_item.purchase_treatment = 'workshop_consumable' then
      v_workshop_subtotal := v_workshop_subtotal + v_item.line_subtotal;
    else
      v_inventory_subtotal := v_inventory_subtotal + v_item.line_subtotal;
    end if;
  end loop;

  v_scaled_subtotal := coalesce(p_invoice.subtotal, 0);

  if v_total_item_subtotal <= 0 then
    v_inventory_subtotal := v_scaled_subtotal;
    v_workshop_subtotal := 0;
  elsif abs(v_total_item_subtotal - v_scaled_subtotal) > 0.01 then
    v_inventory_subtotal := round(
      (v_inventory_subtotal / v_total_item_subtotal) * v_scaled_subtotal,
      2
    );
    v_workshop_subtotal := round(
      (v_workshop_subtotal / v_total_item_subtotal) * v_scaled_subtotal,
      2
    );

    v_subtotal_delta := round(
      v_scaled_subtotal - v_inventory_subtotal - v_workshop_subtotal,
      2
    );

    if v_subtotal_delta <> 0 then
      if v_inventory_subtotal >= v_workshop_subtotal then
        v_inventory_subtotal := v_inventory_subtotal + v_subtotal_delta;
      else
        v_workshop_subtotal := v_workshop_subtotal + v_subtotal_delta;
      end if;
    end if;
  end if;

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    p_invoice.tenant_id,
    public.get_next_document_number(p_invoice.tenant_id, 'journal_entry'),
    coalesce(p_invoice.date, now()),
    v_description,
    'purchase',
    'purchase_invoices',
    p_invoice.invoice_number,
    'posted',
    p_invoice.total,
    p_invoice.total,
    now(),
    now()
  );

  if v_inventory_subtotal > 0 then
    insert into public.journal_lines (
      id,
      entry_id,
      account_id,
      tenant_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_entry_id,
      v_inventory_account_id,
      p_invoice.tenant_id,
      '1105',
      'Inventarios',
      v_description,
      v_inventory_subtotal,
      0,
      now(),
      now()
    );
  end if;

  if v_workshop_subtotal > 0 then
    insert into public.journal_lines (
      id,
      entry_id,
      account_id,
      tenant_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_entry_id,
      v_workshop_consumables_account_id,
      p_invoice.tenant_id,
      '5101',
      'Consumibles de Taller',
      v_description,
      v_workshop_subtotal,
      0,
      now(),
      now()
    );
  end if;

  insert into public.journal_lines (
    id,
    entry_id,
    account_id,
    tenant_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_entry_id,
    v_iva_account_id,
    p_invoice.tenant_id,
    '2120',
    'IVA Crédito Fiscal',
    v_description,
    p_invoice.tax,
    0,
    now(),
    now()
  );

  insert into public.journal_lines (
    id,
    entry_id,
    account_id,
    tenant_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_entry_id,
    v_payable_account_id,
    p_invoice.tenant_id,
    '2101',
    'Cuentas por Pagar Proveedores',
    v_description,
    0,
    p_invoice.total,
    now(),
    now()
  );

  raise notice '✅ Journal entry created successfully for invoice %', p_invoice.id;
  raise notice '🎉 DONE - Entry ID: %, Total: %', v_entry_id, p_invoice.total;
end;
$$;


--
-- TOC entry 825 (class 1255 OID 114810)
-- Name: create_purchase_payment_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_payment_journal_entry(p_payment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_payment record;
  v_invoice record;
  v_entry_id uuid := gen_random_uuid();
  v_exists boolean;
  v_payment_method record;
  v_cash_account_id uuid;
  v_cash_account_code text;
  v_cash_account_name text;
  v_payable_account_id uuid;
  v_payable_account_code text := '2101';
  v_payable_account_name text := 'Cuentas por Pagar Proveedores';
  v_description text;
  v_tenant_id uuid;
begin
  -- Fetch payment data from table instead of using composite type parameter
  select id, invoice_id, amount, date, payment_method_id, tenant_id
    into v_payment
    from public.purchase_payments
   where id = p_payment_id;

  if not found or v_payment.invoice_id is null then
    return;
  end if;

  v_tenant_id := v_payment.tenant_id;

  select exists (
           select 1
             from public.journal_entries
            where source_module = 'purchase_payments'
              and source_reference = v_payment.id::text
        )
    into v_exists;

  if v_exists then
    return;
  end if;

  select id,
         invoice_number,
         supplier_name,
         total
    into v_invoice
    from public.purchase_invoices
   where id = v_payment.invoice_id;

  if not found then
    return;
  end if;

  -- Get payment method and its associated account (DYNAMIC!)
  select pm.id, pm.code, pm.name, a.id as account_id, a.code as account_code, a.name as account_name
    into v_payment_method
    from public.payment_methods pm
    join public.accounts a on a.id = pm.account_id
   where pm.id = v_payment.payment_method_id;

  if not found then
    raise exception 'Payment method not found for payment %', v_payment.id;
  end if;

  -- Use the account from payment method configuration
  v_cash_account_id := v_payment_method.account_id;
  v_cash_account_code := v_payment_method.account_code;
  v_cash_account_name := v_payment_method.account_name;

  v_payable_account_id := public.ensure_account(
    v_payable_account_code,
    v_payable_account_name,
    'liability',
    'currentLiability',
    'Cuentas por pagar a proveedores',
    null
  );

  v_description := format('Pago factura compra %s - %s', 
    coalesce(v_invoice.invoice_number, v_invoice.id::text),
    v_payment_method.name
  );

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_tenant_id,
    public.get_next_document_number(v_tenant_id, 'journal_entry'),
    coalesce(v_payment.date, now()),
    v_description,
    'payment',
    'purchase_payments',
    v_invoice.invoice_number,
    'posted',
    v_payment.amount,
    v_payment.amount,
    now(),
    now()
  );

  -- DR: Accounts Payable (reduce liability)
  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_tenant_id,
    v_entry_id,
    v_payable_account_id,
    v_payable_account_code,
    v_payable_account_name,
    v_description,
    v_payment.amount,
    0,
    now(),
    now()
  );

  -- CR: Cash/Bank account (reduce asset)
  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_tenant_id,
    v_entry_id,
    v_cash_account_id,
    v_cash_account_code,
    v_cash_account_name,
    v_description,
    0,
    v_payment.amount,
    now(),
    now()
  );
end;
$$;


--
-- TOC entry 1624 (class 1255 OID 137914)
-- Name: create_sales_invoice_journal_entry(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sales_invoice_journal_entry(p_invoice jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_entry_id uuid;
  v_tenant_id uuid;
  v_invoice_id uuid;
  v_invoice_number text;
  v_customer_name text;
  v_total numeric;
  v_subtotal numeric;
  v_tax_amount numeric;
  v_receivable_account_id uuid;
  v_revenue_account_id uuid;
  v_iva_account_id uuid;
  v_inventory_account_id uuid;
  v_cogs_account_id uuid;
  v_total_cost numeric;
  v_iva_account_code text := '2150';
  v_iva_account_name text := 'IVA Débito Fiscal';
BEGIN
  -- Extract invoice data
  v_tenant_id := (p_invoice->>'tenant_id')::uuid;
  v_invoice_id := (p_invoice->>'id')::uuid;
  v_invoice_number := p_invoice->>'invoice_number';
  v_customer_name := p_invoice->>'customer_name';
  v_total := COALESCE((p_invoice->>'total')::numeric, 0);
  v_subtotal := COALESCE((p_invoice->>'subtotal')::numeric, 0);
  v_tax_amount := COALESCE((p_invoice->>'tax_amount')::numeric, 0);

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id is required for journal entry';
  END IF;

  -- Ensure accounts exist (using LIABILITY for IVA, not tax!)
  v_receivable_account_id := public.ensure_account(
    v_tenant_id,
    '1130',
    'Cuentas por Cobrar',
    'asset',
    'currentAsset',
    'Cuentas por cobrar comerciales',
    null
  );

  v_revenue_account_id := public.ensure_account(
    v_tenant_id,
    '4100',
    'Ingresos por Ventas',
    'income',
    'operatingIncome',
    'Ingresos operacionales por ventas',
    null
  );

  v_iva_account_id := public.ensure_account(
    v_tenant_id,
    v_iva_account_code,
    v_iva_account_name,
    'liability',  -- FIXED: was 'tax'
    'currentLiability',  -- FIXED: was 'taxPayable'
    'IVA generado en ventas',
    null
  );

  -- Calculate total cost from items
  SELECT COALESCE(SUM((item->>'cost')::numeric * (item->>'quantity')::numeric), 0)
  INTO v_total_cost
  FROM jsonb_array_elements(COALESCE(p_invoice->'items', '[]'::jsonb)) item
  WHERE (item->>'cost') IS NOT NULL;

  -- Create journal entry
  INSERT INTO journal_entries (
    tenant_id,
    entry_date,
    description,
    reference_type,
    reference_id,
    status,
    created_at
  ) VALUES (
    v_tenant_id,
    COALESCE((p_invoice->>'date')::date, CURRENT_DATE),
    'Factura de venta ' || v_invoice_number || ' - ' || COALESCE(v_customer_name, 'Cliente'),
    'sales_invoice',
    v_invoice_id,
    'posted',
    NOW()
  )
  RETURNING id INTO v_entry_id;

  -- Debit: Cuentas por Cobrar (total amount)
  INSERT INTO journal_lines (entry_id, account_id, debit_amount, credit_amount, description)
  VALUES (v_entry_id, v_receivable_account_id, v_total, 0, 'Cuenta por cobrar - ' || v_invoice_number);

  -- Credit: Ingresos por Ventas (net amount)
  INSERT INTO journal_lines (entry_id, account_id, debit_amount, credit_amount, description)
  VALUES (v_entry_id, v_revenue_account_id, 0, v_subtotal, 'Ingreso por venta - ' || v_invoice_number);

  -- Credit: IVA Débito Fiscal (tax amount) if any
  IF v_tax_amount > 0 THEN
    INSERT INTO journal_lines (entry_id, account_id, debit_amount, credit_amount, description)
    VALUES (v_entry_id, v_iva_account_id, 0, v_tax_amount, 'IVA débito - ' || v_invoice_number);
  END IF;

  -- COGS entries if there's cost
  IF v_total_cost > 0 THEN
    v_inventory_account_id := public.ensure_account(
      v_tenant_id,
      '1105',
      'Inventarios',
      'asset',
      'currentAsset',
      'Inventario de mercaderías',
      null
    );

    v_cogs_account_id := public.ensure_account(
      v_tenant_id,
      '5100',
      'Costo de Ventas',
      'expense',
      'costOfGoodsSold',
      'Costo de mercaderías vendidas',
      null
    );

    -- Debit: Cost of Goods Sold
    INSERT INTO journal_lines (entry_id, account_id, debit_amount, credit_amount, description)
    VALUES (v_entry_id, v_cogs_account_id, v_total_cost, 0, 'Costo de venta - ' || v_invoice_number);

    -- Credit: Inventory
    INSERT INTO journal_lines (entry_id, account_id, debit_amount, credit_amount, description)
    VALUES (v_entry_id, v_inventory_account_id, 0, v_total_cost, 'Salida de inventario - ' || v_invoice_number);
  END IF;

  RETURN v_entry_id;
END;
$$;


--
-- TOC entry 912 (class 1255 OID 19364)
-- Name: create_sales_invoice_journal_entry(public.sales_invoices); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sales_invoice_journal_entry(p_invoice public.sales_invoices) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_exists boolean;
  v_entry_id uuid := gen_random_uuid();
  v_receivable_account_code text := '1130';
  v_receivable_account_name text := 'Cuentas por Cobrar Comerciales';
  v_receivable_account_id uuid;
  v_revenue_account_code text := '4100';
  v_revenue_account_name text := 'Ingresos Operacionales';
  v_revenue_account_id uuid;
  v_iva_account_code text := '2150';
  v_iva_account_name text := 'IVA Débito Fiscal';
  v_iva_account_id uuid;
  v_inventory_account_code text := '1105';
  v_inventory_account_name text := 'Inventarios';
  v_inventory_account_id uuid;
  v_cogs_account_code text := '5100';
  v_cogs_account_name text := 'Costo de Ventas';
  v_cogs_account_id uuid;
  v_invoice_number text;
  v_customer_name text;
  v_description text;
  v_subtotal numeric(12,2);
  v_iva numeric(12,2);
  v_total numeric(12,2);
  v_total_cost numeric(12,2);
  v_tenant_id uuid;
begin
  if p_invoice.id is null then
    return;
  end if;

  if coalesce(p_invoice.status, 'draft') in ('draft', 'cancelled') then
    return;
  end if;

  v_tenant_id := p_invoice.tenant_id;

  if v_tenant_id is null then
    raise warning 'create_sales_invoice_journal_entry: No tenant_id on invoice %, skipping', p_invoice.id;
    return;
  end if;

  select exists (
           select 1
             from public.journal_entries
            where source_module = 'sales_invoices'
              and source_reference = p_invoice.invoice_number
              and tenant_id = v_tenant_id
       )
    into v_exists;

  if v_exists then
    raise notice 'create_sales_invoice_journal_entry: Entry already exists for invoice %, skipping', p_invoice.invoice_number;
    return;
  end if;

  raise notice 'create_sales_invoice_journal_entry: Creating entry for invoice % (status: %)', p_invoice.invoice_number, p_invoice.status;

  v_subtotal := coalesce(nullif(p_invoice.net_amount, 0), p_invoice.subtotal, 0);
  v_iva := coalesce(nullif(p_invoice.iva_amount, 0), 0);

  if p_invoice.tax_treatment = 'tax_included' and (v_iva = 0 or v_subtotal = p_invoice.total) then
    v_subtotal := round(p_invoice.total / 1.19, 2);
    v_iva := p_invoice.total - v_subtotal;
  end if;

  v_total := coalesce(p_invoice.total, v_subtotal + v_iva);

  if v_total = 0 then
    return;
  end if;

  v_receivable_account_id := public.ensure_account(
    v_tenant_id,
    v_receivable_account_code,
    v_receivable_account_name,
    'asset',
    'currentAsset',
    'Cuentas por cobrar a clientes',
    null
  );

  v_revenue_account_id := public.ensure_account(
    v_tenant_id,
    v_revenue_account_code,
    v_revenue_account_name,
    'income',
    'operatingIncome',
    'Ingresos operacionales por ventas',
    null
  );

  v_iva_account_id := public.ensure_account(
    v_tenant_id,
    v_iva_account_code,
    v_iva_account_name,
    'liability',
    'currentLiability',
    'IVA generado en ventas',
    null
  );

  select coalesce(
           sum(
             case
               when coalesce((item->>'is_service')::boolean, false) then 0
               when coalesce(nullif(item->>'purchase_treatment', ''), 'inventory') = 'workshop_consumable' then 0
               else coalesce((item->>'quantity')::numeric, 0) * coalesce((item->>'cost')::numeric, 0)
             end
           ),
           0
         )
    into v_total_cost
    from jsonb_array_elements(coalesce(p_invoice.items, '[]'::jsonb)) item
   where (item->>'cost') is not null
     and (item->>'cost') <> '';

  if v_total_cost > 0 then
    v_inventory_account_id := public.ensure_account(
      v_tenant_id,
      v_inventory_account_code,
      v_inventory_account_name,
      'asset',
      'currentAsset',
      'Inventario disponible para la venta',
      null
    );

    v_cogs_account_id := public.ensure_account(
      v_tenant_id,
      v_cogs_account_code,
      v_cogs_account_name,
      'expense',
      'costOfGoodsSold',
      'Costo de ventas',
      null
    );
  end if;

  v_invoice_number := coalesce(nullif(p_invoice.invoice_number, ''), p_invoice.id::text);
  v_customer_name := coalesce(nullif(p_invoice.customer_name, ''), 'Cliente');
  v_description := format('Factura %s - %s', v_invoice_number, v_customer_name);

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_tenant_id,
    public.get_next_document_number(v_tenant_id, 'journal_entry'),
    coalesce(p_invoice.date, now()),
    v_description,
    'sales',
    'sales_invoices',
    p_invoice.invoice_number,
    'posted',
    v_total,
    v_total,
    now(),
    now()
  );

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_tenant_id,
    v_entry_id,
    v_receivable_account_id,
    v_receivable_account_code,
    v_receivable_account_name,
    v_description,
    v_total,
    0,
    now(),
    now()
  );

  if v_total - v_iva <> 0 then
    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_tenant_id,
      v_entry_id,
      v_revenue_account_id,
      v_revenue_account_code,
      v_revenue_account_name,
      format('Ingreso por venta %s', v_invoice_number),
      0,
      v_total - v_iva,
      now(),
      now()
    );
  end if;

  if v_iva <> 0 then
    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_tenant_id,
      v_entry_id,
      v_iva_account_id,
      v_iva_account_code,
      v_iva_account_name,
      format('IVA débito factura %s', v_invoice_number),
      0,
      v_iva,
      now(),
      now()
    );
  end if;

  if v_total_cost > 0 then
    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_tenant_id,
      v_entry_id,
      v_cogs_account_id,
      v_cogs_account_code,
      v_cogs_account_name,
      format('Costo de ventas %s', v_invoice_number),
      v_total_cost,
      0,
      now(),
      now()
    ), (
      gen_random_uuid(),
      v_tenant_id,
      v_entry_id,
      v_inventory_account_id,
      v_inventory_account_code,
      v_inventory_account_name,
      format('Salida inventario factura %s', v_invoice_number),
      0,
      v_total_cost,
      now(),
      now()
    );
  end if;
end;
$$;


--
-- TOC entry 431 (class 1259 OID 18568)
-- Name: sales_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_id uuid NOT NULL,
    invoice_reference text,
    amount numeric(12,2) DEFAULT 0 NOT NULL,
    date timestamp with time zone DEFAULT now() NOT NULL,
    reference text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    payment_method_id uuid NOT NULL,
    tenant_id uuid,
    tax_treatment text DEFAULT 'no_tax'::text,
    net_amount numeric(15,2),
    iva_amount numeric(15,2) DEFAULT 0,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    CONSTRAINT sales_payments_tax_treatment_check CHECK ((tax_treatment = ANY (ARRAY['no_tax'::text, 'tax_included'::text, 'tax_excluded'::text])))
);


--
-- TOC entry 1478 (class 1255 OID 19055)
-- Name: create_sales_payment_journal_entry(public.sales_payments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sales_payment_journal_entry(p_payment public.sales_payments) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_invoice record;
  v_entry_id uuid := gen_random_uuid();
  v_exists boolean;
  v_payment_method record;
  v_cash_account_id uuid;
  v_cash_account_code text;
  v_cash_account_name text;
  v_receivable_account_id uuid;
  v_receivable_account_code text := '1130';
  v_receivable_account_name text := 'Cuentas por Cobrar Comerciales';
  v_description text;
  v_tenant_id uuid;
begin
  if p_payment.invoice_id is null then
    return;
  end if;

  if p_payment.deleted_at is not null then
    return;
  end if;

  v_tenant_id := p_payment.tenant_id;

  if v_tenant_id is null then
    return;
  end if;

  select exists (
    select 1
    from public.journal_entries
    where source_module = 'sales_payments'
      and source_reference = p_payment.id::text
      and tenant_id = v_tenant_id
  ) into v_exists;

  if v_exists then
    return;
  end if;

  select id, invoice_number, customer_name, total
    into v_invoice
    from public.sales_invoices
   where id = p_payment.invoice_id;

  if not found then
    return;
  end if;

  select pm.id, pm.code, pm.name, a.id as account_id, a.code as account_code, a.name as account_name
    into v_payment_method
    from public.payment_methods pm
    join public.accounts a on a.id = pm.account_id
   where pm.id = p_payment.payment_method_id;

  if not found then
    raise exception 'Payment method not found for payment %', p_payment.id;
  end if;

  v_cash_account_id := v_payment_method.account_id;
  v_cash_account_code := v_payment_method.account_code;
  v_cash_account_name := v_payment_method.account_name;

  v_receivable_account_id := public.ensure_account(
    v_tenant_id,
    '1130',
    'Cuentas por Cobrar Comerciales',
    'asset',
    'currentAsset',
    'Cuentas por cobrar a clientes',
    null
  );

  v_description := format(
    'Pago factura %s - %s',
    coalesce(v_invoice.invoice_number, v_invoice.id::text),
    v_payment_method.name
  );

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_tenant_id,
    public.get_next_document_number(v_tenant_id, 'journal_entry'),
    coalesce(p_payment.date, now()),
    v_description,
    'payment',
    'sales_payments',
    p_payment.id::text,
    'posted',
    p_payment.amount,
    p_payment.amount,
    now(),
    now()
  );

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_tenant_id,
    v_entry_id,
    v_cash_account_id,
    v_cash_account_code,
    v_cash_account_name,
    format('Cobro a %s', coalesce(v_invoice.customer_name, 'Cliente')),
    p_payment.amount,
    0,
    now(),
    now()
  );

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_tenant_id,
    v_entry_id,
    v_receivable_account_id,
    '1130',
    'Cuentas por Cobrar Comerciales',
    format('Cancelación factura %s', coalesce(v_invoice.invoice_number, v_invoice.id::text)),
    0,
    p_payment.amount,
    now(),
    now()
  );
end;
$$;


--
-- TOC entry 839 (class 1255 OID 129495)
-- Name: create_website_backup(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_website_backup(p_name text, p_description text DEFAULT NULL::text, p_is_auto boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_tenant_id uuid;
  v_backup_id uuid;
  v_blocks jsonb;
  v_settings jsonb;
  v_pages jsonb;
  v_block_count integer;
begin
  v_tenant_id := public.user_tenant_id();
  if v_tenant_id is null then
    raise exception 'No tenant found for current user';
  end if;
  
  -- Snapshot all blocks
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', id,
      'block_type', block_type,
      'block_data', block_data,
      'is_visible', is_visible,
      'order_index', order_index,
      'page_id', page_id
    ) order by order_index
  ), '[]'::jsonb)
  into v_blocks
  from website_blocks
  where tenant_id = v_tenant_id;
  
  select count(*) into v_block_count from website_blocks where tenant_id = v_tenant_id;
  
  -- Snapshot all settings
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb)
  into v_settings
  from website_settings
  where tenant_id = v_tenant_id;
  
  -- Snapshot all pages
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', id,
      'slug', slug,
      'title', title,
      'meta_title', meta_title,
      'meta_description', meta_description,
      'is_published', is_published,
      'is_home', is_home,
      'template', template
    ) order by created_at
  ), '[]'::jsonb)
  into v_pages
  from website_pages
  where tenant_id = v_tenant_id;
  
  -- Insert backup
  insert into website_backups (
    tenant_id, name, description, blocks_snapshot, settings_snapshot,
    pages_snapshot, block_count, is_auto_backup, created_by
  ) values (
    v_tenant_id, p_name, p_description, v_blocks, v_settings,
    v_pages, v_block_count, p_is_auto, auth.uid()
  )
  returning id into v_backup_id;
  
  return v_backup_id;
end;
$$;


--
-- TOC entry 1060 (class 1255 OID 155556)
-- Name: delete_conversation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_conversation(p_conversation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_participant BOOLEAN;
    v_is_employee BOOLEAN;
    v_user_role TEXT;
    v_chat_type TEXT;
BEGIN
    -- Get conversation details
    SELECT type INTO v_chat_type 
    FROM conversations 
    WHERE id = p_conversation_id;
    
    IF v_chat_type IS NULL THEN
        RETURN; -- Conversation does not exist
    END IF;

    -- Check if user is a participant using a more direct query
    IF EXISTS (
        SELECT 1 FROM conversation_participants
        WHERE conversation_id = p_conversation_id
        AND user_id = v_user_id
    ) THEN
        v_is_participant := true;
    ELSE
        v_is_participant := false;
    END IF;

    -- Check if user is an employee
    IF EXISTS (SELECT 1 FROM employees WHERE user_id = v_user_id) THEN
        v_is_employee := true;
    ELSE
        v_is_employee := false;
    END IF;

    -- Get user role
    SELECT role INTO v_user_role FROM user_profiles WHERE user_id = v_user_id;
    
    -- AUTH LOGIC:
    -- 1. Participant can delete (Standard)
    -- 2. Employee can delete 'support' chats (Shared Inbox)
    -- 3. Admins/Managers can delete any chat
    
    IF v_is_participant 
       OR (v_is_employee AND v_chat_type = 'support')
       OR (v_user_role IN ('admin', 'owner', 'manager')) THEN
        -- Allowed
        NULL;
    ELSE
        RAISE EXCEPTION 'User is not authorized to delete this conversation (Code: P0001)';
    END IF;
    
    -- DELETE OPERATIONS
    
    -- 1. Messages (Foreign Key)
    DELETE FROM messages WHERE conversation_id = p_conversation_id;
    
    -- 2. Participants
    DELETE FROM conversation_participants WHERE conversation_id = p_conversation_id;
    
    -- 3. Conversation
    DELETE FROM conversations WHERE id = p_conversation_id;
    
END;
$$;


