CREATE FUNCTION public.delete_purchase_invoice_journal_entry(p_invoice_number text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_invoice_number is null then
