--
-- TOC entry 1292 (class 1255 OID 38134)
-- Name: delete_tenant_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_tenant_user(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_tenant_id uuid;
  v_caller_role text;
  v_caller_tenant_id uuid;
  v_caller_user_id uuid;
begin
  -- Get caller's user ID from the session
  v_caller_user_id := auth.uid();
  
  if v_caller_user_id is null then
    raise exception 'Not authenticated';
  end if;
  
  -- Get caller's tenant_id and role from auth.users metadata
  select 
    (raw_app_meta_data->>'tenant_id')::uuid,
    (raw_app_meta_data->>'role')::text
  into v_caller_tenant_id, v_caller_role
  from auth.users
  where id = v_caller_user_id;
  
  -- Only managers can delete users
  if v_caller_role != 'manager' then
    raise exception 'Only managers can delete users. Your role: %', v_caller_role;
  end if;
  
  -- Get the target user's tenant_id
  select (raw_app_meta_data->>'tenant_id')::uuid into v_tenant_id
  from auth.users
  where id = p_user_id;
  
  -- Verify same tenant
  if v_tenant_id != v_caller_tenant_id then
    raise exception 'Cannot delete user from different tenant';
  end if;
  
  -- Unlink from employee
  update employees
  set user_id = null
  where user_id = p_user_id;
  
  -- Delete the auth user
  delete from auth.users where id = p_user_id;
  
  raise notice 'User % deleted successfully', p_user_id;
end;
$$;


--
-- TOC entry 1900 (class 1255 OID 19200)
-- Name: ensure_account(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_account(p_code text, p_name text, p_type text, p_category text, p_description text DEFAULT NULL::text, p_parent_code text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_parent_id uuid;
begin
  perform public.migrate_accounts_to_uuid();

  if p_code is null then
    return null;
  end if;

  -- Get current tenant_id (will be null for non-authenticated contexts)
  declare
    v_tenant_id uuid := public.user_tenant_id();
  begin
    -- Lookup parent account (must be in same tenant)
    if p_parent_code is not null and v_tenant_id is not null then
      select id
        into v_parent_id
        from public.accounts
       where tenant_id = v_tenant_id
         and code = p_parent_code
       limit 1;
    elsif p_parent_code is not null and v_tenant_id is null then
      -- Backward compatibility for single-tenant
      select id
        into v_parent_id
        from public.accounts
       where code = p_parent_code
       limit 1;
    end if;
    if v_tenant_id is null then
      raise exception 'Cannot create account without tenant_id. User must be authenticated.';
    end if;
    
    -- Multi-tenant structure: use (tenant_id, code) unique constraint
    insert into public.accounts (tenant_id, code, name, type, category, description, parent_id)
    values (v_tenant_id, p_code, p_name, p_type, p_category, p_description, v_parent_id)
    on conflict (tenant_id, code) do update
      set name = excluded.name,
          type = excluded.type,
          category = excluded.category,
          description = coalesce(excluded.description, accounts.description),
          parent_id = coalesce(excluded.parent_id, accounts.parent_id),
          is_active = true,
          updated_at = now()
    returning id into v_account_id;
  end;

  return v_account_id;
end;
$$;


--
-- TOC entry 730 (class 1255 OID 51766)
-- Name: ensure_account(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_account(p_tenant_id uuid, p_code text, p_name text, p_type text, p_category text, p_description text DEFAULT NULL::text, p_parent_code text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_parent_id uuid;
begin
  perform public.migrate_accounts_to_uuid();

  -- Handle empty string or null code
  if p_code is null or p_code = '' then
    return null;
  end if;

  -- Lookup parent account (must be in same tenant)
  if p_parent_code is not null and p_parent_code != '' and p_tenant_id is not null then
    select id
      into v_parent_id
      from public.accounts
     where tenant_id = p_tenant_id
       and code = p_parent_code
     limit 1;
  end if;

  if p_tenant_id is null then
    raise exception 'Cannot create account without tenant_id. Tenant ID is required for multi-tenant system.';
  end if;

  -- Multi-tenant structure: use (tenant_id, code) unique constraint
  insert into public.accounts (tenant_id, code, name, type, category, description, parent_id)
  values (p_tenant_id, p_code, p_name, p_type, p_category, nullif(p_description, ''), v_parent_id)
  on conflict (tenant_id, code) do update
    set name = excluded.name,
        type = excluded.type,
        category = excluded.category,
        description = coalesce(excluded.description, accounts.description),
        parent_id = coalesce(excluded.parent_id, accounts.parent_id),
        is_active = true,
        updated_at = now()
  returning id into v_account_id;

  return v_account_id;
end;
$$;


