  ) values (
    p_tenant_id, p_name, nullif(p_description, ''), p_default_account_id, 0
  ) returning id into v_id;

  return v_id;
end;
$$;


--
-- TOC entry 1977 (class 1255 OID 224706)
-- Name: ensure_sales_invoice_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_sales_invoice_journal_entry(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_invoice public.sales_invoices%rowtype;
begin
  if p_invoice_id is null then
    return;
  end if;

  select * into v_invoice
    from public.sales_invoices
   where id = p_invoice_id;

  if not found then
    raise notice 'ensure_sales_invoice_journal_entry: invoice % not found', p_invoice_id;
    return;
  end if;

  -- create_sales_invoice_journal_entry already checks for duplicate JE internally,
  -- so calling this multiple times is safe (idempotent).
  perform public.create_sales_invoice_journal_entry(v_invoice);
end;
$$;


