--

CREATE FUNCTION public.ensure_single_default_address() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.is_default then
    update customer_addresses
    set is_default = false
    where customer_id = new.customer_id
      and id != new.id
      and is_default = true;
  end if;
  return new;
end;
$$;


