--

CREATE FUNCTION public.ensure_single_home_page() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if NEW.is_home = true then
    update website_pages set is_home = false, updated_at = now()
    where tenant_id = NEW.tenant_id and id != NEW.id and is_home = true;
  end if;
  return NEW;
end;
$$;


--
-- TOC entry 1482 (class 1255 OID 236750)
-- Name: ensure_whatsapp_conversation_binding(uuid, uuid, text, text, text, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_whatsapp_conversation_binding(p_tenant_id uuid, p_channel_id uuid, p_wa_id text, p_phone_number text DEFAULT NULL::text, p_contact_name text DEFAULT NULL::text, p_customer_id uuid DEFAULT NULL::uuid, p_context_type text DEFAULT NULL::text, p_context_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_binding record;
  v_conversation_id uuid;
  v_binding_id uuid;
  v_customer_auth_user_id uuid;
  v_context_type text;
  v_context_id uuid;
  v_title text;
BEGIN
  IF p_tenant_id IS NULL OR p_channel_id IS NULL OR p_wa_id IS NULL THEN
    RAISE EXCEPTION 'tenant, channel and wa_id are required';
  END IF;

  SELECT * INTO v_binding
  FROM public.whatsapp_conversation_bindings
  WHERE channel_id = p_channel_id
    AND external_wa_id = p_wa_id
  LIMIT 1;

  IF FOUND THEN
    v_conversation_id := v_binding.conversation_id;
    v_binding_id := v_binding.id;
  ELSE
    IF p_conversation_id IS NOT NULL THEN
      SELECT id INTO v_conversation_id
      FROM public.conversations
      WHERE id = p_conversation_id
        AND tenant_id = p_tenant_id
      LIMIT 1;
    END IF;

    IF v_conversation_id IS NULL THEN
      v_title := coalesce(nullif(trim(p_contact_name), ''), nullif(trim(p_phone_number), ''), 'WhatsApp');

      INSERT INTO public.conversations (
        tenant_id,
        type,
        title,
        status,
        last_message_at,
        updated_at
      ) VALUES (
        p_tenant_id,
        'support',
        v_title,
        'pending',  -- AQUÍ SE ENCONTRABA EL ERROR: ESTABA EN 'active'
        now(),
        now()
      ) RETURNING id INTO v_conversation_id;
    END IF;

    INSERT INTO public.whatsapp_conversation_bindings (
      tenant_id,
      conversation_id,
      channel_id,
      customer_id,
      external_wa_id,
      external_phone_number,
      contact_name
    ) VALUES (
      p_tenant_id,
      v_conversation_id,
      p_channel_id,
      p_customer_id,
      p_wa_id,
      public.normalize_whatsapp_phone(p_phone_number),
      p_contact_name
    ) RETURNING id INTO v_binding_id;
  END IF;

  UPDATE public.whatsapp_conversation_bindings
  SET customer_id = coalesce(p_customer_id, customer_id),
      external_phone_number = coalesce(public.normalize_whatsapp_phone(p_phone_number), external_phone_number),
      contact_name = coalesce(nullif(trim(p_contact_name), ''), contact_name),
      updated_at = now()
  WHERE id = v_binding_id;

  IF p_customer_id IS NOT NULL THEN
    SELECT auth_user_id INTO v_customer_auth_user_id
    FROM public.customers
    WHERE id = p_customer_id
      AND tenant_id = p_tenant_id
    LIMIT 1;

    IF v_customer_auth_user_id IS NOT NULL THEN
      INSERT INTO public.conversation_participants (
        conversation_id,
        user_id,
        tenant_id,
        role
      ) VALUES (
        v_conversation_id,
        v_customer_auth_user_id,
        p_tenant_id,
        'member'
      ) ON CONFLICT (conversation_id, user_id) DO NOTHING;
    END IF;
  END IF;

  v_context_type := p_context_type;
  v_context_id := p_context_id;

  IF v_context_type IS NULL AND p_customer_id IS NOT NULL THEN
    v_context_type := 'customer';
    v_context_id := p_customer_id;
  END IF;

  IF v_context_type IS NOT NULL AND v_context_id IS NOT NULL THEN
    INSERT INTO public.conversation_contexts (
      conversation_id,
      context_type,
      context_id,
      is_primary,
      tenant_id
    ) VALUES (
      v_conversation_id,
      v_context_type,
      v_context_id,
      NOT EXISTS (
        SELECT 1
        FROM public.conversation_contexts
        WHERE conversation_id = v_conversation_id
      ),
      p_tenant_id
    ) ON CONFLICT (conversation_id, context_type, context_id) DO NOTHING;
  END IF;

  UPDATE public.conversations
  SET title = coalesce(title, nullif(trim(p_contact_name), ''), nullif(trim(p_phone_number), ''), title),
      updated_at = now()
  WHERE id = v_conversation_id;

  RETURN jsonb_build_object(
    'conversation_id', v_conversation_id,
    'binding_id', v_binding_id
  );
END;
$$;


--
-- TOC entry 1799 (class 1255 OID 80244)
-- Name: find_compatible_hubs(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_compatible_hubs(p_tenant_id uuid, p_rim_id uuid, p_bike_old_mm numeric DEFAULT NULL::numeric, p_hub_type text DEFAULT 'rear'::text) RETURNS TABLE(hub_id uuid, hub_name text, manufacturer text, old_mm numeric, spoke_holes integer, compatibility_score integer, notes text)
    LANGUAGE plpgsql
    AS $$
declare
  v_rim_spoke_holes integer;
  v_rim_brake_type text;
begin
  -- Get rim specs
  select r.spoke_holes, r.brake_type
  into v_rim_spoke_holes, v_rim_brake_type
  from wheel_rims r
  where r.id = p_rim_id and r.tenant_id = p_tenant_id;
  
  if not found then
    raise exception 'Rim not found: %', p_rim_id;
  end if;
  
  -- Find matching hubs
  return query
  select
    h.id as hub_id,
    h.name as hub_name,
    h.manufacturer,
    h.old_mm,
    h.spoke_holes,
    -- Compatibility scoring
    case
      when h.spoke_holes = v_rim_spoke_holes then 100 -- Perfect match
      when h.brake_type = v_rim_brake_type then 80    -- Brake match
      when p_bike_old_mm is not null and h.old_mm = p_bike_old_mm then 90 -- OLD match
      else 50 -- Partial match
    end as compatibility_score,
    case
      when h.spoke_holes <> v_rim_spoke_holes then '⚠️ Spoke hole mismatch'
      when h.brake_type <> v_rim_brake_type then '⚠️ Brake type mismatch'
      else '✅ Compatible'
    end as notes
  from wheel_hubs h
  where h.tenant_id = p_tenant_id
    and h.is_active = true
    and h.hub_type = p_hub_type
    and h.spoke_holes = v_rim_spoke_holes -- Strict: spoke holes must match
  order by compatibility_score desc, h.name;
end;
$$;


--
-- TOC entry 1088 (class 1255 OID 80245)
-- Name: find_compatible_spokes(uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_compatible_spokes(p_tenant_id uuid, p_required_length_mm numeric, p_tolerance_mm numeric DEFAULT 2.0) RETURNS TABLE(spoke_id uuid, spoke_name text, length_mm integer, gauge numeric, manufacturer text, stock_quantity integer, length_difference_mm numeric)
    LANGUAGE plpgsql
    AS $$
begin
  return query
  select
    ws.id as spoke_id,
    ws.name as spoke_name,
    ws.length_mm,
    ws.gauge,
    ws.manufacturer,
    coalesce(p.inventory_qty, 0) as stock_quantity,
    abs(ws.length_mm - p_required_length_mm) as length_difference_mm
  from wheel_spokes ws
  left join products p on p.id = ws.product_id
  where ws.tenant_id = p_tenant_id
    and ws.is_active = true
    and ws.length_mm between (p_required_length_mm - p_tolerance_mm) and (p_required_length_mm + p_tolerance_mm)
  order by length_difference_mm, stock_quantity desc, ws.manufacturer;
end;
$$;


--
-- TOC entry 1196 (class 1255 OID 32695)
-- Name: generate_expense_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_expense_number() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_next bigint;
  v_number text;
  v_attempts int := 0;
BEGIN
  LOOP
    v_attempts := v_attempts + 1;
    
    -- Get next sequence value
    SELECT nextval('expense_number_seq') INTO v_next;
    v_number := format('GTO-%s', lpad(v_next::text, 5, '0'));
    
    -- Check if this number already exists
    IF NOT EXISTS (SELECT 1 FROM public.expenses WHERE expense_number = v_number) THEN
      RETURN v_number;
    END IF;
    
    -- Safety: don't loop forever
    IF v_attempts > 100 THEN
      -- Fallback to timestamp-based number
      RETURN format('GTO-%s', lpad((extract(epoch from now())::bigint % 100000)::text, 5, '0'));
    END IF;
  END LOOP;
END;
$$;


--
-- TOC entry 1533 (class 1255 OID 78793)
-- Name: generate_f29_from_accounting(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_f29_from_accounting(p_tenant_id uuid, p_year integer, p_month integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_start_date date;
  v_end_date date;
  v_iva_debito numeric(15,2);
  v_iva_credito numeric(15,2);
  v_ventas_netas numeric(15,2);
  v_ppm_monto numeric(15,2);
  v_retencion_honorarios numeric(15,2);
  v_retencion_segunda numeric(15,2);
  v_iva_neto numeric(15,2);
  v_total_pagar numeric(15,2);
  v_due_date date;
  v_f29_id uuid;
begin
  -- Calculate period dates
  v_start_date := make_date(p_year, p_month, 1);
  v_end_date := (v_start_date + interval '1 month' - interval '1 day')::date;
  
  -- Due date: 12th of following month
  v_due_date := make_date(p_year, p_month, 1) + interval '1 month 12 days' - interval '1 day';
  
  -- Calculate IVA Débito (Sales tax collected) - Account 2150
  -- Sum CREDIT movements (IVA débito is a liability, increases with CREDIT)
  select coalesce(sum(jl.credit_amount - jl.debit_amount), 0)
  into v_iva_debito
  from journal_lines jl
  join journal_entries je on jl.entry_id = je.id
  join accounts a on jl.account_id = a.id
  where je.tenant_id = p_tenant_id
    and a.code = '2150'
    and je.entry_date >= v_start_date
    and je.entry_date <= v_end_date
    and je.status = 'posted';
  
  -- Calculate IVA Crédito (Purchase tax paid) - Account 2120
  -- Sum DEBIT movements (IVA crédito is an asset, increases with DEBIT)
  select coalesce(sum(jl.debit_amount - jl.credit_amount), 0)
  into v_iva_credito
  from journal_lines jl
  join journal_entries je on jl.entry_id = je.id
  join accounts a on jl.account_id = a.id
  where je.tenant_id = p_tenant_id
    and a.code = '2120'
    and je.entry_date >= v_start_date
    and je.entry_date <= v_end_date
    and je.status = 'posted';
  
  -- Calculate Net Sales (Revenue) - Account 4100
  -- Sum CREDIT movements (revenue is CREDIT)
  select coalesce(sum(jl.credit_amount - jl.debit_amount), 0)
  into v_ventas_netas
  from journal_lines jl
  join journal_entries je on jl.entry_id = je.id
  join accounts a on jl.account_id = a.id
  where je.tenant_id = p_tenant_id
    and a.code = '4100'
    and je.entry_date >= v_start_date
    and je.entry_date <= v_end_date
    and je.status = 'posted';
  
  -- Calculate PPM (1% of net sales by default)
  -- TODO: Get tenant-specific PPM rate from settings
  v_ppm_monto := v_ventas_netas * 0.01;
  
  -- Calculate withholdings (if HR module tracks this)
  -- TODO: Query payroll/honorarios tables when implemented
  v_retencion_honorarios := 0;
  v_retencion_segunda := 0;
  
  -- Calculate net IVA (positive = owe to SII, negative = SII owes us)
  v_iva_neto := v_iva_debito - v_iva_credito;
  
  -- Calculate total to pay
  v_total_pagar := greatest(v_iva_neto, 0) + v_ppm_monto + v_retencion_honorarios + v_retencion_segunda;
  
  -- Insert or update F29 declaration
  insert into f29_declarations (
    tenant_id,
    period_month,
    period_year,
    status,
    iva_debito_ventas,
    iva_debito_total,
    iva_credito_compras,
    iva_credito_total,
    iva_neto,
    ppm_ventas_netas,
    ppm_monto,
    retencion_honorarios,
    retencion_segunda_categoria,
    total_a_pagar,
    total_a_favor,
    due_date,
    updated_at
  ) values (
    p_tenant_id,
    p_month,
    p_year,
    'draft',
    v_iva_debito,
    v_iva_debito,
    v_iva_credito,
    v_iva_credito,
    v_iva_neto,
    v_ventas_netas,
    v_ppm_monto,
    v_retencion_honorarios,
    v_retencion_segunda,
    case when v_iva_neto >= 0 then v_total_pagar else 0 end,
    case when v_iva_neto < 0 then abs(v_iva_neto) else 0 end,
    v_due_date,
    now()
  )
  on conflict (tenant_id, period_year, period_month)
  do update set
    iva_debito_ventas = excluded.iva_debito_ventas,
    iva_debito_total = excluded.iva_debito_total,
    iva_credito_compras = excluded.iva_credito_compras,
    iva_credito_total = excluded.iva_credito_total,
    iva_neto = excluded.iva_neto,
    ppm_ventas_netas = excluded.ppm_ventas_netas,
    ppm_monto = excluded.ppm_monto,
    retencion_honorarios = excluded.retencion_honorarios,
    retencion_segunda_categoria = excluded.retencion_segunda_categoria,
    total_a_pagar = excluded.total_a_pagar,
    total_a_favor = excluded.total_a_favor,
    due_date = excluded.due_date,
    updated_at = now()
  returning id into v_f29_id;
  
  return jsonb_build_object(
    'success', true,
    'f29_id', v_f29_id,
    'period', format('%s/%s', p_month, p_year),
    'iva_debito', v_iva_debito,
    'iva_credito', v_iva_credito,
    'iva_neto', v_iva_neto,
    'ventas_netas', v_ventas_netas,
    'ppm_monto', v_ppm_monto,
    'total_a_pagar', v_total_pagar
  );
end;
$$;


