--

CREATE FUNCTION public.generate_mechanic_job_number() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_next_number integer;
  v_job_number text;
begin
  -- Get next value from sequence (guaranteed unique, no race conditions)
  v_next_number := nextval('public.mechanic_job_number_seq');
  
  -- Format as PG-00001, PG-00002, etc.
  v_job_number := 'PG-' || lpad(v_next_number::text, 5, '0');
  
  return v_job_number;
end;
$$;


--
-- TOC entry 1175 (class 1255 OID 30680)
-- Name: generate_online_order_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_online_order_number() RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
  v_year text;
  v_count integer;
  v_number text;
begin
  v_year := to_char(now(), 'YY');
  
  select count(*) + 1 into v_count
  from online_orders
  where extract(year from created_at) = extract(year from now());
  
  v_number := 'WEB-' || v_year || '-' || lpad(v_count::text, 5, '0');
  
  return v_number;
end;
$$;


--
-- TOC entry 563 (class 1255 OID 161503)
-- Name: generate_payroll_voucher_draft(date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_payroll_voucher_draft(p_start_date date, p_end_date date, p_period_label text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_tenant_id UUID;
  v_voucher_id UUID;
  v_voucher_number TEXT;
  v_total_hours NUMERIC := 0;
  v_total_amount NUMERIC := 0;
  v_emp_count INTEGER := 0;
  emp RECORD;
  v_hours NUMERIC;
  v_overtime NUMERIC;
  v_rate NUMERIC;
  v_overtime_rate NUMERIC;
  v_regular_amt NUMERIC;
  v_overtime_amt NUMERIC;
BEGIN
  v_tenant_id := public.user_tenant_id();
  
  -- Generate voucher number (PV-00001)
  v_voucher_number := 'PV-' || LPAD(nextval('payroll_voucher_number_seq')::TEXT, 5, '0');
  
  -- Create the voucher header
  INSERT INTO payroll_vouchers (
    tenant_id, voucher_number, period_start, period_end, period_label,
    status, created_by
  ) VALUES (
    v_tenant_id, v_voucher_number, p_start_date, p_end_date, 
    COALESCE(p_period_label, 'Periodo: ' || p_start_date || ' - ' || p_end_date),
    'draft', auth.uid()
  )
  RETURNING id INTO v_voucher_id;
  
  -- Create lines for each active employee
  FOR emp IN 
    SELECT e.*, 
           COALESCE(e.hourly_rate, 0) as rate
    FROM employees e
    WHERE e.tenant_id = v_tenant_id
      AND e.status = 'active'
  LOOP
    -- Get hours summary for this period
    SELECT 
      COALESCE(SUM(worked_hours), 0),
      COALESCE(SUM(overtime_hours), 0)
    INTO v_hours, v_overtime
    FROM attendances
    WHERE employee_id = emp.id
      AND check_in::DATE BETWEEN p_start_date AND p_end_date;
    
    v_rate := emp.rate;
    v_overtime_rate := v_rate * 1.5;
    v_regular_amt := v_hours * v_rate;
    v_overtime_amt := v_overtime * v_overtime_rate;
    
    -- INSERT LINE with explicit payment_method_id
    INSERT INTO payroll_voucher_lines (
      tenant_id, voucher_id, employee_id, employee_name,
      worked_hours, overtime_hours, hourly_rate, overtime_rate,
      regular_amount, overtime_amount, total_amount,
      payment_method, -- Legacy
      payment_method_id, -- NEW: Proper FK
      salary_account_id, 
      is_included
    ) VALUES (
      v_tenant_id, v_voucher_id, emp.id, 
      emp.first_name || ' ' || emp.last_name,
      v_hours, v_overtime, v_rate, v_overtime_rate,
      v_regular_amt, v_overtime_amt, v_regular_amt + v_overtime_amt,
      COALESCE(emp.preferred_payment_method::TEXT, 'transfer'), -- Keep separate purely for display fallback
      emp.preferred_payment_method_id, -- USE THE REAL ID
      emp.salary_account_id, 
      (v_hours + v_overtime > 0)
    );
    
    if (v_hours + v_overtime > 0) then
        v_total_hours := v_total_hours + v_hours + v_overtime;
        v_total_amount := v_total_amount + v_regular_amt + v_overtime_amt;
        v_emp_count := v_emp_count + 1;
    end if;
    
  END LOOP;
  
  -- Update voucher totals
  UPDATE payroll_vouchers
  SET total_hours = v_total_hours,
      total_amount = v_total_amount,
      employee_count = v_emp_count
  WHERE id = v_voucher_id;
  
  RETURN v_voucher_id;
END;
$$;


--
-- TOC entry 618 (class 1255 OID 24934)
-- Name: get_account_balance(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_account_balance(p_account_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account record;
  v_total_debit numeric(14,2) := 0;
  v_total_credit numeric(14,2) := 0;
  v_balance numeric(14,2) := 0;
begin
  -- Get account type to determine balance calculation
  select type into v_account
  from accounts
  where id = p_account_id
    and tenant_id = user_tenant_id();
  
  if not found then
    raise exception 'Account not found: %', p_account_id;
  end if;
  
  -- Sum debits and credits for this account in the period
  select
    coalesce(sum(debit_amount), 0),
    coalesce(sum(credit_amount), 0)
  into v_total_debit, v_total_credit
  from journal_lines jl
  inner join journal_entries je on je.id = jl.entry_id
  where jl.account_id = p_account_id
    and je.entry_date >= p_start_date
    and je.entry_date <= p_end_date
    and je.status = 'posted'
    and jl.tenant_id = user_tenant_id()
    and je.tenant_id = user_tenant_id();
  
  -- Calculate balance based on account type
  -- Assets and Expenses: Debit increases balance (debit - credit)
  -- Liabilities, Equity, Income: Credit increases balance (credit - debit)
  if v_account.type in ('asset', 'expense') then
    v_balance := v_total_debit - v_total_credit;
  else
    v_balance := v_total_credit - v_total_debit;
  end if;
  
  return v_balance;
end;
$$;


--
-- TOC entry 954 (class 1255 OID 29071)
-- Name: get_attendance_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_attendance_summary(p_employee_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(total_days integer, total_hours numeric, total_overtime numeric, average_hours numeric, late_arrivals integer, early_departures integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  select 
    count(distinct date(a.check_in))::integer as total_days,
    coalesce(sum(a.worked_hours), 0) as total_hours,
    coalesce(sum(a.overtime_hours), 0) as total_overtime,
    coalesce(avg(a.worked_hours), 0) as average_hours,
    count(*) filter (where extract(hour from a.check_in) > 9)::integer as late_arrivals,
    count(*) filter (where extract(hour from a.check_out) < 18)::integer as early_departures
  from attendances a
  where a.employee_id = p_employee_id
    and a.status in ('completed', 'approved')
    and date(a.check_in) between p_start_date and p_end_date;
end;
$$;


--
-- TOC entry 942 (class 1255 OID 162634)
-- Name: get_attendance_summary_for_period(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_attendance_summary_for_period(p_start_date date, p_end_date date) RETURNS TABLE(employee_id uuid, employee_name text, total_hours numeric, total_days integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  select 
    e.id as employee_id,
    (e.first_name || ' ' || e.last_name) as employee_name,
    coalesce(sum(a.worked_hours), 0)::numeric as total_hours,
    count(distinct date(a.check_in))::integer as total_days
  from employees e
  left join attendances a on a.employee_id = e.id
    and a.status in ('completed', 'approved')
    and date(a.check_in) between p_start_date and p_end_date
  where e.status = 'active'
  group by e.id, e.first_name, e.last_name
  order by e.first_name, e.last_name;
end;
$$;


