-- TOC entry 969 (class 1255 OID 32474)
-- Name: get_expense_breakdown(timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_expense_breakdown(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_limit integer DEFAULT 6) RETURNS TABLE(account_id uuid, account_code text, account_name text, amount numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  select
    a.id,
    a.code,
    a.name,
    coalesce(sum(jl.debit_amount), 0) - coalesce(sum(jl.credit_amount), 0)
      as amount
  from accounts a
  join journal_lines jl on jl.account_id = a.id AND jl.tenant_id = user_tenant_id()
  join journal_entries je on je.id = jl.entry_id AND je.tenant_id = user_tenant_id()
  where a.type = 'expense'
    and a.is_active = true
    and a.tenant_id = user_tenant_id()
    and je.status = 'posted'
    and je.entry_date >= p_start_date
    and je.entry_date <= p_end_date
  group by a.id, a.code, a.name
  having coalesce(sum(jl.debit_amount), 0) - coalesce(sum(jl.credit_amount), 0) <> 0
  order by amount desc
  limit greatest(p_limit, 1);
end;
$$;


--
-- TOC entry 1498 (class 1255 OID 165092)
-- Name: get_expense_category_name_for_account(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_expense_category_name_for_account(p_account_code text, p_account_name text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_code text := coalesce(p_account_code, '');
  v_base_code text;
  v_name text := lower(coalesce(p_account_name, ''));
begin
  v_base_code := regexp_replace(v_code, '-.*$', ''); -- supports 6101-01

  if v_base_code like '51%' then return 'Costo de Ventas'; end if;
  if v_base_code like '610%' then return 'Nómina'; end if;

  if v_base_code = '6201' then return 'Arriendo';
  elsif v_base_code = '6202' then return 'Servicios Básicos';
  elsif v_base_code = '6203' then return 'Telefonía e Internet';
  elsif v_base_code = '6204' then return 'Mantención y Reparaciones';
  elsif v_base_code = '6205' then return 'Suministros de Oficina';
  end if;

  if v_base_code = '6301' then return 'Marketing y Publicidad';
  elsif v_base_code = '6302' then return 'Comisiones de Venta';
  end if;

  if v_base_code = '6401' then return 'Gastos de Viaje'; end if;
  if v_base_code = '6501' then return 'Seguros';
  elsif v_base_code = '6502' then return 'Patentes y Contribuciones';
  end if;

  if v_base_code = '6601' then return 'Gastos Financieros'; end if;
  if v_base_code = '6701' then return 'Depreciación'; end if;
  if v_base_code = '6801' then return 'Gastos Varios'; end if;

  -- Fallback for custom accounts
  if v_name like '%nómina%' or v_name like '%nomina%' or v_name like '%sueldo%' or v_name like '%salario%' then
    return 'Nómina';
  end if;
  if v_name like '%arriendo%' then return 'Arriendo'; end if;
  if v_name like '%internet%' or v_name like '%telefon%' then return 'Telefonía e Internet'; end if;
  if v_name like '%luz%' or v_name like '%agua%' or v_name like '%gas%'
     or v_name like '%servicio básico%' or v_name like '%servicios básicos%' then
    return 'Servicios Básicos';
  end if;

  return 'Otros Gastos';
end;
$_$;


--
-- TOC entry 1883 (class 1255 OID 176763)
-- Name: get_expense_period_details(timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_expense_period_details(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_is_cash_flow boolean) RETURNS TABLE(id uuid, document_number text, description text, account_name text, amount numeric, transaction_date date, source_type text, account_id uuid, account_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_is_cash_flow THEN
    -- Cash Flow: Return payments + paid expenses
    RETURN QUERY
    -- 1. Purchase Payments (Payments to suppliers)
    -- These are generally against Accounts Payable, so specific expense account is unknown/mixed.
    -- We leave account_id/code as NULL or default.
    SELECT
      pp.id,
      pi.invoice_number AS document_number,
      COALESCE(s.name, 'Proveedor') AS description,
      'Pago a Proveedor'::text AS account_name,
      pp.amount::numeric(14,2),
      pp.date::date AS transaction_date,
      'purchase_payment'::text AS source_type,
      NULL::uuid AS account_id,
      NULL::text AS account_code
    FROM purchase_payments pp
    LEFT JOIN purchase_invoices pi ON pi.id = pp.invoice_id
    LEFT JOIN suppliers s ON s.id = pi.supplier_id
    WHERE pp.date >= p_start_date
      AND pp.date < p_end_date
      AND pp.tenant_id = user_tenant_id()
    
    UNION ALL
    
    -- 2. Paid operating expenses (salaries, rent, utilities, etc.)
    SELECT
      e.id,
      e.expense_number AS document_number,
      COALESCE(e.supplier_name, 'Gasto') AS description,
      a.name AS account_name,
      el.total::numeric(14,2) AS amount,
      e.paid_at::date AS transaction_date,
      'expense'::text AS source_type,
      a.id AS account_id,
      a.code AS account_code
    FROM expenses e
    JOIN expense_lines el ON el.expense_id = e.id
    JOIN accounts a ON a.id = el.account_id
    WHERE e.payment_status = 'paid'
      AND e.paid_at >= p_start_date
      AND e.paid_at < p_end_date
      AND e.tenant_id = user_tenant_id()
      AND a.type = 'expense'
    
    ORDER BY transaction_date DESC, amount DESC;
    
  ELSE
    -- Accrual: Return expense journal entries (This feeds the Pie Chart usually)
    RETURN QUERY
    SELECT
      je.id,
      COALESCE(je.reference, '') AS document_number,
      je.description,
      a.name AS account_name,
      (COALESCE(SUM(jl.debit_amount), 0) - COALESCE(SUM(jl.credit_amount), 0))::numeric(14,2) AS amount,
      je.entry_date::date AS transaction_date,
      'journal_entry'::text AS source_type,
      a.id AS account_id,
      a.code AS account_code
    FROM journal_lines jl
    JOIN journal_entries je ON je.id = jl.entry_id
    JOIN accounts a ON a.id = jl.account_id
    WHERE je.status = 'posted'
      AND a.type = 'expense'
      AND je.entry_date >= p_start_date
      AND je.entry_date < p_end_date
      AND je.tenant_id = user_tenant_id()
      AND jl.tenant_id = user_tenant_id()
      AND a.tenant_id = user_tenant_id()
    GROUP BY je.id, je.reference, je.description, a.name, je.entry_date, a.id, a.code
    HAVING (COALESCE(SUM(jl.debit_amount), 0) - COALESCE(SUM(jl.credit_amount), 0)) <> 0
    ORDER BY je.entry_date DESC, amount DESC;
  END IF;
END;
$$;


--
-- TOC entry 621 (class 1255 OID 148443)
-- Name: get_full_sets_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_full_sets_count(p_set_product_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_min_sets INTEGER;
BEGIN
  SELECT MIN(
    FLOOR(COALESCE(p.stock_quantity, p.inventory_qty, 0)::NUMERIC / psc.quantity_in_set)
  )::INTEGER
  INTO v_min_sets
  FROM product_set_components psc
  JOIN products p ON p.id = psc.component_product_id
  WHERE psc.set_product_id = p_set_product_id;
  
  RETURN COALESCE(v_min_sets, 0);
END;
$$;


--
-- TOC entry 1444 (class 1255 OID 34005)
-- Name: get_income_expense_daily_timeseries(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_expense_daily_timeseries(p_start_date timestamp with time zone, p_end_date timestamp with time zone) RETURNS TABLE(period_start date, period_end date, income numeric, expense numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with day_windows as (
    select
      (date_trunc('day', p_start_date) + make_interval(days => d.day_index))::date as period_start
    from generate_series(0, extract(days from (p_end_date - p_start_date))::integer) as d(day_index)
  )
  select
    dw.period_start::date,
    dw.period_start::date as period_end,
    coalesce(
      (
        select
          sum(coalesce(jl.credit_amount, 0) - coalesce(jl.debit_amount, 0))
        from journal_lines jl
        join journal_entries je on je.id = jl.entry_id
        join accounts a on a.id = jl.account_id
        where je.status = 'posted'
          and a.type = 'income'
          and je.entry_date >= dw.period_start
          and je.entry_date < dw.period_start + interval '1 day'
          and je.tenant_id = user_tenant_id()
          and jl.tenant_id = user_tenant_id()
          and a.tenant_id = user_tenant_id()
      ),
      0
    )::numeric(14,2) as income,
    coalesce(
      (
        select
          sum(coalesce(jl.debit_amount, 0) - coalesce(jl.credit_amount, 0))
        from journal_lines jl
        join journal_entries je on je.id = jl.entry_id
        join accounts a on a.id = jl.account_id
        where je.status = 'posted'
          and a.type = 'expense'
          and je.entry_date >= dw.period_start
          and je.entry_date < dw.period_start + interval '1 day'
          and je.tenant_id = user_tenant_id()
          and jl.tenant_id = user_tenant_id()
          and a.tenant_id = user_tenant_id()
      ),
      0
    )::numeric(14,2) as expense
  from day_windows dw
  order by dw.period_start;
$$;


--
-- TOC entry 910 (class 1255 OID 153785)
-- Name: get_income_expense_daily_timeseries(timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_expense_daily_timeseries(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_is_cash_flow boolean DEFAULT false) RETURNS TABLE(period_start date, period_end date, income numeric, expense numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with day_windows as (
    select
      (date_trunc('day', p_start_date) + make_interval(days => d.day_index))::date as period_start
    from generate_series(0, extract(days from (p_end_date - p_start_date))::integer) as d(day_index)
  )
  select
    dw.period_start::date,
    dw.period_start::date as period_end,

    -- INCOME CALCULATION
    coalesce(
      case when p_is_cash_flow then
        -- Cash Flow: Sales Payments
        (
          select sum(amount)
          from sales_payments sp
          where sp.date >= dw.period_start
            and sp.date < dw.period_start + interval '1 day'
            and sp.tenant_id = user_tenant_id()
        )
      else
        -- Accrual: Income Journal Entries
        (
          select
            sum(coalesce(jl.credit_amount, 0) - coalesce(jl.debit_amount, 0))
          from journal_lines jl
          join journal_entries je on je.id = jl.entry_id
          join accounts a on a.id = jl.account_id
          where je.status = 'posted'
            and a.type = 'income'
            and je.entry_date >= dw.period_start
            and je.entry_date < dw.period_start + interval '1 day'
            and je.tenant_id = user_tenant_id()
            and jl.tenant_id = user_tenant_id()
            and a.tenant_id = user_tenant_id()
        )
      end,
      0
    )::numeric(14,2) as income,

    -- EXPENSE CALCULATION (FIXED)
    coalesce(
      case when p_is_cash_flow then
        -- Cash Flow: Sum of ALL cash outflows on this day
        (
          -- 1. Purchase payments
          coalesce((
            select sum(amount)
            from purchase_payments pp
            where pp.date >= dw.period_start
              and pp.date < dw.period_start + interval '1 day'
              and pp.tenant_id = user_tenant_id()
          ), 0)
          +
          -- 2. Paid operating expenses
          coalesce((
            select sum(el.total)
            from expenses e
            join expense_lines el on el.expense_id = e.id
            join accounts a on a.id = el.account_id
            where e.payment_status = 'paid'
              and e.paid_at >= dw.period_start
              and e.paid_at < dw.period_start + interval '1 day'
              and e.tenant_id = user_tenant_id()
              and a.type = 'expense'
          ), 0)
        )
      else
        -- Accrual: Expense Journal Entries
        (
          select
            sum(coalesce(jl.debit_amount, 0) - coalesce(jl.credit_amount, 0))
          from journal_lines jl
          join journal_entries je on je.id = jl.entry_id
          join accounts a on a.id = jl.account_id
          where je.status = 'posted'
            and a.type = 'expense'
            and je.entry_date >= dw.period_start
            and je.entry_date < dw.period_start + interval '1 day'
            and je.tenant_id = user_tenant_id()
            and jl.tenant_id = user_tenant_id()
            and a.tenant_id = user_tenant_id()
        )
      end,
      0
    )::numeric(14,2) as expense

  from day_windows dw
  order by dw.period_start;
$$;


--
-- TOC entry 1210 (class 1255 OID 32473)
-- Name: get_income_expense_timeseries(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_expense_timeseries(p_months integer DEFAULT 12) RETURNS TABLE(period_start date, period_end date, income numeric, expense numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with month_windows as (
    select
      date_trunc('month', current_timestamp) - make_interval(months => m.month_index) as period_start
    from generate_series(0, greatest(p_months, 1) - 1) as m(month_index)
  )
  select
    mw.period_start::date,
    (mw.period_start + interval '1 month' - interval '1 day')::date as period_end,
    coalesce(
      (
        select
          sum(coalesce(jl.credit_amount, 0) - coalesce(jl.debit_amount, 0))
        from journal_lines jl
        join journal_entries je on je.id = jl.entry_id
        join accounts a on a.id = jl.account_id
        where je.status = 'posted'
          and a.type = 'income'
          and je.entry_date >= mw.period_start
          and je.entry_date < mw.period_start + interval '1 month'
          and je.tenant_id = user_tenant_id()
          and jl.tenant_id = user_tenant_id()
          and a.tenant_id = user_tenant_id()
      ),
      0
    )::numeric(14,2) as income,
    coalesce(
      (
        select
          sum(coalesce(jl.debit_amount, 0) - coalesce(jl.credit_amount, 0))
        from journal_lines jl
        join journal_entries je on je.id = jl.entry_id
        join accounts a on a.id = jl.account_id
        where je.status = 'posted'
          and a.type = 'expense'
          and je.entry_date >= mw.period_start
          and je.entry_date < mw.period_start + interval '1 month'
          and je.tenant_id = user_tenant_id()
          and jl.tenant_id = user_tenant_id()
          and a.tenant_id = user_tenant_id()
      ),
      0
    )::numeric(14,2) as expense
  from month_windows mw
  order by mw.period_start;
$$;


--
-- TOC entry 1391 (class 1255 OID 153784)
-- Name: get_income_expense_timeseries(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_expense_timeseries(p_months integer DEFAULT 12, p_is_cash_flow boolean DEFAULT false) RETURNS TABLE(period_start date, period_end date, income numeric, expense numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with month_windows as (
    select
      date_trunc('month', current_timestamp) - make_interval(months => m.month_index) as period_start
    from generate_series(0, greatest(p_months, 1) - 1) as m(month_index)
  )
  select
    mw.period_start::date,
    (mw.period_start + interval '1 month' - interval '1 day')::date as period_end,
    
    -- INCOME CALCULATION
    coalesce(
      case when p_is_cash_flow then
        -- Cash Flow: Sum of Sales Payments received in this period
        (
          select sum(amount)
          from sales_payments sp
          where sp.date >= mw.period_start
            and sp.date < mw.period_start + interval '1 month'
            and sp.tenant_id = user_tenant_id()
        )
      else
        -- Accrual: Sum of Income Journal Entries (posted)
        (
          select
            sum(coalesce(jl.credit_amount, 0) - coalesce(jl.debit_amount, 0))
          from journal_lines jl
          join journal_entries je on je.id = jl.entry_id
          join accounts a on a.id = jl.account_id
          where je.status = 'posted'
            and a.type = 'income'
            and je.entry_date >= mw.period_start
            and je.entry_date < mw.period_start + interval '1 month'
            and je.tenant_id = user_tenant_id()
            and jl.tenant_id = user_tenant_id()
            and a.tenant_id = user_tenant_id()
        )
      end,
      0
    )::numeric(14,2) as income,

    -- EXPENSE CALCULATION (FIXED)
    coalesce(
      case when p_is_cash_flow then
        -- Cash Flow: Sum of ALL cash outflows in this period
        (
          -- 1. Purchase payments (payments to suppliers for inventory/purchases)
          coalesce((
            select sum(amount)
            from purchase_payments pp
            where pp.date >= mw.period_start
              and pp.date < mw.period_start + interval '1 month'
              and pp.tenant_id = user_tenant_id()
          ), 0)
          +
          -- 2. Paid operating expenses (salaries, rent, utilities, services, etc.)
          coalesce((
            select sum(el.total)
            from expenses e
            join expense_lines el on el.expense_id = e.id
            join accounts a on a.id = el.account_id
            where e.payment_status = 'paid'
              and e.paid_at >= mw.period_start
              and e.paid_at < mw.period_start + interval '1 month'
              and e.tenant_id = user_tenant_id()
              and a.type = 'expense'
          ), 0)
        )
      else
        -- Accrual: Sum of Expense Journal Entries (posted)
        (
          select
            sum(coalesce(jl.debit_amount, 0) - coalesce(jl.credit_amount, 0))
          from journal_lines jl
          join journal_entries je on je.id = jl.entry_id
          join accounts a on a.id = jl.account_id
          where je.status = 'posted'
            and a.type = 'expense'
            and je.entry_date >= mw.period_start
            and je.entry_date < mw.period_start + interval '1 month'
            and je.tenant_id = user_tenant_id()
            and jl.tenant_id = user_tenant_id()
            and a.tenant_id = user_tenant_id()
        )
      end,
      0
    )::numeric(14,2) as expense

  from month_windows mw
  order by mw.period_start;
$$;


--
-- TOC entry 922 (class 1255 OID 176761)
-- Name: get_income_period_details(timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_period_details(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_is_cash_flow boolean DEFAULT false) RETURNS TABLE(id uuid, document_number text, description text, customer_name text, amount numeric, transaction_date date, source_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_is_cash_flow then
    -- Cash Flow: Return sales payments received in this period
    return query
    select
      sp.id,
      coalesce(si.invoice_number, 'Pago') as document_number,
      coalesce(pm.name, 'Pago recibido') as description,
      coalesce(c.name, 'Cliente') as customer_name,
      sp.amount::numeric(14,2),
      sp.date::date as transaction_date,
      'sales_payment'::text as source_type
    from sales_payments sp
    left join sales_invoices si on si.id = sp.invoice_id
    left join customers c on c.id = si.customer_id
    left join payment_methods pm on pm.id = sp.payment_method_id
    where sp.date >= p_start_date
      and sp.date < p_end_date
      and sp.tenant_id = user_tenant_id()
    order by sp.date desc, sp.amount desc;
  else
    -- Accrual: Return sales invoices posted in this period
    -- Use sales_invoices as main source with their total amounts (excluding tax)
    return query
    select
      si.id,
      si.invoice_number as document_number,
      'Venta' as description,
      coalesce(c.name, 'Cliente') as customer_name,
      si.subtotal::numeric(14,2) as amount,
      si.date::date as transaction_date,
      'sales_invoice'::text as source_type
    from sales_invoices si
    left join customers c on c.id = si.customer_id
    where si.status in ('sent', 'confirmed', 'paid')
      and si.date >= p_start_date
      and si.date < p_end_date
      and si.tenant_id = user_tenant_id()
    order by si.date desc, si.subtotal desc;
  end if;
end;
$$;


--
-- TOC entry 727 (class 1255 OID 24942)
-- Name: get_income_statement_data(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_statement_data(p_start_date timestamp with time zone, p_end_date timestamp with time zone) RETURNS TABLE(category text, category_label text, account_code text, account_name text, amount numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  select
    a.category,
    case a.category
      when 'operatingIncome' then 'Ingresos Operacionales'
      when 'nonOperatingIncome' then 'Ingresos No Operacionales'
      when 'costOfGoodsSold' then 'Costo de Ventas'
      when 'operatingExpense' then 'Gastos Operacionales'
      when 'financialExpense' then 'Gastos Financieros'
      when 'taxExpense' then 'Impuestos'
      else a.category
    end as category_label,
    a.code as account_code,
    a.name as account_name,
    case
      when a.type = 'income' then
        coalesce(sum(jl.credit_amount), 0) - coalesce(sum(jl.debit_amount), 0)
      when a.type = 'expense' then
        coalesce(sum(jl.debit_amount), 0) - coalesce(sum(jl.credit_amount), 0)
      else 0
    end::numeric(14,2) as amount
  from accounts a
  -- CRITICAL FIX: Use INNER JOIN to ensure we only sum lines that actually belong 
  -- to entries within the date range. LEFT JOIN was including all lines regardless of date match.
  join journal_lines jl on jl.account_id = a.id AND jl.tenant_id = user_tenant_id()
  join journal_entries je on je.id = jl.entry_id
    and je.entry_date >= p_start_date
    and je.entry_date <= p_end_date
    and je.status = 'posted'
    and je.tenant_id = user_tenant_id()
  where a.type in ('income', 'expense')
    and a.is_active = true
    and a.tenant_id = user_tenant_id()
  group by a.id, a.code, a.name, a.type, a.category
  having (coalesce(sum(jl.debit_amount), 0) <> 0 
       or coalesce(sum(jl.credit_amount), 0) <> 0)
  order by a.code;
end;
$$;


--
-- TOC entry 2090 (class 1255 OID 153886)
-- Name: get_income_statement_data(timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_income_statement_data(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_is_cash_flow boolean DEFAULT false) RETURNS TABLE(category text, category_label text, account_code text, account_name text, amount numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_is_cash_flow THEN
    -- CASH FLOW STATEMENT (Estado de Flujo de Efectivo)
    RETURN QUERY
    
    -- CASH IN: Customer payments
    SELECT 
      'operatingIncome'::text,
      'Ingresos de Efectivo'::text,
      '4000'::text,
      'Cobros de Clientes'::text,
      COALESCE(SUM(sp.amount), 0)::numeric(14,2)
    FROM sales_payments sp
    WHERE sp.date >= p_start_date
      AND sp.date <= p_end_date
      AND sp.tenant_id = user_tenant_id()
      
    UNION ALL
    
    -- CASH OUT: Payments to suppliers
    SELECT 
      'costOfGoodsSold'::text,
      'Egresos de Efectivo - Proveedores'::text,
      '5000'::text,
      'Pagos a Proveedores'::text,
      COALESCE(SUM(pp.amount), 0)::numeric(14,2)
    FROM purchase_payments pp
    WHERE pp.date >= p_start_date
      AND pp.date <= p_end_date
      AND pp.tenant_id = user_tenant_id()
      
    UNION ALL
    
    -- CASH OUT: Operating expenses paid
    SELECT 
      a.category,
      'Egresos de Efectivo - Gastos'::text,
      a.code,
      a.name,
      COALESCE(SUM(el.total), 0)::numeric(14,2)
    FROM expenses e
    JOIN expense_lines el ON el.expense_id = e.id
    JOIN accounts a ON a.id = el.account_id
    WHERE e.payment_status = 'paid'
      AND e.paid_at >= p_start_date
      AND e.paid_at <= p_end_date
      AND e.tenant_id = user_tenant_id()
      AND a.type = 'expense'
    GROUP BY a.category, a.code, a.name;

  ELSE
    -- INCOME STATEMENT (Estado de Resultados) - Accrual Basis
    RETURN QUERY
    SELECT
      a.category,
      CASE a.category
        WHEN 'operatingIncome' THEN 'Ingresos Operacionales'
        WHEN 'nonOperatingIncome' THEN 'Ingresos No Operacionales'
        WHEN 'costOfGoodsSold' THEN 'Costo de Ventas'
        WHEN 'operatingExpense' THEN 'Gastos Operacionales'
        WHEN 'financialExpense' THEN 'Gastos Financieros'
        WHEN 'taxExpense' THEN 'Impuestos'
        ELSE a.category
      END,
      a.code,
      a.name,
      CASE
        WHEN a.type = 'income' THEN
          COALESCE(SUM(jl.credit_amount), 0) - COALESCE(SUM(jl.debit_amount), 0)
        WHEN a.type = 'expense' THEN
          COALESCE(SUM(jl.debit_amount), 0) - COALESCE(SUM(jl.credit_amount), 0)
        ELSE 0
      END::numeric(14,2)
    FROM accounts a
    JOIN journal_lines jl ON jl.account_id = a.id AND jl.tenant_id = user_tenant_id()
    JOIN journal_entries je ON je.id = jl.entry_id
      AND je.entry_date >= p_start_date
      AND je.entry_date <= p_end_date
      AND je.status = 'posted'
      AND je.tenant_id = user_tenant_id()
    WHERE a.type IN ('income', 'expense')
      AND a.is_active = true
      AND a.tenant_id = user_tenant_id()
    GROUP BY a.id, a.code, a.name, a.type, a.category
    HAVING (COALESCE(SUM(jl.debit_amount), 0) <> 0 
         OR COALESCE(SUM(jl.credit_amount), 0) <> 0)
    ORDER BY a.code;
  END IF;
END;
$$;


--
-- TOC entry 1072 (class 1255 OID 88405)
-- Name: get_next_document_number(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_document_number(p_tenant_id uuid, p_document_type text, p_prefix text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_actor_tenant_id uuid;
  v_next_number integer;
  v_max_existing integer := 0;
  v_prefix text;
  v_table_name text;
  v_column_name text;
  v_formatted_number text;
begin
  v_actor_tenant_id := public.user_tenant_id();

  if auth.uid() is not null then
    if v_actor_tenant_id is null then
      raise exception 'Could not resolve tenant for authenticated user';
    end if;

    if p_tenant_id is null or p_tenant_id <> v_actor_tenant_id then
      raise exception 'Cross-tenant document sequence access is not allowed';
    end if;
  end if;

  v_prefix := coalesce(p_prefix, case p_document_type
    when 'sales_invoice' then 'FV'
    when 'purchase_invoice' then 'FC'
    when 'sales_payment' then 'PV'
    when 'purchase_payment' then 'PC'
    when 'journal_entry' then 'AC'
    when 'mechanic_job' then 'PG'
    when 'stock_adjustment' then 'AJ'
    when 'expense' then 'GTO'
    else 'DOC'
  end);

  case p_document_type
    when 'sales_invoice' then
      v_table_name := 'sales_invoices';
      v_column_name := 'invoice_number';
    when 'purchase_invoice' then
      v_table_name := 'purchase_invoices';
      v_column_name := 'invoice_number';
    when 'sales_payment' then
      v_table_name := 'sales_payments';
      v_column_name := 'payment_number';
    when 'purchase_payment' then
      v_table_name := 'purchase_payments';
      v_column_name := 'payment_number';
    when 'journal_entry' then
      v_table_name := 'journal_entries';
      v_column_name := 'entry_number';
    when 'mechanic_job' then
      v_table_name := 'mechanic_jobs';
      v_column_name := 'job_number';
    when 'stock_adjustment' then
      v_table_name := 'stock_adjustments';
      v_column_name := 'reference';
    when 'expense' then
      v_table_name := 'expenses';
      v_column_name := 'expense_number';
    else
      v_table_name := null;
      v_column_name := null;
  end case;

  if v_table_name is not null and v_column_name is not null then
    execute format(
      'select coalesce(max((substring(%1$I from ''([0-9]+)$''))::integer), 0)
         from public.%2$I
        where tenant_id = $1
          and %1$I ~ $2',
      v_column_name,
      v_table_name
    )
    into v_max_existing
    using p_tenant_id, '^' || v_prefix || '-[0-9]+$';
  end if;

  insert into public.document_sequences (tenant_id, document_type, last_number)
  values (p_tenant_id, p_document_type, greatest(v_max_existing, 0) + 1)
  on conflict (tenant_id, document_type)
  do update set
    last_number = greatest(public.document_sequences.last_number, v_max_existing) + 1,
    updated_at = now()
  returning last_number into v_next_number;

  v_formatted_number := v_prefix || '-' || lpad(v_next_number::text, 5, '0');
  return v_formatted_number;
end;
$_$;


--
-- TOC entry 1818 (class 1255 OID 239196)
-- Name: get_product_conversion_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_conversion_status(p_product_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_product public.products;
  v_conversion public.user_activity_log;
  v_restore public.user_activity_log;
  v_conversion_reference text;
  v_restored boolean := false;
  v_restored_inventory boolean := false;
begin
  if p_product_id is null then
    raise exception 'Product ID is required';
  end if;

  select *
    into v_product
    from public.products
   where id = p_product_id
     and tenant_id = public.user_tenant_id()
   limit 1;

  if not found then
    raise exception 'Product not found or not accessible';
  end if;

  select *
    into v_conversion
    from public.user_activity_log
   where tenant_id = v_product.tenant_id
     and action = 'product_conversion'
     and details->>'product_id' = v_product.id::text
   order by created_at desc
   limit 1;

  if not found then
    return jsonb_build_object(
      'product_id', v_product.id,
      'product_name', v_product.name,
      'has_conversion_history', false,
      'can_restore', false,
      'restored', false
    );
  end if;

  v_conversion_reference := v_conversion.details->>'conversion_reference';
  v_restored := coalesce((v_conversion.details->>'restored')::boolean, false);
  v_restored_inventory := coalesce((v_conversion.details->>'restored_inventory')::boolean, false);

  if v_conversion_reference is not null then
    select *
      into v_restore
      from public.user_activity_log
     where tenant_id = v_product.tenant_id
       and action = 'product_conversion_restore'
       and details->>'product_id' = v_product.id::text
       and details->>'source_conversion_reference' = v_conversion_reference
     order by created_at desc
     limit 1;
  end if;

  return jsonb_build_object(
    'product_id', v_product.id,
    'product_name', v_product.name,
    'has_conversion_history', true,
    'can_restore', not v_restored,
    'conversion_reference', v_conversion_reference,
    'conversion_reason', v_conversion.details->>'conversion_reason',
    'conversion_created_at', v_conversion.created_at,
    'converted_quantity', coalesce((v_conversion.details->>'converted_quantity')::integer, 0),
    'inventory_value', coalesce((v_conversion.details->>'inventory_value')::numeric, 0),
    'target_purchase_treatment', v_conversion.details->>'target_purchase_treatment',
    'target_product_type', v_conversion.details->>'target_product_type',
    'journal_entry_id', v_conversion.details->>'journal_entry_id',
    'original_state', coalesce(v_conversion.details->'original_state', '{}'::jsonb),
    'converted_state', coalesce(v_conversion.details->'converted_state', '{}'::jsonb),
    'restored', v_restored,
    'restored_at', coalesce(v_conversion.details->>'restored_at', to_char(v_restore.created_at, 'YYYY-MM-DD"T"HH24:MI:SSOF')),
    'restored_inventory', coalesce(
      nullif(v_conversion.details->>'restored_inventory', '')::boolean,
      nullif(v_restore.details->>'restored_inventory', '')::boolean,
      v_restored_inventory,
      false
    ),
    'restore_reference', coalesce(v_conversion.details->>'restore_reference', v_restore.details->>'restore_reference'),
    'restore_reason', coalesce(v_conversion.details->>'restore_reason', v_restore.details->>'restore_reason'),
    'restore_journal_entry_id', coalesce(v_conversion.details->>'restore_journal_entry_id', v_restore.details->>'journal_entry_id')
  );
end;
$$;


--
-- TOC entry 1585 (class 1255 OID 251486)
-- Name: get_public_featured_products(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_featured_products(p_tenant_id uuid, p_limit integer DEFAULT 10) RETURNS TABLE(id uuid, tenant_id uuid, name text, sku text, barcode text, price numeric, cost numeric, inventory_qty integer, stock_quantity integer, image_url text, image_url_optimized text, image_urls text[], description text, website_description text, category text, category_id uuid, category_name text, brand_id uuid, brand text, model text, manufacturer text, manufacturer_sku text, gtin text, product_type text, track_stock boolean, is_active boolean, is_published boolean, show_on_website boolean, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    p.id,
    p.tenant_id,
    p.name,
    p.sku,
    p.barcode,
    p.price,
    0::numeric as cost,
    p.inventory_qty,
    p.stock_quantity,
    p.image_url,
    p.image_url_optimized,
    p.image_urls,
    p.description,
    p.website_description,
    p.category,
    p.category_id,
    p.category_name,
    p.brand_id,
    p.brand,
    p.model,
    p.manufacturer,
    p.manufacturer_sku,
    p.gtin,
    p.product_type,
    p.track_stock,
    p.is_active,
    p.is_published,
    p.show_on_website,
    p.created_at,
    p.updated_at
  from public.featured_products fp
  join public.products p on p.id = fp.product_id
  where fp.tenant_id = p_tenant_id
    and fp.active = true
    and p.tenant_id = p_tenant_id
    and p.is_active = true
    and coalesce(p.is_published, false) = true
    and coalesce(p.show_on_website, false) = true
  order by fp.order_index asc, p.name asc
  limit greatest(coalesce(p_limit, 10), 0);
$$;


--
-- TOC entry 2008 (class 1255 OID 251487)
-- Name: get_public_product_category_counts(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_product_category_counts(p_tenant_id uuid, p_product_type text DEFAULT NULL::text, p_only_in_stock boolean DEFAULT true) RETURNS TABLE(category_id uuid, product_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p.category_id, count(*) as product_count
  from public.products p
  where p.tenant_id = p_tenant_id
    and p.is_active = true
    and coalesce(p.is_published, false) = true
    and coalesce(p.show_on_website, false) = true
    and (
      nullif(trim(coalesce(p_product_type, '')), '') is null
      or p.product_type = nullif(trim(coalesce(p_product_type, '')), '')
    )
    and (
      not p_only_in_stock
      or p.product_type = 'service'
      or coalesce(p.track_stock, true) = false
      or greatest(coalesce(p.inventory_qty, 0), coalesce(p.stock_quantity, 0)) > 0
    )
  group by p.category_id;
$$;


--
-- TOC entry 1903 (class 1255 OID 251482)
-- Name: get_public_products(uuid, uuid[], uuid[], text, text, text, boolean, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_products(p_tenant_id uuid, p_category_ids uuid[] DEFAULT NULL::uuid[], p_product_ids uuid[] DEFAULT NULL::uuid[], p_sku text DEFAULT NULL::text, p_search_term text DEFAULT NULL::text, p_product_type text DEFAULT NULL::text, p_only_in_stock boolean DEFAULT true, p_sort_by text DEFAULT 'name'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, tenant_id uuid, name text, sku text, barcode text, price numeric, cost numeric, inventory_qty integer, stock_quantity integer, image_url text, image_url_optimized text, image_urls text[], description text, website_description text, category text, category_id uuid, category_name text, brand_id uuid, brand text, model text, manufacturer text, manufacturer_sku text, gtin text, product_type text, track_stock boolean, is_active boolean, is_published boolean, show_on_website boolean, created_at timestamp with time zone, updated_at timestamp with time zone, total_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with args as (
    select
      trim(coalesce(p_search_term, '')) as term,
      regexp_split_to_array(lower(trim(coalesce(p_search_term, ''))), '\s+')
        as tokens,
      greatest(coalesce(p_limit, 20), 0) as page_limit,
      greatest(coalesce(p_offset, 0), 0) as page_offset,
      lower(coalesce(nullif(trim(p_sort_by), ''), 'name')) as sort_by,
      nullif(trim(coalesce(p_sku, '')), '') as wanted_sku,
      nullif(trim(coalesce(p_product_type, '')), '') as wanted_product_type
  ),
  filtered as (
    select p.*
    from public.products p
    cross join args a
    where p.tenant_id = p_tenant_id
      and p.is_active = true
      and coalesce(p.is_published, false) = true
      and coalesce(p.show_on_website, false) = true
      and (
        p_product_ids is null
        or cardinality(p_product_ids) = 0
        or p.id = any(p_product_ids)
      )
      and (
        p_category_ids is null
        or cardinality(p_category_ids) = 0
        or p.category_id = any(p_category_ids)
      )
      and (
        a.wanted_sku is null
        or lower(p.sku) = lower(a.wanted_sku)
      )
      and (
        a.wanted_product_type is null
        or p.product_type = a.wanted_product_type
      )
      and (
        not p_only_in_stock
        or p.product_type = 'service'
        or coalesce(p.track_stock, true) = false
        or greatest(coalesce(p.inventory_qty, 0), coalesce(p.stock_quantity, 0)) > 0
      )
      and (
        a.term = ''
        or not exists (
          select 1
          from unnest(a.tokens) token
          where token <> ''
            and lower(
              concat_ws(
                ' ',
                p.name,
                p.sku,
                p.barcode,
                p.description,
                p.website_description,
                p.brand,
                p.model,
                p.manufacturer,
                p.manufacturer_sku,
                p.gtin
              )
            ) not like '%' || token || '%'
        )
      )
  ),
  counted as (
    select p.*, count(*) over() as row_total
    from filtered p
  )
  select
    p.id,
    p.tenant_id,
    p.name,
    p.sku,
    p.barcode,
    p.price,
    0::numeric as cost,
    p.inventory_qty,
    p.stock_quantity,
    p.image_url,
    p.image_url_optimized,
    p.image_urls,
    p.description,
    p.website_description,
    p.category,
    p.category_id,
    p.category_name,
    p.brand_id,
    p.brand,
    p.model,
    p.manufacturer,
    p.manufacturer_sku,
    p.gtin,
    p.product_type,
    p.track_stock,
    p.is_active,
    p.is_published,
    p.show_on_website,
    p.created_at,
    p.updated_at,
    p.row_total as total_count
  from counted p
  cross join args a
  order by
    case when a.sort_by = 'price_asc' then p.price end asc nulls last,
    case when a.sort_by = 'price_desc' then p.price end desc nulls last,
    case when a.sort_by = 'newest' then p.created_at end desc nulls last,
    p.name asc,
    p.id asc
  limit (select page_limit from args)
  offset (select page_offset from args);
$$;


--
-- TOC entry 1697 (class 1255 OID 157888)
-- Name: get_public_store_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_store_data(p_tenant_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_settings json;
  v_blocks json;
  v_home_page_id uuid;
BEGIN
  -- Get home page ID
  SELECT id INTO v_home_page_id
  FROM website_pages
  WHERE tenant_id = p_tenant_id
    AND is_home = true
    AND is_published = true
  LIMIT 1;
  
  -- Fallback to first published page if no home page
  IF v_home_page_id IS NULL THEN
    SELECT id INTO v_home_page_id
    FROM website_pages
    WHERE tenant_id = p_tenant_id
      AND is_published = true
    ORDER BY created_at
    LIMIT 1;
  END IF;
  
  -- Get all settings as JSON object
  SELECT json_object_agg(key, value)
  INTO v_settings
  FROM website_settings
  WHERE tenant_id = p_tenant_id;
  
  -- Get blocks for home page as JSON array
  SELECT COALESCE(json_agg(
    json_build_object(
      'id', id,
      'block_type', block_type,
      'block_data', block_data,
      'is_visible', is_visible,
      'order_index', order_index
    ) ORDER BY order_index
  ), '[]'::json)
  INTO v_blocks
  FROM website_blocks
  WHERE tenant_id = p_tenant_id
    AND page_id = v_home_page_id
    AND is_visible = true;
  
  -- Return combined result
  RETURN json_build_object(
    'settings', COALESCE(v_settings, '{}'::json),
    'blocks', COALESCE(v_blocks, '[]'::json),
    'home_page_id', v_home_page_id
  );
END;
$$;


--
-- TOC entry 1120 (class 1255 OID 157881)
-- Name: get_public_user_info(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_user_info(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_result jsonb;
begin
  -- 1. Try to find in employees table (via user_id)
  -- Note: user_profiles does not have name column, employees does
  select jsonb_build_object(
    'id', user_id,
    'name', coalesce(first_name || ' ' || last_name, 'Soporte'),
    'avatar_url', photo_url,
    'role', 'employee'
  )
  into v_result
  from public.employees
  where user_id = p_user_id
  limit 1;

  if v_result is not null then
    return v_result;
  end if;

  -- 2. If not found, try customers (for completeness)
  select jsonb_build_object(
    'id', auth_user_id,
    'name', coalesce(name, 'Cliente'),
    'avatar_url', image_url,
    'role', 'customer'
  )
  into v_result
  from public.customers
  where auth_user_id = p_user_id
  limit 1;

  -- 3. Fallback: try auth.users metadata if absolutely necessary (optional)
  if v_result is null then
     select jsonb_build_object(
      'id', id,
      'name', coalesce(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', email),
      'avatar_url', raw_user_meta_data->>'avatar_url',
      'role', 'unknown'
    )
    into v_result
    from auth.users
    where id = p_user_id;
  end if;

  return v_result;
end;
$$;


--
-- TOC entry 1525 (class 1255 OID 148442)
-- Name: get_set_availability(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_set_availability(p_set_product_id uuid) RETURNS TABLE(component_id uuid, component_name text, component_label text, component_position integer, stock_quantity integer, quantity_needed integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    psc.component_product_id AS component_id,
    p.name AS component_name,
    psc.component_label,
    psc.component_position,
    COALESCE(p.stock_quantity, p.inventory_qty, 0)::INTEGER AS stock_quantity,
    psc.quantity_in_set AS quantity_needed
  FROM product_set_components psc
  JOIN products p ON p.id = psc.component_product_id
  WHERE psc.set_product_id = p_set_product_id
  ORDER BY psc.component_position;
END;
$$;


--
-- TOC entry 1354 (class 1255 OID 241625)
-- Name: get_stock_adjustment_details(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stock_adjustment_details(p_adjustment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_adjustment record;
  v_entry record;
  v_counterpart_account_code text;
  v_counterpart_account_name text;
  v_counterpart_debit numeric;
  v_counterpart_credit numeric;
begin
  select
    sa.id,
    sa.tenant_id,
    sa.product_id,
    sa.adjustment_type,
    sa.quantity,
    sa.stock_before,
    sa.stock_after,
    sa.reason,
    sa.reference,
    sa.adjustment_origin,
    sa.adjustment_date,
    sa.created_at,
    sa.created_by,
    p.name as product_name,
    p.sku as product_sku,
    p.cost as unit_cost,
    au.email as created_by_email,
    abs(sa.quantity) * greatest(coalesce(p.cost, 0), 0) as inventory_value
  into v_adjustment
  from public.stock_adjustments sa
  join public.products p
    on p.id = sa.product_id
   and p.tenant_id = sa.tenant_id
  left join auth.users au
    on au.id = sa.created_by
  where sa.id = p_adjustment_id
    and sa.tenant_id = public.user_tenant_id();

  if not found then
    raise exception 'Stock adjustment % not found for current tenant', p_adjustment_id
      using errcode = 'foreign_key_violation';
  end if;

  select
    je.id,
    je.entry_number,
    je.entry_date,
    je.description,
    je.total_debit,
    je.total_credit
  into v_entry
  from public.journal_entries je
  where je.tenant_id = v_adjustment.tenant_id
    and je.source_module = 'stock_adjustment'
    and je.source_reference = v_adjustment.id::text
  order by je.created_at desc
  limit 1;

  if v_entry.id is not null then
    select
      jl.account_code,
      jl.account_name,
      jl.debit_amount,
      jl.credit_amount
    into v_counterpart_account_code,
         v_counterpart_account_name,
         v_counterpart_debit,
         v_counterpart_credit
    from public.journal_lines jl
    where jl.entry_id = v_entry.id
      and jl.account_code <> '1105'
    order by greatest(jl.debit_amount, jl.credit_amount) desc, jl.created_at asc
    limit 1;
  end if;

  return jsonb_build_object(
    'id', v_adjustment.id,
    'product_id', v_adjustment.product_id,
    'product_name', v_adjustment.product_name,
    'product_sku', v_adjustment.product_sku,
    'adjustment_type', v_adjustment.adjustment_type,
    'reference_number', v_adjustment.reference,
    'quantity', v_adjustment.quantity,
    'stock_before', v_adjustment.stock_before,
    'stock_after', v_adjustment.stock_after,
    'reason', v_adjustment.reason,
    'adjustment_origin', v_adjustment.adjustment_origin,
    'adjustment_date', v_adjustment.adjustment_date,
    'created_at', v_adjustment.created_at,
    'created_by', v_adjustment.created_by,
    'created_by_email', v_adjustment.created_by_email,
    'unit_cost', v_adjustment.unit_cost,
    'inventory_value', v_adjustment.inventory_value,
    'journal_entry_id', v_entry.id,
    'journal_entry_number', v_entry.entry_number,
    'journal_entry_date', v_entry.entry_date,
    'journal_entry_description', v_entry.description,
    'counterpart_account_code', v_counterpart_account_code,
    'counterpart_account_name', v_counterpart_account_name,
    'counterpart_debit', v_counterpart_debit,
    'counterpart_credit', v_counterpart_credit
  );
end;
$$;


--
-- TOC entry 1941 (class 1255 OID 37686)
-- Name: get_tenant_users(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tenant_users(p_tenant_id uuid) RETURNS TABLE(id uuid, email text, role text, permissions jsonb, is_active boolean, last_sign_in timestamp with time zone, created_at timestamp with time zone, employee_id uuid, employee_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  select 
    u.id,
    u.email::text,
    coalesce(up.role, 'viewer')::text as role,
    coalesce(up.permissions, '{}'::jsonb) as permissions,
    coalesce(up.is_active, true) as is_active,
    u.last_sign_in_at,
    u.created_at,
    e.id as employee_id,
    (e.first_name || ' ' || e.last_name) as employee_name
  from auth.users u
  inner join user_profiles up on up.user_id = u.id
  left join employees e on e.user_id = u.id and e.tenant_id = p_tenant_id
  where up.tenant_id = p_tenant_id
  order by u.created_at desc;
end;
$$;


--
-- TOC entry 1906 (class 1255 OID 24937)
-- Name: get_trial_balance(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_trial_balance(p_start_date timestamp with time zone, p_end_date timestamp with time zone) RETURNS TABLE(account_code text, account_name text, account_type text, account_category text, debit_total numeric, credit_total numeric, balance numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  select
    a.code as account_code,
    a.name as account_name,
    a.type as account_type,
    a.category as account_category,
    coalesce(sum(jl.debit_amount), 0)::numeric(14,2) as debit_total,
    coalesce(sum(jl.credit_amount), 0)::numeric(14,2) as credit_total,
    case
      when a.type in ('asset', 'expense') then
        coalesce(sum(jl.debit_amount), 0) - coalesce(sum(jl.credit_amount), 0)
      else
        coalesce(sum(jl.credit_amount), 0) - coalesce(sum(jl.debit_amount), 0)
    end::numeric(14,2) as balance
  from accounts a
  left join journal_lines jl on jl.account_id = a.id AND jl.tenant_id = user_tenant_id()
  left join journal_entries je on je.id = jl.entry_id
    and je.entry_date >= p_start_date
    and je.entry_date <= p_end_date
    and je.status = 'posted'
    and je.tenant_id = user_tenant_id()
  where a.is_active = true
    and a.tenant_id = user_tenant_id()
  group by a.id, a.code, a.name, a.type, a.category
  having coalesce(sum(jl.debit_amount), 0) <> 0 
      or coalesce(sum(jl.credit_amount), 0) <> 0
  order by a.code;
end;
$$;


--
-- TOC entry 693 (class 1255 OID 32699)
-- Name: handle_expense_line_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_expense_line_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_expense_id uuid;
  v_posting_status text;
begin
  -- Get the expense_id from the relevant row
  if TG_OP = 'DELETE' then
    v_expense_id := OLD.expense_id;
  else
    v_expense_id := NEW.expense_id;
  end if;

  -- Check if parent expense is posted
  select posting_status into v_posting_status
    from public.expenses
   where id = v_expense_id;

  -- If posted, regenerate journal entry
  if lower(coalesce(v_posting_status, 'draft')) = 'posted' then
    perform public.delete_expense_journal_entry(v_expense_id);
    perform public.create_expense_journal_entry(v_expense_id);
  end if;

  -- Recalculate expense totals
  perform public.recalculate_expense_totals(v_expense_id);

  if TG_OP = 'DELETE' then
    return OLD;
  else
    return NEW;
  end if;
end;
$$;


--
-- TOC entry 1089 (class 1255 OID 32712)
-- Name: handle_expense_payment_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_expense_payment_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if TG_OP = 'INSERT' then
    perform public.recalculate_expense_totals(NEW.expense_id);
    perform public.create_expense_payment_journal_entry(NEW.id);
    return NEW;

  elsif TG_OP = 'UPDATE' then
    perform public.recalculate_expense_totals(NEW.expense_id);
    perform public.delete_expense_payment_journal_entry(OLD.id);
    perform public.create_expense_payment_journal_entry(NEW.id);
    return NEW;

  elsif TG_OP = 'DELETE' then
    perform public.recalculate_expense_totals(OLD.expense_id);
    perform public.delete_expense_payment_journal_entry(OLD.id);
    return OLD;
  end if;

  return NULL;
end;
$$;


--
-- TOC entry 834 (class 1255 OID 26289)
-- Name: handle_mechanic_job_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_mechanic_job_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_old_status text; v_new_status text; v_should_consume_inventory boolean := false; v_should_restore_inventory boolean := false; v_should_create_journal boolean := false; v_should_delete_journal boolean := false;
begin
  if pg_trigger_depth() > 1 then if TG_OP = 'DELETE' then return OLD; else return NEW; end if; end if;
  if TG_OP = 'INSERT' then
    if TG_WHEN = 'BEFORE' then if NEW.job_number is null or NEW.job_number = '' then NEW.job_number := public.generate_mechanic_job_number(); end if; if NEW.status = 'EN_CURSO' and NEW.started_at is null then NEW.started_at := now(); end if; if NEW.status = 'FINALIZADO' and NEW.completed_at is null then NEW.completed_at := now(); end if; if NEW.status = 'ENTREGADO' and NEW.delivered_at is null then NEW.delivered_at := now(); end if; return NEW; end if;
    if TG_WHEN = 'AFTER' then perform public.log_mechanic_job_timeline(NEW.id,'created',null,NEW.status,'Job created: ' || coalesce(NEW.client_request, 'Service request')); if NEW.status in ('EN_CURSO', 'FINALIZADO', 'ENTREGADO') then v_should_consume_inventory := true; end if; if NEW.status in ('FINALIZADO', 'ENTREGADO') and not NEW.is_invoiced then v_should_create_journal := true; end if; end if; return NEW;
  elsif TG_OP = 'UPDATE' then
    v_old_status := OLD.status; v_new_status := NEW.status;
    if v_old_status <> v_new_status then
      perform public.log_mechanic_job_timeline(NEW.id,'status_changed',v_old_status,v_new_status,'Status changed from ' || v_old_status || ' to ' || v_new_status);
      if v_new_status = 'EN_CURSO' and NEW.started_at is null then NEW.started_at := now(); end if; if v_new_status = 'FINALIZADO' and NEW.completed_at is null then NEW.completed_at := now(); end if; if v_new_status = 'ENTREGADO' and NEW.delivered_at is null then NEW.delivered_at := now(); end if;
      if NEW.invoice_id is not null then if v_new_status = 'ENTREGADO' then update public.sales_invoices set status = 'enviado', updated_at = now() where id = NEW.invoice_id and status = 'draft'; elsif v_new_status = 'CANCELADO' then update public.sales_invoices set status = 'cancelado', updated_at = now() where id = NEW.invoice_id and status != 'paid'; end if; end if;
      if v_old_status not in ('EN_CURSO', 'FINALIZADO', 'ENTREGADO') and v_new_status in ('EN_CURSO', 'FINALIZADO', 'ENTREGADO') then v_should_consume_inventory := true; elsif v_old_status in ('EN_CURSO', 'FINALIZADO', 'ENTREGADO') and v_new_status = 'CANCELADO' then v_should_restore_inventory := true; end if;
      if v_new_status in ('FINALIZADO', 'ENTREGADO') and v_old_status not in ('FINALIZADO', 'ENTREGADO') and not NEW.is_invoiced then v_should_create_journal := true; elsif v_new_status = 'CANCELADO' and v_old_status in ('FINALIZADO', 'ENTREGADO') then v_should_delete_journal := true; end if;
    end if;

    -- 🌟 Link Bridge Fix: If invoice_id is newly linked, force a Forward Sync!
    if NEW.invoice_id is not null and OLD.invoice_id is null then
      perform public.sync_invoice_items_to_job(NEW.invoice_id);
      perform public.sync_invoice_status_to_job(NEW.invoice_id);
    end if;

    if OLD.diagnosis is distinct from NEW.diagnosis and NEW.diagnosis is not null then perform public.log_mechanic_job_timeline(NEW.id,'diagnosis_added',null,null,'Diagnosis updated'); end if;
    if OLD.assigned_to is distinct from NEW.assigned_to then perform public.log_mechanic_job_timeline(NEW.id,'assigned',OLD.assigned_technician_name,NEW.assigned_technician_name,'Technician assigned'); end if;
    if OLD.approved_by_customer <> NEW.approved_by_customer and NEW.approved_by_customer then perform public.log_mechanic_job_timeline(NEW.id,'approved',null,null,'Customer approved the work'); end if;
    if OLD.is_invoiced <> NEW.is_invoiced and NEW.is_invoiced then perform public.log_mechanic_job_timeline(NEW.id,'invoiced',null,NEW.invoice_id::text,'Job invoiced'); v_should_delete_journal := true; end if;
    return NEW;
  elsif TG_OP = 'DELETE' then
    if OLD.status in ('EN_CURSO', 'FINALIZADO', 'ENTREGADO') then perform public.restore_mechanic_job_inventory(OLD.id); end if;
    perform public.delete_mechanic_job_journal_entry(OLD.id); return OLD;
  end if;
end;
$$;


--
-- TOC entry 1773 (class 1255 OID 26291)
-- Name: handle_mechanic_job_items_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_mechanic_job_items_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if TG_OP = 'INSERT' then
    -- Recalculate job costs
    perform public.recalculate_mechanic_job_costs(NEW.job_id);
    
    -- Note: Sync to invoice is handled by statement-level trigger
    
    -- Log event
    perform public.log_mechanic_job_timeline(
      NEW.job_id,
      'parts_added',
      null,
      NEW.product_name,
      'Added part: ' || NEW.product_name || ' (Qty: ' || NEW.quantity || ')'
    );
    
    return NEW;

  elsif TG_OP = 'UPDATE' then
    -- Recalculate job costs
    perform public.recalculate_mechanic_job_costs(NEW.job_id);
    
    -- Note: Sync to invoice is handled by statement-level trigger
    
    return NEW;

  elsif TG_OP = 'DELETE' then
    -- Recalculate job costs
    perform public.recalculate_mechanic_job_costs(OLD.job_id);
    
    -- Note: Sync to invoice is handled by statement-level trigger
    
    return OLD;
  end if;

  return NULL;
end;
$$;


