--
-- TOC entry 1805 (class 1255 OID 148444)
-- Name: is_set_partial(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_set_partial(p_set_product_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_has_stock BOOLEAN;
  v_missing_stock BOOLEAN;
BEGIN
  -- Check if at least one component has stock
  SELECT EXISTS (
    SELECT 1 FROM product_set_components psc
    JOIN products p ON p.id = psc.component_product_id
    WHERE psc.set_product_id = p_set_product_id
      AND COALESCE(p.stock_quantity, p.inventory_qty, 0) >= psc.quantity_in_set
  ) INTO v_has_stock;
  
  -- Check if at least one component is missing stock
  SELECT EXISTS (
    SELECT 1 FROM product_set_components psc
    JOIN products p ON p.id = psc.component_product_id
    WHERE psc.set_product_id = p_set_product_id
      AND COALESCE(p.stock_quantity, p.inventory_qty, 0) < psc.quantity_in_set
  ) INTO v_missing_stock;
  
  -- Partial = some have stock AND some don't
  RETURN v_has_stock AND v_missing_stock;
END;
$$;


--
-- TOC entry 775 (class 1255 OID 26288)
-- Name: log_mechanic_job_timeline(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_mechanic_job_timeline(p_job_id uuid, p_event_type text, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_description text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant_id uuid;
begin
  -- Get tenant_id from the job
  select tenant_id into v_tenant_id
  from mechanic_jobs
  where id = p_job_id;

  if v_tenant_id is null then
    raise warning 'Cannot log timeline: job % not found or has no tenant_id', p_job_id;
