--
-- TOC entry 615 (class 1255 OID 236751)
-- Name: mark_whatsapp_job_quote_sent(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_whatsapp_job_quote_sent(p_job_id uuid, p_external_message_id text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job record;
  v_status_id uuid;
begin
  select * into v_job
  from public.mechanic_jobs
  where id = p_job_id;

  if not found then
    raise exception 'Job not found: %', p_job_id;
  end if;

  select id into v_status_id
  from public.job_statuses
  where tenant_id = v_job.tenant_id
    and code = 'ESPERANDO_APROBACION'
    and is_active = true
  order by sort_order
  limit 1;

  update public.mechanic_jobs
  set status = coalesce(
        case
          when v_status_id is not null then 'ESPERANDO_APROBACION'
          else status
        end,
        status
      ),
      status_id = coalesce(v_status_id, status_id),
      diagnostic_sent_at = coalesce(diagnostic_sent_at, now()),
      requires_approval = true,
      updated_at = now()
  where id = p_job_id;

  perform public.log_mechanic_job_timeline(
    p_job_id,
    'whatsapp_quote_sent',
    null,
    p_external_message_id,
    'Quote sent to customer via WhatsApp'
  );

  return jsonb_build_object(
    'job_id', p_job_id,
    'status_code', case when v_status_id is not null then 'ESPERANDO_APROBACION' else v_job.status end,
    'diagnostic_sent_at', now(),
    'external_message_id', p_external_message_id,
    'payload', p_payload
  );
end;
$$;


--
-- TOC entry 1974 (class 1255 OID 206774)
-- Name: match_products_semantic(public.vector, uuid, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_products_semantic(query_embedding public.vector, match_tenant_id uuid, match_threshold double precision DEFAULT 0.3, match_count integer DEFAULT 10) RETURNS TABLE(id uuid, name text, sku text, brand text, category_name text, description text, price double precision, inventory_qty integer, warehouse_location text, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.id,
    p.name,
    p.sku,
    p.brand,
    p.category_name,
    p.description,
    p.price::float,
    p.inventory_qty,
    p.warehouse_location,
    1 - (p.embedding <=> query_embedding) AS similarity
  FROM products p
  WHERE p.tenant_id = match_tenant_id
    AND p.embedding IS NOT NULL
    AND p.is_active = true
    AND 1 - (p.embedding <=> query_embedding) > match_threshold
  ORDER BY p.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


--
-- TOC entry 1808 (class 1255 OID 19270)
-- Name: migrate_accounts_to_uuid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migrate_accounts_to_uuid() RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_accounts_id_is_uuid boolean;
  v_accounts_parent_type text;
  v_journal_account_type text;
begin
  select case when data_type = 'uuid' then true else false end
    into v_accounts_id_is_uuid
    from information_schema.columns
   where table_schema = 'public'
     and table_name = 'accounts'
     and column_name = 'id'
   limit 1;

  if coalesce(v_accounts_id_is_uuid, false) then
    return;
  end if;

  if not exists (
    select 1
      from information_schema.columns
     where table_schema = 'public'
       and table_name = 'accounts'
       and column_name = 'id_uuid'
  ) then
    alter table public.accounts add column id_uuid uuid;
  end if;

  update public.accounts
     set id_uuid = coalesce(id_uuid, gen_random_uuid());

  alter table public.accounts
    alter column id_uuid set not null;

  select data_type
    into v_journal_account_type
    from information_schema.columns
   where table_schema = 'public'
     and table_name = 'journal_lines'
     and column_name = 'account_id'
   limit 1;

  if v_journal_account_type is not null then
    if v_journal_account_type <> 'uuid' then
      if not exists (
        select 1
          from information_schema.columns
         where table_schema = 'public'
           and table_name = 'journal_lines'
           and column_name = 'account_id_uuid'
      ) then
        alter table public.journal_lines add column account_id_uuid uuid;
      end if;

      update public.journal_lines jl
         set account_id_uuid = a.id_uuid
        from public.accounts a
       where jl.account_id is not null
         and a.id::text = jl.account_id::text;

      alter table public.journal_lines drop column account_id;
      alter table public.journal_lines rename column account_id_uuid to account_id;
    else
      update public.journal_lines jl
         set account_id = a.id_uuid
        from public.accounts a
       where jl.account_id is not null
         and a.id::text = jl.account_id::text
         and jl.account_id <> a.id_uuid;
    end if;
  end if;

  select data_type
    into v_accounts_parent_type
    from information_schema.columns
   where table_schema = 'public'
     and table_name = 'accounts'
     and column_name = 'parent_id'
   limit 1;

  if v_accounts_parent_type is not null then
    if v_accounts_parent_type <> 'uuid' then
      if not exists (
        select 1
          from information_schema.columns
         where table_schema = 'public'
           and table_name = 'accounts'
           and column_name = 'parent_id_uuid'
      ) then
        alter table public.accounts add column parent_id_uuid uuid;
      end if;

      update public.accounts child
         set parent_id_uuid = parent.id_uuid
        from public.accounts parent
       where child.parent_id is not null
         and parent.id::text = child.parent_id::text;

      alter table public.accounts drop column parent_id;
      alter table public.accounts rename column parent_id_uuid to parent_id;
    else
      update public.accounts child
         set parent_id = parent.id_uuid
        from public.accounts parent
       where child.parent_id is not null
         and parent.id::text = child.parent_id::text
         and child.parent_id <> parent.id_uuid;
    end if;
  end if;

  if v_journal_account_type is not null then
    alter table public.journal_lines
      drop constraint if exists journal_lines_account_id_fkey;
  end if;

  if exists (
    select 1
      from pg_constraint
     where conrelid = 'public.accounts'::regclass
       and contype = 'f'
       and conname = 'accounts_parent_id_fkey'
  ) then
    alter table public.accounts
      drop constraint accounts_parent_id_fkey;
  end if;

  alter table public.accounts
    drop constraint if exists accounts_pkey;

  alter table public.accounts drop column id;
  alter table public.accounts rename column id_uuid to id;
  alter table public.accounts add primary key (id);
  alter table public.accounts alter column id set default gen_random_uuid();

  if exists (
    select 1
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
     where c.relkind = 'S'
       and n.nspname = 'public'
       and c.relname = 'accounts_id_seq'
  ) then
    execute 'drop sequence public.accounts_id_seq';
  end if;

  if exists (
    select 1
      from information_schema.columns
     where table_schema = 'public'
       and table_name = 'accounts'
       and column_name = 'parent_id'
  ) then
    if not exists (
      select 1
        from pg_constraint
       where conrelid = 'public.accounts'::regclass
         and contype = 'f'
         and conname = 'accounts_parent_id_fkey'
    ) then
      alter table public.accounts
        add constraint accounts_parent_id_fkey
          foreign key (parent_id)
          references public.accounts(id)
          on delete set null;
    end if;
  end if;

  if exists (
    select 1
      from information_schema.columns
     where table_schema = 'public'
       and table_name = 'journal_lines'
       and column_name = 'account_id'
  ) then
    if not exists (
      select 1
        from pg_constraint
       where conrelid = 'public.journal_lines'::regclass
         and contype = 'f'
         and conname = 'journal_lines_account_id_fkey'
    ) then
      alter table public.journal_lines
        add constraint journal_lines_account_id_fkey
          foreign key (account_id)
          references public.accounts(id);
    end if;
  end if;
end;
$$;


--
-- TOC entry 1664 (class 1255 OID 120316)
-- Name: migrate_job_statuses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migrate_job_statuses() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_count int := 0;
  v_job record;
  v_status_id uuid;
begin
  -- First, seed job statuses for all existing tenants that don't have them
  for v_job in (select distinct tenant_id from mechanic_jobs) loop
    perform public.seed_job_statuses_for_tenant(v_job.tenant_id);
  end loop;

  -- Now update all mechanic_jobs to set status_id based on status text
  for v_job in (
    select id, tenant_id, status from mechanic_jobs where status_id is null
  ) loop
    select id into v_status_id
    from job_statuses
    where tenant_id = v_job.tenant_id
      and code = v_job.status
    limit 1;

    if v_status_id is not null then
      update mechanic_jobs set status_id = v_status_id where id = v_job.id;
      v_count := v_count + 1;
    end if;
  end loop;

  return format('✓ Migrated %s jobs to use status_id', v_count);
end;
$$;


--
-- TOC entry 1019 (class 1255 OID 236749)
-- Name: normalize_whatsapp_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_whatsapp_phone(p_phone text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  v_digits text;
begin
  if p_phone is null then
    return null;
  end if;

  v_digits := regexp_replace(p_phone, '[^0-9]', '', 'g');

  if v_digits = '' then
    return null;
  end if;

  if v_digits like '56%' then
    return v_digits;
  end if;

  if length(v_digits) = 9 and left(v_digits, 1) = '9' then
    return '56' || v_digits;
  end if;

  if length(v_digits) = 8 then
    return '569' || v_digits;
  end if;

  return v_digits;
end;
$$;


--
-- TOC entry 2051 (class 1255 OID 167527)
-- Name: notify_new_email(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_new_email(p_user_id uuid, p_provider text, p_history_id text DEFAULT NULL::text, p_notification_data jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Update the subscription to trigger realtime notification
  UPDATE email_push_subscriptions
  SET 
    new_mail_notification = true,
    notification_data = p_notification_data,
    gmail_history_id = COALESCE(p_history_id, gmail_history_id),
    last_notification_at = now(),
    updated_at = now()
  WHERE user_id = p_user_id AND provider = p_provider;
  
  -- If no subscription exists, create one
  IF NOT FOUND THEN
    INSERT INTO email_push_subscriptions (user_id, tenant_id, provider, gmail_history_id, new_mail_notification, notification_data, last_notification_at)
    SELECT 
      p_user_id,
      up.tenant_id,
      p_provider,
      p_history_id,
      true,
      p_notification_data,
      now()
    FROM user_profiles up
    WHERE up.user_id = p_user_id
    LIMIT 1;
  END IF;
END;
$$;


--
-- TOC entry 1319 (class 1255 OID 114131)
-- Name: parse_description_to_tasks(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_description_to_tasks(p_tenant_id uuid, p_job_id uuid, p_parent_item_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_task_line text;
  v_task_name text;
  v_task_count integer := 0;
  v_lines text[];
begin
  if p_description is null or trim(p_description) = '' then
    return 0;
  end if;
  
  -- Split description by newlines
  v_lines := string_to_array(p_description, E'\n');
  
  -- Parse each line
  foreach v_task_line in array v_lines
  loop
    v_task_line := trim(v_task_line);
    
    -- Check if line starts with bullet markers: -, •, *, →, ✓, ☐, ☑, 1., 2., etc.
    if v_task_line ~ '^[-•*→✓☐☑]' or v_task_line ~ '^\d+\.' then
      -- Remove bullet marker and clean up
      v_task_name := regexp_replace(v_task_line, '^[-•*→✓☐☑]\s*', '');
      v_task_name := regexp_replace(v_task_name, '^\d+\.\s*', '');
      v_task_name := trim(v_task_name);
      
      -- Skip empty lines
      if length(v_task_name) > 0 then
        insert into mechanic_job_tasks (
          tenant_id,
          job_id,
          parent_item_id,
          task_name,
          parsed_from_description,
          is_standalone,
          display_order
        ) values (
          p_tenant_id,
          p_job_id,
          p_parent_item_id,
          v_task_name,
          true,
          false,
          v_task_count
        );
        
        v_task_count := v_task_count + 1;
      end if;
    end if;
  end loop;
  
  return v_task_count;
end;
$$;


