--
-- TOC entry 1741 (class 1255 OID 32696)
-- Name: prepare_expense_record(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_expense_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_posting text := lower(coalesce(NEW.posting_status, 'draft'));
  v_payment text := lower(coalesce(NEW.payment_status, 'pending'));
begin
  if TG_OP = 'INSERT' then
    if coalesce(NEW.expense_number, '') = '' then
      NEW.expense_number := public.generate_expense_number();
    end if;
    NEW.created_at := coalesce(NEW.created_at, now());
    if v_posting = 'posted' then
      NEW.posted_at := coalesce(NEW.posted_at, NEW.issue_date, now());
    end if;
    if v_payment = 'paid' then
      NEW.paid_at := coalesce(NEW.paid_at, NEW.issue_date, now());
    end if;
  elsif TG_OP = 'UPDATE' then
    if v_posting = 'posted' and lower(coalesce(OLD.posting_status, 'draft')) <> 'posted' then
      NEW.posted_at := coalesce(NEW.posted_at, NEW.issue_date, now());
    elsif v_posting <> 'posted' then
      NEW.posted_at := null;
    end if;

    if v_payment = 'paid' and lower(coalesce(OLD.payment_status, 'pending')) <> 'paid' then
      NEW.paid_at := coalesce(NEW.paid_at, NEW.issue_date, now());
    elsif v_payment <> 'paid' then
      NEW.paid_at := null;
    end if;
  end if;

  NEW.updated_at := now();
  return NEW;
end;
$$;


--
-- TOC entry 579 (class 1255 OID 29068)
-- Name: prevent_duplicate_checkin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_duplicate_checkin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ongoing_count integer;
begin
  -- Only check on INSERT or when status becomes 'ongoing'
  if (TG_OP = 'INSERT' or (TG_OP = 'UPDATE' and NEW.status = 'ongoing')) 
     and NEW.status = 'ongoing' and NEW.check_out is null then
    
    select count(*) into v_ongoing_count
    from attendances
    where employee_id = NEW.employee_id
      and status = 'ongoing'
      and check_out is null
      and id != coalesce(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
    
    if v_ongoing_count > 0 then
      raise exception 'Employee % already has an ongoing attendance session', NEW.employee_id;
    end if;
  end if;
  
  return NEW;
end;
$$;


--
-- TOC entry 1876 (class 1255 OID 127286)
-- Name: preview_next_document_number(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_next_document_number(p_tenant_id uuid, p_document_type text, p_prefix text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_actor_tenant_id uuid;
  v_current_number integer;
  v_max_existing integer := 0;
  v_next_number integer;
  v_prefix text;
  v_table_name text;
  v_column_name text;
  v_formatted_number text;
begin
  v_actor_tenant_id := public.user_tenant_id();

  if auth.uid() is not null then
    if v_actor_tenant_id is null then
      raise exception 'Could not resolve tenant for authenticated user';
    end if;

    if p_tenant_id is null or p_tenant_id <> v_actor_tenant_id then
      raise exception 'Cross-tenant document sequence access is not allowed';
    end if;
  end if;

  v_prefix := coalesce(p_prefix, case p_document_type
    when 'sales_invoice' then 'FV'
    when 'purchase_invoice' then 'FC'
    when 'sales_payment' then 'PV'
    when 'purchase_payment' then 'PC'
    when 'journal_entry' then 'AC'
    when 'mechanic_job' then 'PG'
    when 'stock_adjustment' then 'AJ'
    when 'expense' then 'GTO'
    else 'DOC'
  end);

  case p_document_type
    when 'sales_invoice' then
      v_table_name := 'sales_invoices';
      v_column_name := 'invoice_number';
    when 'purchase_invoice' then
      v_table_name := 'purchase_invoices';
      v_column_name := 'invoice_number';
    when 'sales_payment' then
      v_table_name := 'sales_payments';
      v_column_name := 'payment_number';
    when 'purchase_payment' then
      v_table_name := 'purchase_payments';
      v_column_name := 'payment_number';
    when 'journal_entry' then
      v_table_name := 'journal_entries';
      v_column_name := 'entry_number';
    when 'mechanic_job' then
      v_table_name := 'mechanic_jobs';
      v_column_name := 'job_number';
    when 'stock_adjustment' then
      v_table_name := 'stock_adjustments';
      v_column_name := 'reference';
    when 'expense' then
      v_table_name := 'expenses';
      v_column_name := 'expense_number';
    else
      v_table_name := null;
      v_column_name := null;
  end case;

  if v_table_name is not null and v_column_name is not null then
    execute format(
      'select coalesce(max((substring(%1$I from ''([0-9]+)$''))::integer), 0)
         from public.%2$I
        where tenant_id = $1
          and %1$I ~ $2',
      v_column_name,
      v_table_name
    )
    into v_max_existing
    using p_tenant_id, '^' || v_prefix || '-[0-9]+$';
  end if;

  select coalesce(last_number, 0)
    into v_current_number
    from public.document_sequences
   where tenant_id = p_tenant_id
     and document_type = p_document_type;

  v_next_number := greatest(coalesce(v_current_number, 0), coalesce(v_max_existing, 0)) + 1;
  v_formatted_number := v_prefix || '-' || lpad(v_next_number::text, 5, '0');
  return v_formatted_number;
end;
$_$;


--
-- TOC entry 1281 (class 1255 OID 32710)
-- Name: process_expense_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_expense_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old_posted boolean := lower(coalesce(OLD.posting_status, 'draft')) = 'posted';
  v_new_posted boolean := lower(coalesce(NEW.posting_status, 'draft')) = 'posted';
begin
  if pg_trigger_depth() > 1 then
    if TG_OP = 'DELETE' then
      return OLD;
    else
      return NEW;
    end if;
  end if;

  if TG_OP = 'INSERT' then
    perform public.recalculate_expense_totals(NEW.id);
    -- Journal entry will be created by expense_lines trigger after lines are inserted
    return NEW;

  elsif TG_OP = 'UPDATE' then
    perform public.recalculate_expense_totals(NEW.id);

    if v_old_posted and not v_new_posted then
      perform public.delete_expense_journal_entry(OLD.id);
    elsif not v_old_posted and v_new_posted then
      perform public.create_expense_journal_entry(NEW.id);
    elsif v_old_posted and v_new_posted then
      perform public.delete_expense_journal_entry(OLD.id);
      perform public.create_expense_journal_entry(NEW.id);
    end if;

    return NEW;

  elsif TG_OP = 'DELETE' then
    if v_old_posted then
      perform public.delete_expense_journal_entry(OLD.id);
    end if;
    return OLD;
  end if;

  return NULL;
end;
$$;


--
-- TOC entry 1982 (class 1255 OID 30679)
-- Name: process_online_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_online_order(p_order_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_order record;
  v_invoice_id uuid;
  v_invoice_number text;
  v_items jsonb;
  v_next_number integer;
  v_year text;
  v_payment_method record;
  v_tenant_id uuid;
  v_net_amount numeric(12,2);
  v_iva_amount numeric(12,2);
  v_tax_treatment text;
  v_invoice_status text;
  v_should_create_payment boolean;
begin
  -- Get order details WITH ROW LOCK to prevent race conditions
  select * into v_order
  from online_orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'Order not found: %', p_order_id;
  end if;

  -- Get tenant_id from the order
  v_tenant_id := v_order.tenant_id;
  if v_tenant_id is null then
    raise exception 'Order has no tenant_id: %', p_order_id;
  end if;

  -- Check if invoice already exists
  if v_order.sales_invoice_id is not null then
    -- Invoice exists - check if we need to update it to 'paid' status
    if v_order.payment_status = 'paid' then
      -- Get payment method for creating payment record
      select * into v_payment_method
      from payment_methods
      where tenant_id = v_tenant_id
        and lower(code) = lower(coalesce(v_order.payment_method, 'mercadopago'))
        and is_active = true
      limit 1;

      -- If payment method not found, try fallback
      if v_payment_method is null then
        select * into v_payment_method
        from payment_methods
        where tenant_id = v_tenant_id
          and is_active = true
        order by sort_order
        limit 1;
      end if;

      -- Check if invoice is not already paid
      perform 1 from sales_invoices
      where id = v_order.sales_invoice_id
        and status != 'paid';

      if found then
        -- Update invoice to paid status
        update sales_invoices
        set status = 'paid',
            paid_amount = total,
            balance = 0,
            updated_at = now()
        where id = v_order.sales_invoice_id;

        -- Create payment record if not exists
        if not exists (
          select 1 from sales_payments
          where invoice_id = v_order.sales_invoice_id
        ) and v_payment_method.id is not null then
          insert into sales_payments (
            tenant_id,
            invoice_id,
            invoice_reference,
            payment_method_id,
            amount,
            date,
            reference,
            notes
          ) values (
            v_tenant_id,
            v_order.sales_invoice_id,
            (select invoice_number from sales_invoices where id = v_order.sales_invoice_id),
            v_payment_method.id,
            v_order.total,
            coalesce(v_order.paid_at, now()),
            v_order.payment_reference,
            'Pago automatico - Pedido online #' || v_order.order_number ||
            ' (' || coalesce(v_payment_method.name, v_order.payment_method) || ')'
          );

          raise notice 'Created payment record for existing invoice (order: %)', v_order.order_number;
        end if;

        raise notice 'Updated existing invoice to paid status (order: %)', v_order.order_number;
      end if;
    end if;

    return v_order.sales_invoice_id;
  end if;

  -- Get payment method configuration
  select * into v_payment_method
  from payment_methods
  where tenant_id = v_tenant_id
    and lower(code) = lower(coalesce(v_order.payment_method, 'mercadopago'))
    and is_active = true
  limit 1;

  -- If payment method not found, try fallback
  if v_payment_method is null then
    select * into v_payment_method
    from payment_methods
    where tenant_id = v_tenant_id
      and is_active = true
    order by sort_order
    limit 1;
  end if;

  -- Determine tax treatment based on payment method
  if v_order.tax_amount > 0 then
    v_tax_treatment := 'tax_included';
    v_net_amount := round(v_order.total / 1.19, 2);
    v_iva_amount := round(v_order.total - v_net_amount, 2);
  else
    v_tax_treatment := 'no_tax';
    v_net_amount := v_order.subtotal;
    v_iva_amount := 0;
  end if;

  -- Determine invoice status based on payment method + status
  if v_order.payment_status = 'paid' then
    v_invoice_status := 'paid';
    v_should_create_payment := true;
  elsif lower(v_order.payment_method) = 'mercadopago' and v_order.payment_status = 'pending' then
    v_invoice_status := 'confirmed';
    v_should_create_payment := false;
  else
    v_invoice_status := 'sent';
    v_should_create_payment := false;
  end if;

  -- Generate invoice number PER TENANT in format: INV-25-00001
  v_year := to_char(now(), 'YY');

  select coalesce(max(cast(substring(invoice_number from '\d+$') as integer)), 0) + 1
  into v_next_number
  from sales_invoices
  where tenant_id = v_tenant_id
    and invoice_number ~ ('^INV-' || v_year || '-\d+$');

  v_invoice_number := 'INV-' || v_year || '-' || lpad(v_next_number::text, 5, '0');

  -- Build items JSONB array from order items
  select jsonb_agg(
    jsonb_build_object(
      'product_id', oi.product_id,
      'product_name', oi.product_name,
      'product_sku', oi.product_sku,
      'quantity', oi.quantity,
      'price', oi.unit_price,
      'subtotal', oi.subtotal
    )
  ) into v_items
  from online_order_items oi
  where oi.order_id = p_order_id;

  if v_items is null then
    v_items := '[]'::jsonb;
  end if;

  -- Create sales invoice. Only 'paid' status triggers inventory deduction + journal entry.
  insert into sales_invoices (
    tenant_id,
    invoice_number,
    customer_id,
    customer_name,
    date,
    due_date,
    status,
    tax_treatment,
    net_amount,
    subtotal,
    iva_amount,
    total,
    paid_amount,
    balance,
    items,
    reference,
    source
  ) values (
    v_tenant_id,
    v_invoice_number,
    v_order.customer_id,
    v_order.customer_name,
    now(),
    now() + interval '30 days',
    v_invoice_status,
    v_tax_treatment,
    v_net_amount,
    v_order.subtotal,
    v_iva_amount,
    v_order.total,
    case when v_should_create_payment then v_order.total else 0 end,
    case when v_should_create_payment then 0 else v_order.total end,
    v_items,
    'Pedido online #' || v_order.order_number ||
    case
      when v_order.delivery_type = 'pickup' then ' (Retiro en tienda)'
      else ' (Envio)'
    end,
    'ecommerce'
  )
  returning id into v_invoice_id;

  raise notice 'Created invoice % (status: %, tax: %) for online order %',
    v_invoice_number, v_invoice_status, v_tax_treatment, v_order.order_number;

  -- Directly call inventory and journal functions here because nested triggers block the usual path.
  if v_invoice_status in ('paid', 'confirmed') then
    declare
      v_invoice_record sales_invoices%rowtype;
    begin
      select * into v_invoice_record from sales_invoices where id = v_invoice_id;

      raise notice 'Calling consume_sales_invoice_inventory for invoice %', v_invoice_number;
      perform public.consume_sales_invoice_inventory(v_invoice_record);

      raise notice 'Calling create_sales_invoice_journal_entry for invoice %', v_invoice_number;
      perform public.create_sales_invoice_journal_entry(v_invoice_record);
    end;
  end if;

  -- Link invoice to order + update order status
  update online_orders
  set
    sales_invoice_id = v_invoice_id,
    status = case
      when status = 'pending' then 'confirmed'
      else status
    end,
    updated_at = now()
  where id = p_order_id;

  -- Create payment record ONLY if payment is confirmed
  if v_should_create_payment and v_payment_method.id is not null then
    insert into sales_payments (
      tenant_id,
      invoice_id,
      invoice_reference,
      payment_method_id,
      amount,
      date,
      reference,
      notes
    ) values (
      v_tenant_id,
      v_invoice_id,
      v_invoice_number,
      v_payment_method.id,
      v_order.total,
      coalesce(v_order.paid_at, now()),
      v_order.payment_reference,
      'Pago automatico - Pedido online #' || v_order.order_number ||
      ' (' || coalesce(v_payment_method.name, v_order.payment_method) || ')'
    );

    raise notice 'Created payment record for invoice % (method: %)',
      v_invoice_number, v_payment_method.name;
  elsif not v_should_create_payment then
    raise notice 'Invoice % pending manual payment confirmation (method: %)',
      v_invoice_number, v_order.payment_method;
  end if;

  return v_invoice_id;
end;
$_$;


--
-- TOC entry 771 (class 1255 OID 32704)
-- Name: recalculate_expense_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_expense_totals(p_expense_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_expense record;
  v_subtotal numeric(14,2) := 0;
  v_tax numeric(14,2) := 0;
  v_total numeric(14,2) := 0;
  v_paid numeric(14,2) := 0;
  v_latest_payment_date timestamp with time zone;
  v_payment_method_count integer := 0;
  v_payment_account_count integer := 0;
  v_single_payment_method_id uuid;
  v_single_payment_account_id uuid;
  v_category_id uuid;
  v_line_account_id uuid;
  v_line_account_code text;
  v_line_account_name text;
  v_category_name text;
  v_category_desc text;
  v_prev_payment text;
  v_new_payment text;
begin
  if p_expense_id is null then
    return;
  end if;

    select e.id,
      e.tenant_id,
      e.category_id,
         e.issue_date,
         lower(coalesce(e.payment_status, 'pending')) as payment_status,
         lower(coalesce(e.posting_status, 'draft')) as posting_status,
         e.paid_at,
         e.payment_method_id,
      e.payment_account_id,
         e.amount_paid as current_amount_paid,
         e.balance as current_balance
    into v_expense
    from public.expenses e
   where e.id = p_expense_id
   for update;

  if not found then
    return;
  end if;

  select
      coalesce(sum(subtotal), 0),
      coalesce(sum(tax_amount), 0),
      coalesce(sum(total), 0)
    into v_subtotal, v_tax, v_total
    from public.expense_lines
   where expense_id = p_expense_id;

  select coalesce(sum(amount), 0)
    into v_paid
    from public.expense_payments
   where expense_id = p_expense_id;

  select max(payment_date)
    into v_latest_payment_date
    from public.expense_payments
   where expense_id = p_expense_id
     and coalesce(amount, 0) > 0;

  if v_paid > 0 then
    select
      count(distinct ep.payment_method_id),
      (array_agg(distinct ep.payment_method_id))[1]
      into v_payment_method_count, v_single_payment_method_id
      from public.expense_payments ep
     where ep.expense_id = p_expense_id
       and coalesce(ep.amount, 0) > 0
       and ep.payment_method_id is not null;

    select
      count(distinct ep.payment_account_id),
      (array_agg(distinct ep.payment_account_id))[1]
      into v_payment_account_count, v_single_payment_account_id
      from public.expense_payments ep
     where ep.expense_id = p_expense_id
       and coalesce(ep.amount, 0) > 0
       and ep.payment_account_id is not null;
  end if;

  v_prev_payment := v_expense.payment_status;

  v_category_id := v_expense.category_id;
  if v_category_id is null then
    select el.account_id,
           el.account_code,
           el.account_name
      into v_line_account_id,
           v_line_account_code,
           v_line_account_name
      from public.expense_lines el
     where el.expense_id = p_expense_id
     order by el.line_index asc, el.created_at asc
     limit 1;

    if v_line_account_id is not null then
      v_category_name := public.get_expense_category_name_for_account(
        v_line_account_code,
        v_line_account_name
      );
      v_category_desc := coalesce(v_line_account_name, v_category_name);

      v_category_id := public.ensure_expense_category(
        v_expense.tenant_id,
        v_category_name,
        v_category_desc,
        v_line_account_id
      );
    end if;
  end if;

  if v_prev_payment = 'paid'
     and v_expense.payment_method_id is not null
     and v_paid = 0
     and v_total > 0 then
    v_new_payment := 'paid';
    v_paid := v_total;
  elsif v_total = 0 then
    v_new_payment := v_prev_payment;
  elsif v_paid <= 0 then
    if v_prev_payment = 'scheduled' then
      v_new_payment := 'scheduled';
    else
      v_new_payment := 'pending';
    end if;
  elsif v_paid + 0.01 < v_total then
    v_new_payment := 'partial';
  else
    v_new_payment := 'paid';
  end if;

  update public.expenses
     set subtotal = v_subtotal,
         tax_amount = v_tax,
         total_amount = v_total,
         amount_paid = v_paid,
         balance = greatest(v_total - v_paid, 0),
         category_id = coalesce(category_id, v_category_id),
         payment_method_id = case
           when v_payment_method_count = 1 and v_expense.payment_method_id is null
             then v_single_payment_method_id
           else payment_method_id
         end,
         payment_account_id = case
           when v_payment_account_count = 1 and v_expense.payment_account_id is null
             then v_single_payment_account_id
           else payment_account_id
         end,
         payment_status = case
           when v_expense.posting_status = 'void' then payment_status
           when v_prev_payment = 'void' then 'void'
           else v_new_payment
         end,
         paid_at = case
           when v_expense.posting_status <> 'void'
             and v_total > 0
             and v_paid + 0.01 >= v_total then coalesce(v_latest_payment_date, paid_at, v_expense.issue_date, now())
           when v_new_payment <> 'paid' then null
           else paid_at
         end,
         updated_at = now()
   where id = p_expense_id;
end;
$$;


--
-- TOC entry 1515 (class 1255 OID 143617)
-- Name: recalculate_job_bike_costs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_job_bike_costs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job_bike_id uuid;
  v_parts_cost numeric(12,2);
  v_labor_cost numeric(12,2);
begin
  -- 🔄 CIRCULAR SYNC GUARD
  if current_setting('app.syncing_invoice_to_job', true) = 'true' or
     current_setting('app.syncing_job_to_invoice', true) = 'true' then
    return coalesce(NEW, OLD);
  end if;

  if TG_OP = 'DELETE' then v_job_bike_id := OLD.job_bike_id; else v_job_bike_id := NEW.job_bike_id; end if;
  if v_job_bike_id is null then return coalesce(NEW, OLD); end if;
  
  select coalesce(sum(case when item_type = 'product' or item_type is null then total_price else 0 end), 0), coalesce(sum(case when item_type = 'service' then total_price else 0 end), 0) into v_parts_cost, v_labor_cost from mechanic_job_items where job_bike_id = v_job_bike_id;
  update mechanic_job_bikes set parts_cost = v_parts_cost, labor_cost = v_labor_cost, subtotal = v_parts_cost + v_labor_cost, updated_at = now() where id = v_job_bike_id;
  return coalesce(NEW, OLD);
end;
$$;


--
-- TOC entry 1810 (class 1255 OID 251476)
-- Name: recalculate_journal_entry_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_journal_entry_totals(p_entry_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_entry_id is null then
    return;
  end if;

  update public.journal_entries je
     set total_debit = coalesce(lines.total_debit, 0),
         total_credit = coalesce(lines.total_credit, 0),
         updated_at = now()
    from (
      select
        coalesce(sum(coalesce(jl.debit_amount, 0)), 0)::numeric(14, 2)
          as total_debit,
        coalesce(sum(coalesce(jl.credit_amount, 0)), 0)::numeric(14, 2)
          as total_credit
      from public.journal_lines jl
      where jl.entry_id = p_entry_id
    ) lines
   where je.id = p_entry_id;
end;
$$;


--
-- TOC entry 1317 (class 1255 OID 26283)
-- Name: recalculate_mechanic_job_costs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_mechanic_job_costs(p_job_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_parts_cost numeric(12,2) := 0; v_labor_cost numeric(12,2) := 0; v_subtotal numeric(12,2) := 0; v_discount numeric(12,2) := 0; v_tax_amount numeric(12,2) := 0; v_total numeric(12,2) := 0; v_tax_rate numeric(5,4) := 0.19;
begin
  if current_setting('app.syncing_invoice_to_job', true) = 'true' or current_setting('app.syncing_job_to_invoice', true) = 'true' then return; end if;
  if p_job_id is null then return; end if;
  select coalesce(sum(total_price), 0) into v_parts_cost from mechanic_job_items where job_id = p_job_id and coalesce(item_type, 'product') <> 'service';
  select coalesce(sum(total_price), 0) into v_labor_cost from mechanic_job_items where job_id = p_job_id and coalesce(item_type, 'product') = 'service';
  select coalesce(discount_amount, 0) into v_discount from mechanic_jobs where id = p_job_id;
  v_subtotal := v_parts_cost + v_labor_cost;
  v_tax_amount := (v_subtotal - v_discount) * v_tax_rate;
  v_total := v_subtotal - v_discount + v_tax_amount;
  update mechanic_jobs set parts_cost = v_parts_cost, labor_cost = v_labor_cost, final_cost = v_subtotal, tax_amount = v_tax_amount, total_cost = v_total, updated_at = now() where id = p_job_id;
end;
$$;


--
-- TOC entry 2102 (class 1255 OID 23951)
-- Name: recalculate_purchase_invoice_payments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_purchase_invoice_payments(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_invoice record;
  v_total numeric(12,2);
  v_new_status text;
  v_balance numeric(12,2);
BEGIN
  IF p_invoice_id IS NULL THEN
    RETURN;
  END IF;

  SELECT id, total, status, prepayment_model
    INTO v_invoice
    FROM public.purchase_invoices
   WHERE id = p_invoice_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT coalesce(sum(amount), 0)
    INTO v_total
    FROM public.purchase_payments
   WHERE invoice_id = p_invoice_id;

  v_balance := greatest(coalesce(v_invoice.total, 0) - v_total, 0);

  -- Status transition logic based on prepayment model
  -- Standard model: Draft→Sent→Confirmed→Received→Paid
  -- Prepayment model: Draft→Sent→Confirmed→Paid→Received
  
  IF v_invoice.status = 'cancelled' THEN
    v_new_status := 'cancelled';
    
  ELSIF v_invoice.status IN ('draft', 'sent') THEN
    v_new_status := v_invoice.status;
    
  -- Rounding tolerance: treat balance < $1 as fully paid
  ELSIF v_total >= coalesce(v_invoice.total, 0) OR v_balance < 1.0 THEN
    -- Only mark as paid if there's actually some payment
    IF v_total > 0 THEN
      v_new_status := 'paid';
    ELSE
      v_new_status := v_invoice.status;
    END IF;
    
  ELSIF v_total > 0 THEN
    IF v_invoice.prepayment_model THEN
      IF v_invoice.status IN ('paid', 'received') THEN
        v_new_status := 'paid';
      ELSE
        v_new_status := 'confirmed';
      END IF;
    ELSE
      IF v_invoice.status IN ('received', 'paid') THEN
        v_new_status := 'received';
      ELSE
        v_new_status := 'confirmed';
      END IF;
    END IF;
    
  ELSE
    IF v_invoice.prepayment_model THEN
      IF v_invoice.status IN ('paid', 'received') THEN
        v_new_status := 'confirmed';
      ELSE
        v_new_status := v_invoice.status;
      END IF;
    ELSE
      IF v_invoice.status = 'paid' THEN
        v_new_status := 'received';
      ELSE
        v_new_status := v_invoice.status;
      END IF;
    END IF;
  END IF;

  -- When balance is less than $1, set it to 0 and paid_amount to total
  IF v_balance < 1.0 AND v_total > 0 THEN
    UPDATE public.purchase_invoices
       SET paid_amount = total,
           balance = 0,
           status = v_new_status,
           updated_at = now()
     WHERE id = p_invoice_id;
  ELSE
    UPDATE public.purchase_invoices
       SET paid_amount = v_total,
           balance = v_balance,
           status = v_new_status,
           updated_at = now()
     WHERE id = p_invoice_id;
  END IF;
END;
$_$;


--
-- TOC entry 1007 (class 1255 OID 19054)
-- Name: recalculate_sales_invoice_payments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_sales_invoice_payments(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_invoice record;
  v_total numeric(12,2);
  v_new_status text;
  v_balance numeric(12,2);
begin
  if p_invoice_id is null then
    return;
  end if;

  select id,
         total,
         status
    into v_invoice
    from public.sales_invoices
   where id = p_invoice_id
   for update;

  if not found then
    return;
  end if;

  select coalesce(sum(amount), 0)
    into v_total
    from public.sales_payments
   where invoice_id = p_invoice_id;

  v_balance := greatest(coalesce(v_invoice.total, 0) - v_total, 0);

  -- Determine new status based on payment totals and current status
  if v_invoice.status = 'cancelled' then
    -- Keep cancelled status
    v_new_status := v_invoice.status;
  elsif v_invoice.status = 'draft' then
    -- Draft stays draft unless fully paid
    if v_total >= coalesce(v_invoice.total, 0) and v_total > 0 then
      v_new_status := 'paid';
    else
      v_new_status := 'draft';
    end if;
  elsif v_total >= coalesce(v_invoice.total, 0) and v_total > 0 then
    -- Fully paid
    v_new_status := 'paid';
  elsif v_total > 0 and v_total < coalesce(v_invoice.total, 0) then
    -- Partially paid - keep current status if it's overdue, otherwise set to confirmed
    if v_invoice.status = 'overdue' then
      v_new_status := 'overdue';
    else
      v_new_status := 'confirmed';
    end if;
  elsif v_total = 0 then
    -- No payments
    if v_invoice.status = 'paid' then
      -- If was paid but now has no payments, revert to confirmed
      v_new_status := 'confirmed';
    else
      -- Otherwise keep current status (draft/sent/confirmed/overdue)
      v_new_status := v_invoice.status;
    end if;
  else
    -- Fallback: keep current status
    v_new_status := v_invoice.status;
  end if;

  update public.sales_invoices
     set paid_amount = v_total,
         balance = v_balance,
         status = v_new_status,
         updated_at = now()
   where id = p_invoice_id;

  -- SYNC: Update mechanic_jobs if this invoice is linked to a job
  perform public.sync_invoice_status_to_job(p_invoice_id);
end;
$$;


--
-- TOC entry 800 (class 1255 OID 236754)
-- Name: record_whatsapp_message_status(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_whatsapp_message_status(p_phone_number_id text, p_external_message_id text, p_status text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_channel record;
  v_message record;
  v_event_key text;
  v_row_count integer;
  v_job_id uuid;
begin
  select * into v_channel
  from public.whatsapp_channels
  where phone_number_id = p_phone_number_id
    and is_active = true
  limit 1;

  if not found then
    raise exception 'WhatsApp channel not found for phone_number_id %', p_phone_number_id;
  end if;

  v_event_key := 'status:' || p_external_message_id || ':' || lower(coalesce(p_status, 'unknown')) || ':' || coalesce(p_payload->>'timestamp', '');

  insert into public.whatsapp_webhook_events (
    tenant_id,
    channel_id,
    event_key,
    event_type,
    direction,
    payload
  ) values (
    v_channel.tenant_id,
    v_channel.id,
    v_event_key,
    'status',
    'system',
    p_payload
  ) on conflict (channel_id, event_key) do nothing;

  get diagnostics v_row_count = row_count;

  if v_row_count = 0 then
    return jsonb_build_object(
      'duplicate', true,
      'event_key', v_event_key,
      'external_message_id', p_external_message_id
    );
  end if;

  update public.messages
  set external_status = lower(p_status),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'whatsapp_status', lower(p_status),
        'whatsapp_status_payload', p_payload,
        'whatsapp_status_updated_at', now()
      )
  where external_provider = 'whatsapp'
    and external_message_id = p_external_message_id
  returning id, conversation_id into v_message;

  if v_message.conversation_id is not null and lower(p_status) = 'read' then
    select cc.context_id into v_job_id
    from public.conversation_contexts cc
    where cc.conversation_id = v_message.conversation_id
      and cc.context_type = 'job'
    order by cc.is_primary desc, cc.added_at asc
    limit 1;

    if v_job_id is not null then
      perform public.log_mechanic_job_timeline(
        v_job_id,
        'whatsapp_read',
        null,
        p_external_message_id,
        'Customer read a WhatsApp message linked to this job'
      );
    end if;
  end if;

  return jsonb_build_object(
    'duplicate', false,
    'message_id', v_message.id,
    'conversation_id', v_message.conversation_id,
    'status', lower(p_status)
  );
end;
$$;


--
-- TOC entry 1290 (class 1255 OID 157880)
-- Name: respond_to_action_request(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_to_action_request(p_message_id uuid, p_action_type text, p_status text, p_metadata_updates jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_message_exists boolean;
  v_current_metadata jsonb;
  v_new_metadata jsonb;
begin
  -- 1. Verify existence
  select exists(select 1 from public.messages where id = p_message_id)
  into v_message_exists;

  if not v_message_exists then
    raise exception 'StartChat: Message not found';
  end if;

  -- 2. Get current metadata
  select metadata into v_current_metadata
  from public.messages
  where id = p_message_id;

  -- 3. Merge updates
  -- We update status, responded_at, and any other fields provided
  v_new_metadata := v_current_metadata || 
                    jsonb_build_object(
                      'status', p_status,
                      'responded_at', now()
                    ) || p_metadata_updates;

  -- 4. Update the message
  update public.messages
  set metadata = v_new_metadata
  where id = p_message_id;

end;
$$;


--
-- TOC entry 2062 (class 1255 OID 83550)
-- Name: restore_backup(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_backup(p_backup_id uuid, p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_backup_data jsonb;
  v_summary jsonb;
  v_tables_restored int := 0;
  v_records_restored int := 0;
begin
  -- Get backup data
  select backup_data, summary into v_backup_data, v_summary
  from database_backups
  where id = p_backup_id and tenant_id = p_tenant_id and status = 'completed';
  
  if not found then
    return jsonb_build_object('success', false, 'error', 'Backup not found or invalid');
  end if;
  
  -- START TRANSACTION: Delete existing data and restore backup
  -- WARNING: This will delete ALL tenant data and restore from backup
  
  -- Delete existing data (in STRICT reverse dependency order)
  -- Level 5: Deepest children first
  delete from journal_lines where entry_id in (select id from journal_entries where tenant_id = p_tenant_id);
  delete from mechanic_job_items where job_id in (select id from mechanic_jobs where tenant_id = p_tenant_id);
  delete from mechanic_job_timeline where job_id in (select id from mechanic_jobs where tenant_id = p_tenant_id);
  delete from online_order_items where order_id in (select id from online_orders where tenant_id = p_tenant_id);
  delete from employee_contracts where tenant_id = p_tenant_id;
  delete from attendance_records where tenant_id = p_tenant_id;
  
  -- Level 4: Tables that reference Level 5 or standalone with FKs
  delete from journal_entries where tenant_id = p_tenant_id;
  delete from sales_payments where tenant_id = p_tenant_id;
  delete from purchase_payments where tenant_id = p_tenant_id;
  delete from mechanic_jobs where tenant_id = p_tenant_id;
  delete from bikes where tenant_id = p_tenant_id;
  delete from online_orders where tenant_id = p_tenant_id;
  delete from stock_movements where tenant_id = p_tenant_id;
  
  -- Level 3: Invoices and e-commerce content
  delete from sales_invoices where tenant_id = p_tenant_id;
  delete from purchase_invoices where tenant_id = p_tenant_id;
  delete from featured_products where tenant_id = p_tenant_id;
  delete from website_blocks where tenant_id = p_tenant_id;
  delete from website_content where tenant_id = p_tenant_id;
  delete from website_banners where tenant_id = p_tenant_id;
  delete from website_settings where tenant_id = p_tenant_id;
  delete from company_settings where tenant_id = p_tenant_id;
  
  -- Level 2: Payment methods (references accounts), then products/employees/bikes
  delete from payment_methods where tenant_id = p_tenant_id;  -- BEFORE accounts!
  delete from products where tenant_id = p_tenant_id;
  delete from employees where tenant_id = p_tenant_id;
  delete from bike_models where tenant_id = p_tenant_id;
  
  -- Level 1: Base tables (brands, categories, customers, suppliers, accounts)
  delete from accounts where tenant_id = p_tenant_id;  -- AFTER payment_methods!
  delete from product_categories where tenant_id = p_tenant_id;
  delete from product_brands where tenant_id = p_tenant_id;
  delete from bike_brands where tenant_id = p_tenant_id;
  delete from customers where tenant_id = p_tenant_id;
  delete from suppliers where tenant_id = p_tenant_id;
  
  -- Restore data from backup
  -- Product Brands (restore before products)
  if v_backup_data ? 'product_brands' and v_backup_data->'product_brands' is not null and jsonb_typeof(v_backup_data->'product_brands') = 'array' then
    insert into product_brands select * from jsonb_populate_recordset(null::product_brands, v_backup_data->'product_brands');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Product Categories (restore BEFORE products - they have FK dependency)
  if v_backup_data ? 'product_categories' and v_backup_data->'product_categories' is not null and jsonb_typeof(v_backup_data->'product_categories') = 'array' then
    insert into product_categories select * from jsonb_populate_recordset(null::product_categories, v_backup_data->'product_categories');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Products (restore AFTER categories - products reference category_id)
  if v_backup_data ? 'products' and v_backup_data->'products' is not null and jsonb_typeof(v_backup_data->'products') = 'array' then
    insert into products select * from jsonb_populate_recordset(null::products, v_backup_data->'products');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Customers
  if v_backup_data ? 'customers' and v_backup_data->'customers' is not null and jsonb_typeof(v_backup_data->'customers') = 'array' then
    insert into customers select * from jsonb_populate_recordset(null::customers, v_backup_data->'customers');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Suppliers
  if v_backup_data ? 'suppliers' and v_backup_data->'suppliers' is not null and jsonb_typeof(v_backup_data->'suppliers') = 'array' then
    insert into suppliers select * from jsonb_populate_recordset(null::suppliers, v_backup_data->'suppliers');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Sales Invoices
  if v_backup_data ? 'sales_invoices' and v_backup_data->'sales_invoices' is not null and jsonb_typeof(v_backup_data->'sales_invoices') = 'array' then
    insert into sales_invoices select * from jsonb_populate_recordset(null::sales_invoices, v_backup_data->'sales_invoices');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Sales Payments
  if v_backup_data ? 'sales_payments' and v_backup_data->'sales_payments' is not null and jsonb_typeof(v_backup_data->'sales_payments') = 'array' then
    insert into sales_payments select * from jsonb_populate_recordset(null::sales_payments, v_backup_data->'sales_payments');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Purchase Invoices
  if v_backup_data ? 'purchase_invoices' and v_backup_data->'purchase_invoices' is not null and jsonb_typeof(v_backup_data->'purchase_invoices') = 'array' then
    insert into purchase_invoices select * from jsonb_populate_recordset(null::purchase_invoices, v_backup_data->'purchase_invoices');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Purchase Payments
  if v_backup_data ? 'purchase_payments' and v_backup_data->'purchase_payments' is not null and jsonb_typeof(v_backup_data->'purchase_payments') = 'array' then
    insert into purchase_payments select * from jsonb_populate_recordset(null::purchase_payments, v_backup_data->'purchase_payments');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Employees & Contracts
  if v_backup_data ? 'employees' and v_backup_data->'employees' is not null and jsonb_typeof(v_backup_data->'employees') = 'array' then
    insert into employees select * from jsonb_populate_recordset(null::employees, v_backup_data->'employees');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  if v_backup_data ? 'employee_contracts' and v_backup_data->'employee_contracts' is not null and jsonb_typeof(v_backup_data->'employee_contracts') = 'array' then
    insert into employee_contracts select * from jsonb_populate_recordset(null::employee_contracts, v_backup_data->'employee_contracts');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Attendance
  if v_backup_data ? 'attendance_records' and v_backup_data->'attendance_records' is not null and jsonb_typeof(v_backup_data->'attendance_records') = 'array' then
    insert into attendance_records select * from jsonb_populate_recordset(null::attendance_records, v_backup_data->'attendance_records');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Accounting
  if v_backup_data ? 'accounts' and v_backup_data->'accounts' is not null and jsonb_typeof(v_backup_data->'accounts') = 'array' then
    insert into accounts select * from jsonb_populate_recordset(null::accounts, v_backup_data->'accounts');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Payment Methods (restore after accounts - they reference account_id)
  if v_backup_data ? 'payment_methods' and v_backup_data->'payment_methods' is not null and jsonb_typeof(v_backup_data->'payment_methods') = 'array' then
    insert into payment_methods select * from jsonb_populate_recordset(null::payment_methods, v_backup_data->'payment_methods');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  if v_backup_data ? 'journal_entries' and v_backup_data->'journal_entries' is not null and jsonb_typeof(v_backup_data->'journal_entries') = 'array' then
    insert into journal_entries select * from jsonb_populate_recordset(null::journal_entries, v_backup_data->'journal_entries');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  if v_backup_data ? 'journal_lines' and v_backup_data->'journal_lines' is not null and jsonb_typeof(v_backup_data->'journal_lines') = 'array' then
    insert into journal_lines select * from jsonb_populate_recordset(null::journal_lines, v_backup_data->'journal_lines');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Stock Movements
  if v_backup_data ? 'stock_movements' and v_backup_data->'stock_movements' is not null and jsonb_typeof(v_backup_data->'stock_movements') = 'array' then
    insert into stock_movements select * from jsonb_populate_recordset(null::stock_movements, v_backup_data->'stock_movements');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Bike Brands (restore before bike_models and bikes)
  if v_backup_data ? 'bike_brands' and v_backup_data->'bike_brands' is not null and jsonb_typeof(v_backup_data->'bike_brands') = 'array' then
    insert into bike_brands select * from jsonb_populate_recordset(null::bike_brands, v_backup_data->'bike_brands');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Bike Models (restore before bikes)
  if v_backup_data ? 'bike_models' and v_backup_data->'bike_models' is not null and jsonb_typeof(v_backup_data->'bike_models') = 'array' then
    insert into bike_models select * from jsonb_populate_recordset(null::bike_models, v_backup_data->'bike_models');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Bikes
  if v_backup_data ? 'bikes' and v_backup_data->'bikes' is not null and jsonb_typeof(v_backup_data->'bikes') = 'array' then
    insert into bikes select * from jsonb_populate_recordset(null::bikes, v_backup_data->'bikes');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Mechanic Jobs (Pegas)
  if v_backup_data ? 'mechanic_jobs' and v_backup_data->'mechanic_jobs' is not null and jsonb_typeof(v_backup_data->'mechanic_jobs') = 'array' then
    insert into mechanic_jobs select * from jsonb_populate_recordset(null::mechanic_jobs, v_backup_data->'mechanic_jobs');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Mechanic Job Items
  if v_backup_data ? 'mechanic_job_items' and v_backup_data->'mechanic_job_items' is not null and jsonb_typeof(v_backup_data->'mechanic_job_items') = 'array' then
    insert into mechanic_job_items select * from jsonb_populate_recordset(null::mechanic_job_items, v_backup_data->'mechanic_job_items');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Mechanic Job Timeline
  if v_backup_data ? 'mechanic_job_timeline' and v_backup_data->'mechanic_job_timeline' is not null and jsonb_typeof(v_backup_data->'mechanic_job_timeline') = 'array' then
    insert into mechanic_job_timeline select * from jsonb_populate_recordset(null::mechanic_job_timeline, v_backup_data->'mechanic_job_timeline');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Company Settings
  if v_backup_data ? 'company_settings' and v_backup_data->'company_settings' is not null and jsonb_typeof(v_backup_data->'company_settings') = 'array' then
    insert into company_settings select * from jsonb_populate_recordset(null::company_settings, v_backup_data->'company_settings');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Website Settings
  if v_backup_data ? 'website_settings' and v_backup_data->'website_settings' is not null and jsonb_typeof(v_backup_data->'website_settings') = 'array' then
    insert into website_settings select * from jsonb_populate_recordset(null::website_settings, v_backup_data->'website_settings');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Website Banners
  if v_backup_data ? 'website_banners' and v_backup_data->'website_banners' is not null and jsonb_typeof(v_backup_data->'website_banners') = 'array' then
    insert into website_banners select * from jsonb_populate_recordset(null::website_banners, v_backup_data->'website_banners');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Website Content
  if v_backup_data ? 'website_content' and v_backup_data->'website_content' is not null and jsonb_typeof(v_backup_data->'website_content') = 'array' then
    insert into website_content select * from jsonb_populate_recordset(null::website_content, v_backup_data->'website_content');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Website Blocks
  if v_backup_data ? 'website_blocks' and v_backup_data->'website_blocks' is not null and jsonb_typeof(v_backup_data->'website_blocks') = 'array' then
    insert into website_blocks select * from jsonb_populate_recordset(null::website_blocks, v_backup_data->'website_blocks');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Featured Products
  if v_backup_data ? 'featured_products' and v_backup_data->'featured_products' is not null and jsonb_typeof(v_backup_data->'featured_products') = 'array' then
    insert into featured_products select * from jsonb_populate_recordset(null::featured_products, v_backup_data->'featured_products');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Online Orders
  if v_backup_data ? 'online_orders' and v_backup_data->'online_orders' is not null and jsonb_typeof(v_backup_data->'online_orders') = 'array' then
    insert into online_orders select * from jsonb_populate_recordset(null::online_orders, v_backup_data->'online_orders');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Online Order Items
  if v_backup_data ? 'online_order_items' and v_backup_data->'online_order_items' is not null and jsonb_typeof(v_backup_data->'online_order_items') = 'array' then
    insert into online_order_items select * from jsonb_populate_recordset(null::online_order_items, v_backup_data->'online_order_items');
    v_tables_restored := v_tables_restored + 1;
  end if;
  
  -- Update backup record
  update database_backups
  set status = 'restored',
      restored_at = now(),
      restored_by = auth.uid()
  where id = p_backup_id;
  
  return jsonb_build_object(
    'success', true,
    'backup_id', p_backup_id,
    'tables_restored', v_tables_restored,
    'summary', v_summary
  );
exception
  when others then
    return jsonb_build_object(
      'success', false,
      'error', SQLERRM
    );
end;
$$;


--
-- TOC entry 957 (class 1255 OID 26285)
-- Name: restore_mechanic_job_inventory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_mechanic_job_inventory(p_job_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_reference text;
  v_movement record;
begin
  if p_job_id is null then
    return;
  end if;

  v_reference := concat('mechanic_job:', p_job_id::text);

  -- Restore inventory from each stock movement
  for v_movement in
    select 
      product_id,
      quantity
    from stock_movements
    where reference = v_reference and type = 'OUT'
  loop
    -- Create reversal stock movement
    insert into stock_movements (
      product_id,
      type,
      quantity,
      reference,
      notes,
      date,
      created_at
    ) values (
      v_movement.product_id,
      'IN',
      v_movement.quantity,
      v_reference || ':reversed',
      'Inventory restored - job cancelled or modified',
      now(),
      now()
    );

    -- Update product inventory
    update products
    set 
      inventory_qty = inventory_qty + v_movement.quantity::integer,
      stock_quantity = stock_quantity + v_movement.quantity::integer,
      updated_at = now()
    where id = v_movement.product_id;
  end loop;

  -- Delete original stock movements
  delete from stock_movements
  where reference = v_reference and type = 'OUT';
end;
$$;


--
-- TOC entry 1375 (class 1255 OID 239188)
-- Name: restore_product_conversion_state(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_product_conversion_state(p_product_id uuid, p_reason text DEFAULT NULL::text, p_restore_inventory boolean DEFAULT false, p_conversion_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_product public.products;
  v_log public.user_activity_log;
  v_original_state jsonb;
  v_restore_reason text;
  v_restore_reference text;
  v_original_purchase_treatment text;
  v_original_product_type text;
  v_original_track_stock boolean;
  v_original_inventory_qty integer := 0;
  v_original_stock_qty integer := 0;
  v_original_min_stock integer := 0;
  v_original_max_stock integer := 0;
  v_inventory_value numeric(14,2) := 0;
  v_blocking_activity_count integer := 0;
  v_inventory_account_id uuid;
  v_workshop_consumables_account_id uuid;
  v_entry_id uuid;
  v_restored_inventory_qty integer := 0;
  v_restored_stock_qty integer := 0;
begin
  if p_product_id is null then
    raise exception 'Product ID is required';
  end if;

  select *
    into v_product
    from public.products
   where id = p_product_id
     and tenant_id = public.user_tenant_id()
   for update;

  if not found then
    raise exception 'Product not found or not accessible';
  end if;

  select *
    into v_log
    from public.user_activity_log
   where tenant_id = v_product.tenant_id
     and action = 'product_conversion'
     and details->>'product_id' = v_product.id::text
     and coalesce((details->>'restored')::boolean, false) = false
     and (
       p_conversion_reference is null
       or details->>'conversion_reference' = p_conversion_reference
     )
   order by created_at desc
   limit 1
   for update;

  if not found then
    raise exception 'No unreversed product conversion snapshot found for product %', v_product.name;
  end if;

  v_original_state := v_log.details->'original_state';

  if v_original_state is null then
    raise exception 'The selected conversion does not contain a reversible snapshot';
  end if;

  v_original_purchase_treatment := coalesce(v_original_state->>'purchase_treatment', 'inventory');
  v_original_product_type := coalesce(v_original_state->>'product_type', 'product');
  v_original_track_stock := coalesce((v_original_state->>'track_stock')::boolean, true);
  v_original_inventory_qty := coalesce((v_original_state->>'inventory_qty')::integer, 0);
  v_original_stock_qty := coalesce((v_original_state->>'stock_quantity')::integer, 0);
  v_original_min_stock := coalesce((v_original_state->>'min_stock_level')::integer, 0);
  v_original_max_stock := coalesce((v_original_state->>'max_stock_level')::integer, 0);
  v_inventory_value := coalesce((v_log.details->>'inventory_value')::numeric, 0);
  v_restore_reason := coalesce(
    nullif(trim(p_reason), ''),
    'Restauración de estado original del producto'
  );
  v_restore_reference := format(
    'product_restore:%s:%s',
    v_product.id,
    extract(epoch from clock_timestamp())::bigint
  );

  if p_restore_inventory then
    select case
             when exists (
               select 1
                 from public.stock_adjustments sa
                where sa.tenant_id = v_product.tenant_id
                  and sa.product_id = v_product.id
                  and sa.created_at > v_log.created_at
                  and coalesce(sa.reference, '') <> coalesce(v_log.details->>'conversion_reference', '')
             ) then 1
             when exists (
               select 1
                 from public.stock_movements sm
                where sm.tenant_id = v_product.tenant_id
                  and sm.product_id = v_product.id
                  and sm.created_at > v_log.created_at
             ) then 1
             when exists (
               select 1
                 from public.sales_invoices si
                 cross join lateral jsonb_array_elements(coalesce(si.items, '[]'::jsonb)) item
                where si.tenant_id = v_product.tenant_id
                  and si.created_at > v_log.created_at
                  and lower(coalesce(si.status, 'draft')) not in (
                    'draft','borrador',
                    'sent','enviado','enviada','issued','emitido','emitida',
                    'cancelled','cancelado','cancelada','anulado','anulada'
                  )
                  and nullif(item->>'product_id', '')::uuid = v_product.id
             ) then 1
             when exists (
               select 1
                 from public.purchase_invoices pi
                 cross join lateral jsonb_array_elements(coalesce(pi.items, '[]'::jsonb)) item
                where pi.tenant_id = v_product.tenant_id
                  and pi.created_at > v_log.created_at
                  and pi.status not in ('draft', 'cancelled')
                  and nullif(item->>'product_id', '')::uuid = v_product.id
             ) then 1
             else 0
           end
      into v_blocking_activity_count;

    if v_blocking_activity_count > 0 then
      raise exception
        'No es seguro restaurar stock/valor para el producto % porque hubo actividad después de la conversión.',
        v_product.name
        using errcode = 'check_violation',
              hint = 'Restaura solo la configuración con p_restore_inventory = false, o revisa manualmente compras/ventas posteriores.';
    end if;
  end if;

  perform set_config('app.skip_stock_adjustment_trigger', 'true', true);

  v_restored_inventory_qty := case when p_restore_inventory then v_original_inventory_qty else 0 end;
  v_restored_stock_qty := case when p_restore_inventory then v_original_stock_qty else 0 end;

  update public.products
     set purchase_treatment = v_original_purchase_treatment,
         product_type = v_original_product_type,
         track_stock = v_original_track_stock,
         inventory_qty = v_restored_inventory_qty,
         stock_quantity = v_restored_stock_qty,
         min_stock_level = v_original_min_stock,
         max_stock_level = v_original_max_stock,
         updated_at = now()
   where id = v_product.id
   returning * into v_product;

  if p_restore_inventory and v_original_inventory_qty > 0 then
    insert into public.stock_adjustments (
      tenant_id,
      product_id,
      adjustment_type,
      quantity,
      stock_before,
      stock_after,
      reason,
      reference,
      created_by,
      created_at
    ) values (
      v_product.tenant_id,
      v_product.id,
      'correction',
      v_original_inventory_qty,
      0,
      v_original_inventory_qty,
      v_restore_reason,
      v_restore_reference,
      auth.uid(),
      now()
    );

    if v_inventory_value > 0 then
      v_inventory_account_id := public.ensure_account(
        v_product.tenant_id,
        '1105',
        'Inventarios',
        'asset',
        'currentAsset',
        'Valor del inventario de productos',
        null
      );

      v_workshop_consumables_account_id := public.ensure_account(
        v_product.tenant_id,
        '5101',
        'Consumibles de Taller',
        'expense',
        'costOfGoodsSold',
        'Materiales y consumibles de uso rápido aplicados directamente en el taller',
        null
      );

      v_entry_id := gen_random_uuid();

      insert into public.journal_entries (
        id,
        tenant_id,
        entry_number,
        entry_date,
        description,
        type,
        source_module,
        source_reference,
        status,
        total_debit,
        total_credit,
        created_at,
        updated_at
      ) values (
        v_entry_id,
        v_product.tenant_id,
        public.get_next_document_number(v_product.tenant_id, 'journal_entry'),
        now(),
        format('%s - %s', v_restore_reason, v_product.name),
        'adjustment',
        'product_restore',
        v_product.id::text,
        'posted',
        v_inventory_value,
        v_inventory_value,
        now(),
        now()
      );

      insert into public.journal_lines (
        id,
        entry_id,
        account_id,
        tenant_id,
        account_code,
        account_name,
        description,
        debit_amount,
        credit_amount,
        created_at,
        updated_at
      ) values (
        gen_random_uuid(),
        v_entry_id,
        v_inventory_account_id,
        v_product.tenant_id,
        '1105',
        'Inventarios',
        format('%s - %s', v_restore_reason, v_product.name),
        v_inventory_value,
        0,
        now(),
        now()
      ), (
        gen_random_uuid(),
        v_entry_id,
        v_workshop_consumables_account_id,
        v_product.tenant_id,
        '5101',
        'Consumibles de Taller',
        format('%s - %s', v_restore_reason, v_product.name),
        0,
        v_inventory_value,
        now(),
        now()
      );
    end if;
  end if;

  update public.user_activity_log
     set details = coalesce(details, '{}'::jsonb) || jsonb_build_object(
       'restored', true,
       'restored_at', now(),
       'restored_by', auth.uid(),
       'restore_reference', v_restore_reference,
       'restored_inventory', p_restore_inventory,
       'restore_journal_entry_id', v_entry_id,
       'restore_reason', v_restore_reason
     )
   where id = v_log.id;

  insert into public.user_activity_log (
    tenant_id,
    user_id,
    action,
    details,
    performed_by,
    created_at
  ) values (
    v_product.tenant_id,
    auth.uid(),
    'product_conversion_restore',
    jsonb_build_object(
      'product_id', v_product.id,
      'product_name', v_product.name,
      'source_conversion_reference', v_log.details->>'conversion_reference',
      'restore_reference', v_restore_reference,
      'restore_reason', v_restore_reason,
      'restored_inventory', p_restore_inventory,
      'restored_inventory_qty', v_restored_inventory_qty,
      'restored_stock_qty', v_restored_stock_qty,
      'journal_entry_id', v_entry_id,
      'product_state_after_restore', jsonb_build_object(
        'purchase_treatment', coalesce(v_product.purchase_treatment, 'inventory'),
        'product_type', coalesce(v_product.product_type, 'product'),
        'track_stock', coalesce(v_product.track_stock, true),
        'inventory_qty', coalesce(v_product.inventory_qty, 0),
        'stock_quantity', coalesce(v_product.stock_quantity, 0),
        'min_stock_level', coalesce(v_product.min_stock_level, 0),
        'max_stock_level', coalesce(v_product.max_stock_level, 0)
      )
    ),
    auth.uid(),
    now()
  );

  perform set_config('app.skip_stock_adjustment_trigger', '', true);

  return jsonb_build_object(
    'product', to_jsonb(v_product),
    'source_conversion_reference', v_log.details->>'conversion_reference',
    'restore_reference', v_restore_reference,
    'restored_inventory', p_restore_inventory,
    'blocking_activity_count', v_blocking_activity_count,
    'journal_entry_id', v_entry_id
  );
exception
  when others then
    perform set_config('app.skip_stock_adjustment_trigger', '', true);
    raise;
end;
$$;


--
-- TOC entry 1986 (class 1255 OID 23961)
-- Name: restore_purchase_invoice_inventory(public.purchase_invoices); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_purchase_invoice_inventory(p_invoice public.purchase_invoices) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_reference text;
  v_item record;
  v_items jsonb;
  v_resolved_product_id uuid;
  v_quantity_numeric numeric;
  v_quantity_int integer;
  v_is_set boolean;
  v_child record;
  v_child_qty integer;
begin
  if p_invoice.id is null then
    raise notice 'restore_purchase_invoice_inventory: invoice ID is null, returning';
    return;
  end if;

  v_reference := format('purchase_invoice:%s', p_invoice.id);

  for v_item in
    select product_id, sum(quantity)::numeric as quantity
      from public.stock_movements
     where reference = v_reference
     group by product_id
    having sum(quantity) > 0
  loop
    if v_item.product_id is null then
      continue;
    end if;

    v_quantity_numeric := coalesce(v_item.quantity, 0);
    v_quantity_int := abs(v_quantity_numeric::integer);

    if v_quantity_int = 0 then
      continue;
    end if;

    update public.products
       set inventory_qty = greatest(inventory_qty - v_quantity_int, 0),
           stock_quantity = greatest(stock_quantity - v_quantity_int, 0)
     where id = v_item.product_id;

    insert into public.stock_movements (
      tenant_id,
      product_id,
      quantity,
      movement_type,
      type,
      reference,
      notes,
      date,
      created_at,
      updated_at
    ) values (
      p_invoice.tenant_id,
      v_item.product_id,
      -v_quantity_int,
      'purchase_invoice_reversal',
      'OUT',
      v_reference,
      concat(
        'Reversión de entrada por factura de compra ',
        coalesce(nullif(p_invoice.invoice_number, ''), p_invoice.id::text)
      ),
      coalesce(p_invoice.date, now()),
      now(),
      now()
    );
  end loop;

  raise notice 'restore_purchase_invoice_inventory: completed for invoice %', p_invoice.id;
end;
$$;


--
-- TOC entry 1252 (class 1255 OID 19392)
-- Name: restore_sales_invoice_inventory(public.sales_invoices); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_sales_invoice_inventory(p_invoice public.sales_invoices) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_reference text;
  v_movement record;
  v_has_inventory_qty boolean := false;
  v_has_stock_quantity boolean := false;
  v_has_is_service boolean := false;
  v_has_track_stock boolean := false;
  v_has_updated_at boolean := false;
  v_update_assignments text := '';
  v_update_sql text;
  v_quantity_int integer;
begin
  if p_invoice.id is null then
    return;
  end if;

  perform set_config('app.skip_stock_adjustment_trigger', 'true', true);

  v_reference := concat('sales_invoice:', p_invoice.id::text);

  select exists (
           select 1
             from information_schema.columns
            where table_schema = 'public'
              and table_name = 'products'
              and column_name = 'inventory_qty'
         )
    into v_has_inventory_qty;

  select exists (
           select 1
             from information_schema.columns
            where table_schema = 'public'
              and table_name = 'products'
              and column_name = 'stock_quantity'
         )
    into v_has_stock_quantity;

  select exists (
           select 1
             from information_schema.columns
            where table_schema = 'public'
              and table_name = 'products'
              and column_name = 'is_service'
         )
    into v_has_is_service;

  select exists (
           select 1
             from information_schema.columns
            where table_schema = 'public'
              and table_name = 'products'
              and column_name = 'track_stock'
         )
    into v_has_track_stock;

  select exists (
           select 1
             from information_schema.columns
            where table_schema = 'public'
              and table_name = 'products'
              and column_name = 'updated_at'
         )
    into v_has_updated_at;

  if not v_has_inventory_qty and not v_has_stock_quantity then
    perform set_config('app.skip_stock_adjustment_trigger', '', true);
    return;
  end if;

  if v_has_inventory_qty then
    v_update_assignments := v_update_assignments || 'inventory_qty = coalesce(inventory_qty, 0) + $1';
  end if;

  if v_has_stock_quantity then
    if v_update_assignments <> '' then
      v_update_assignments := v_update_assignments || ', ';
    end if;
    v_update_assignments := v_update_assignments || 'stock_quantity = coalesce(stock_quantity, 0) + $1';
  end if;

  if v_has_updated_at then
    if v_update_assignments <> '' then
      v_update_assignments := v_update_assignments || ', ';
    end if;
    v_update_assignments := v_update_assignments || 'updated_at = now()';
  end if;

  if v_update_assignments = '' then
    perform set_config('app.skip_stock_adjustment_trigger', '', true);
    return;
  end if;

  v_update_sql := 'update public.products set ' || v_update_assignments || ' where id = $2';

  if v_has_is_service then
    v_update_sql := v_update_sql || ' and coalesce(is_service, false) = false';
  end if;

  if v_has_track_stock then
    v_update_sql := v_update_sql || ' and coalesce(track_stock, true) = true';
  end if;

  for v_movement in
    select product_id, abs(sum(quantity))::integer as quantity
      from public.stock_movements
     where reference = v_reference
     group by product_id
    having sum(quantity) < 0
  loop
    if v_movement.product_id is null or v_movement.quantity = 0 then
      continue;
    end if;

    v_quantity_int := abs(coalesce(v_movement.quantity::int, 0));

    if v_quantity_int = 0 then
      continue;
    end if;

    execute v_update_sql using v_quantity_int, v_movement.product_id;

    insert into public.stock_movements (
      tenant_id,
      id,
      product_id,
      warehouse_id,
      type,
      movement_type,
      quantity,
      reference,
      notes,
      date,
      created_at,
      updated_at
    ) values (
      p_invoice.tenant_id,
      gen_random_uuid(),
      v_movement.product_id,
      null,
      'IN',
      'sales_invoice_reversal',
      v_quantity_int,
      v_reference,
      concat(
        'Reversión de salida por factura ',
        coalesce(nullif(p_invoice.invoice_number, ''), p_invoice.id::text)
      ),
      coalesce(p_invoice.date, now()),
      now(),
      now()
    );
  end loop;

  perform set_config('app.skip_stock_adjustment_trigger', '', true);
end;
$_$;


--
-- TOC entry 1460 (class 1255 OID 129496)
-- Name: restore_website_backup(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_website_backup(p_backup_id uuid, p_create_safety_backup boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_tenant_id uuid;
  v_backup record;
  v_block record;
begin
  v_tenant_id := public.user_tenant_id();
  if v_tenant_id is null then
    raise exception 'No tenant found for current user';
  end if;
  
  select * into v_backup
  from website_backups
  where id = p_backup_id and tenant_id = v_tenant_id;
  
  if not found then
    raise exception 'Backup not found or access denied';
  end if;
  
  -- Create safety backup before restoring
  if p_create_safety_backup then
    perform public.create_website_backup(
      'Auto-backup before restore: ' || v_backup.name,
      'Automatic backup created before restoring to: ' || v_backup.name,
      true
    );
  end if;
  
  -- Delete current blocks
  delete from website_blocks where tenant_id = v_tenant_id;
  
  -- Restore blocks from snapshot
  for v_block in select * from jsonb_array_elements(v_backup.blocks_snapshot)
  loop
    insert into website_blocks (
      id, tenant_id, block_type, block_data, is_visible, order_index, page_id
    ) values (
      coalesce((v_block.value->>'id')::uuid, gen_random_uuid()),
      v_tenant_id,
      v_block.value->>'block_type',
      (v_block.value->'block_data')::jsonb,
      coalesce((v_block.value->>'is_visible')::boolean, true),
      coalesce((v_block.value->>'order_index')::integer, 0),
      (v_block.value->>'page_id')::uuid
    );
  end loop;
  
  -- Restore settings
  insert into website_settings (tenant_id, key, value)
  select v_tenant_id, key, value
  from jsonb_each_text(v_backup.settings_snapshot)
  on conflict (tenant_id, key) do update
  set value = excluded.value, updated_at = now();
  
  return true;
end;
$$;


--
-- TOC entry 1616 (class 1255 OID 21100)
-- Name: reverse_purchase_invoice_inventory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_purchase_invoice_inventory(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_invoice RECORD;
  v_item JSONB;
  v_product_id UUID;
  v_quantity NUMERIC;
  v_current_qty INTEGER;
BEGIN
  -- Get invoice data
  SELECT * INTO v_invoice
  FROM purchase_invoices
  WHERE id = p_invoice_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % not found', p_invoice_id;
  END IF;

  -- Process each item in reverse
  FOR v_item IN SELECT * FROM jsonb_array_elements(v_invoice.items)
  LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_quantity := (v_item->>'quantity')::NUMERIC;

    IF v_product_id IS NULL OR v_quantity IS NULL OR v_quantity <= 0 THEN
      CONTINUE;
    END IF;

    -- Check if sufficient inventory exists
    SELECT inventory_qty INTO v_current_qty
    FROM products
    WHERE id = v_product_id;

    IF v_current_qty < v_quantity THEN
      RAISE EXCEPTION 'Inventario insuficiente para producto % (disponible: %, necesario: %)',
        v_product_id, v_current_qty, v_quantity;
    END IF;

    -- Decrease product inventory
    UPDATE products
    SET 
      inventory_qty = inventory_qty - v_quantity,
      updated_at = NOW()
    WHERE id = v_product_id;

    RAISE NOTICE 'Decreased inventory for product % (qty: %)', v_product_id, v_quantity;
  END LOOP;

  -- Delete stock movements (DELETE-based reversal)
  DELETE FROM stock_movements
  WHERE reference = p_invoice_id::TEXT
    AND movement_type IN ('purchase_invoice', 'purchase_invoice_prepaid')
    AND type = 'IN';

  RAISE NOTICE 'Inventory reversed for invoice %', v_invoice.invoice_number;
END;
$$;


--
-- TOC entry 1489 (class 1255 OID 20080)
-- Name: reverse_purchase_invoice_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_purchase_invoice_journal_entry(invoice_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  invoice_rec RECORD;
  entry_rec RECORD;
  reversal_entry_id UUID;
BEGIN
  -- Get invoice details
  SELECT * INTO invoice_rec
  FROM purchase_invoices
  WHERE id = invoice_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Purchase invoice % not found', invoice_id;
  END IF;
  
  -- Find the journal entry
  SELECT * INTO entry_rec
  FROM journal_entries
  WHERE source_module = 'purchase_invoice'
    AND source_reference = invoice_id::text
  LIMIT 1;
  
  IF NOT FOUND THEN
    RAISE NOTICE 'No journal entry found for invoice %', invoice_rec.invoice_number;
    RETURN false;
  END IF;
  
  RAISE NOTICE 'Reversing journal entry % for invoice %', 
    entry_rec.entry_number, invoice_rec.invoice_number;
  
  -- Create reversing entry (debits become credits, credits become debits)
  reversal_entry_id := gen_random_uuid();
  
  INSERT INTO journal_entries (
    id,
    entry_number,
    date,
    description,
    source_module,
    source_reference,
    type,
    status,
    created_at
  )
  VALUES (
    reversal_entry_id,
    'REV-' || entry_rec.entry_number,
    NOW(),
    'REVERSO: ' || entry_rec.description,
    'purchase_invoice_reversal',
    invoice_id::text,
    'reversal',
    'posted',
    NOW()
  );
  
  -- Copy lines with reversed debits/credits
  INSERT INTO journal_lines (
    id,
    entry_id,
    account_id,
    account_code,
    account_name,
    debit_amount,
    credit_amount,
    description
  )
  SELECT
    gen_random_uuid(),
    reversal_entry_id,
    jl.account_id,
    jl.account_code,
    jl.account_name,
    jl.credit_amount,  -- Swap: credit becomes debit
    jl.debit_amount,   -- Swap: debit becomes credit
    'REVERSO: ' || jl.description
  FROM journal_lines jl
  WHERE jl.entry_id = entry_rec.id;
  
  -- Mark original entry as reversed (don't delete it for audit trail)
  UPDATE journal_entries
  SET 
    status = 'reversed',
    description = description || ' (REVERSADO)',
    updated_at = NOW()
  WHERE id = entry_rec.id;
  
  RAISE NOTICE 'Created reversing entry % for original entry %',
    reversal_entry_id, entry_rec.id;
  
  RETURN true;
END;
$$;


--
-- TOC entry 798 (class 1255 OID 175619)
-- Name: revert_payroll_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revert_payroll_payment(p_voucher_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_line record;
BEGIN
  -- Get current status
  SELECT status INTO v_status
  FROM public.payroll_vouchers
  WHERE id = p_voucher_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payroll voucher not found';
  END IF;
  
  IF v_status <> 'paid' THEN
    RAISE EXCEPTION 'Only paid vouchers can have their payment reverted. Current status: %', v_status;
  END IF;
  
  -- For each line with an expense_id, delete the expense chain
  FOR v_line IN
    SELECT id, expense_id
    FROM public.payroll_voucher_lines
    WHERE voucher_id = p_voucher_id
      AND expense_id IS NOT NULL
  LOOP
    -- Delete expense_payments (this will trigger journal entry deletion via cascade/trigger)
    DELETE FROM public.expense_payments WHERE expense_id = v_line.expense_id;
    
    -- Delete expense_lines
    DELETE FROM public.expense_lines WHERE expense_id = v_line.expense_id;
    
    -- Delete journal entries linked to this expense
    DELETE FROM public.journal_entries 
    WHERE source_module = 'expenses' 
      AND source_reference = v_line.expense_id::text;
    
    -- Delete the expense itself
    DELETE FROM public.expenses WHERE id = v_line.expense_id;
    
    -- Clear the expense_id from the payroll line
    UPDATE public.payroll_voucher_lines
    SET expense_id = NULL
    WHERE id = v_line.id;
  END LOOP;
  
  -- Update voucher status back to confirmed
  UPDATE public.payroll_vouchers
  SET status = 'confirmed',
      paid_at = NULL,
      paid_by = NULL,
      updated_at = now()
  WHERE id = p_voucher_id;
  
  RAISE NOTICE 'Payroll payment reverted for voucher %', p_voucher_id;
  
  RETURN true;
END;
$$;


--
-- TOC entry 795 (class 1255 OID 175620)
-- Name: revert_payroll_to_draft(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revert_payroll_to_draft(p_voucher_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  -- Get current status
  SELECT status INTO v_status
  FROM public.payroll_vouchers
  WHERE id = p_voucher_id;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payroll voucher not found';
  END IF;
  
  IF v_status <> 'confirmed' THEN
    RAISE EXCEPTION 'Only confirmed vouchers can be reverted to draft. Current status: %', v_status;
  END IF;
  
  -- Update to draft
  UPDATE public.payroll_vouchers
  SET status = 'draft',
      updated_at = now()
  WHERE id = p_voucher_id;
  
  RETURN true;
END;
$$;


