--
-- TOC entry 1523 (class 1255 OID 211708)
-- Name: set_purchase_context_on_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_purchase_context_on_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- When status changes to 'received', we are about to update stock.
  -- Set the context variables so the product trigger knows it's a purchase.
  IF NEW.status = 'received' AND (OLD.status IS DISTINCT FROM 'received') THEN
    
    PERFORM set_config('app.stock_adjustment_context', 'purchase', true);
    PERFORM set_config('app.stock_adjustment_reference', COALESCE(NEW.invoice_number, NEW.id::text), true);
    
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- TOC entry 1346 (class 1255 OID 102079)
-- Name: set_task_completed_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_task_completed_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if NEW.is_completed and not OLD.is_completed then
    NEW.completed_at := now();
    NEW.completed_by_user_id := auth.uid();
  elsif not NEW.is_completed and OLD.is_completed then
    NEW.completed_at := null;
    NEW.completed_by_user_id := null;
  end if;
  
  return NEW;
end;
$$;


