--
-- TOC entry 1744 (class 1255 OID 21103)
-- Name: settle_prepaid_inventory_on_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_prepaid_inventory_on_order(p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_invoice RECORD;
  v_entry_id UUID;
  v_inventory_account_id UUID;       -- Inventario (1150)
  v_inv_transit_account_id UUID;     -- Inventario en Tránsito (1155)
BEGIN
  -- Get invoice data
  SELECT * INTO v_invoice
  FROM purchase_invoices
  WHERE id = p_invoice_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % not found', p_invoice_id;
  END IF;

  -- Get account IDs
  SELECT id INTO v_inventory_account_id FROM accounts WHERE code = '1150' LIMIT 1;
  SELECT id INTO v_inv_transit_account_id FROM accounts WHERE code = '1155' LIMIT 1;

  IF v_inventory_account_id IS NULL OR v_inv_transit_account_id IS NULL THEN
    RAISE EXCEPTION 'Required accounts not found for settlement (1150, 1155)';
  END IF;

  -- Create settlement journal entry
  INSERT INTO journal_entries (
    id,
    entry_number,
    entry_date,
    entry_type,
    source_module,
    source_reference,
    status,
    notes,
    created_at
  )
  VALUES (
    gen_random_uuid(),
    'RECEP-PREPAID-' || v_invoice.invoice_number,
    v_invoice.received_date,
    'purchase_receipt',
    'purchase_invoices',
    p_invoice_id::TEXT,
    'posted',
    'Recepción de inventario prepagado - ' || v_invoice.invoice_number,
    NOW()
  )
  RETURNING id INTO v_entry_id;

  -- DR: Inventario (move from transit to stock)
  INSERT INTO journal_lines (id, journal_entry_id, account_id, debit, credit, description, created_at)
  VALUES (
    gen_random_uuid(),
    v_entry_id,
    v_inventory_account_id,
    v_invoice.subtotal,
    0,
    'Inventario recibido',
    NOW()
  );

  -- CR: Inventario en Tránsito
  INSERT INTO journal_lines (id, journal_entry_id, account_id, debit, credit, description, created_at)
  VALUES (
    gen_random_uuid(),
    v_entry_id,
    v_inv_transit_account_id,
    0,
    v_invoice.subtotal,
    'Inventario en tránsito a stock',
    NOW()
  );

  RAISE NOTICE 'Created settlement entry % for invoice %', v_entry_id, v_invoice.invoice_number;
  RETURN v_entry_id;
END;
$$;


--
-- TOC entry 1464 (class 1255 OID 102077)
-- Name: sync_adhoc_task_to_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_adhoc_task_to_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if TG_OP = 'INSERT' then
    -- ✅ UPDATED (Nov 18, 2025): Sub-tasks WITH prices should also create ad-hoc items
    -- These appear as separate line items in pega forms and invoices
    if NEW.is_adhoc and NEW.adhoc_price is not null and NEW.adhoc_price > 0 then
      perform public.create_adhoc_item_for_task(NEW.id);
    end if;
    
  elsif TG_OP = 'UPDATE' then
    -- Price added or updated on task (parent OR sub-task)
    if NEW.is_adhoc and NEW.adhoc_price is not null and 
       (OLD.adhoc_price is null or OLD.adhoc_price != NEW.adhoc_price) then
      
      -- If item exists, update it
      if NEW.adhoc_item_id is not null then
        update mechanic_job_items
        set 
          product_name = 'Ad-hoc: ' || NEW.task_name,
          unit_price = NEW.adhoc_price,
          total_price = NEW.adhoc_price
        where id = NEW.adhoc_item_id;
      else
        -- Create new item
        perform public.create_adhoc_item_for_task(NEW.id);
      end if;
    end if;
    
    -- Price removed
    if OLD.adhoc_price is not null and NEW.adhoc_price is null and NEW.adhoc_item_id is not null then
      delete from mechanic_job_items where id = NEW.adhoc_item_id;
    end if;
  end if;
  
  return null; -- AFTER trigger must return null
end;
$$;


--
-- TOC entry 1801 (class 1255 OID 136414)
-- Name: sync_inventory_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_inventory_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- If inventory_qty changed, sync stock_quantity
  IF NEW.inventory_qty IS DISTINCT FROM OLD.inventory_qty THEN
    NEW.stock_quantity := NEW.inventory_qty;
  -- If stock_quantity changed, sync inventory_qty
  ELSIF NEW.stock_quantity IS DISTINCT FROM OLD.stock_quantity THEN
    NEW.inventory_qty := NEW.stock_quantity;
  END IF;
  RETURN NEW;
END;
$$;


--
-- TOC entry 1831 (class 1255 OID 28010)
-- Name: sync_invoice_items_to_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_invoice_items_to_job(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_job_id uuid;
  v_invoice record;
  v_item jsonb;
  v_subtotal numeric(12,2) := 0;
  v_labor_cost numeric(12,2) := 0;
  v_parts_cost numeric(12,2) := 0;
  v_product_id uuid;
  v_product_type text;
  v_product_name text;
  v_quantity numeric(12,2);
  v_unit_price numeric(12,2);
  v_line_total numeric(12,2);
  v_tenant_id uuid;
  v_job_bike_id uuid;
  v_item_count integer := 0;
begin
  -- Prevent circular sync in either direction
  if current_setting('app.syncing_invoice_to_job', true) = 'true' or
     current_setting('app.syncing_job_to_invoice', true) = 'true' then
    raise notice 'sync_invoice_items_to_job: skipping due to active sync flag';
    return;
  end if;

  -- Prevent circular sync: if we're already deep in triggers, skip
  if pg_trigger_depth() > 2 then
    raise notice 'sync_invoice_items_to_job: trigger depth too deep (%), skipping to prevent circular sync', pg_trigger_depth();
    return;
  end if;

  -- Find the job linked to this invoice
  select id into v_job_id
  from mechanic_jobs
  where invoice_id = p_invoice_id;
  
  if v_job_id is null then
    raise notice 'No job linked to invoice %', p_invoice_id;
    return;
  end if;
  
  -- Get invoice details
  select * into v_invoice
  from sales_invoices
  where id = p_invoice_id;
  
  if not found then
    raise notice 'Invoice % not found', p_invoice_id;
    return;
  end if;
  
  -- Get tenant_id from invoice
  v_tenant_id := v_invoice.tenant_id;
  
  -- ============================================================
  -- CRITICAL FIX (Mar 19, 2026): Disable row triggers on mechanic_job_items
  -- during the sync to prevent:
  --   1) Cascading trigger chains (5+ triggers per INSERT) that cause
  --      savepoint/set_config interactions to lose the sync guard flag
  --   2) Redundant cost recalculations (we calculate costs ourselves below)
  --   3) auto_parse_item_description side-effects during sync
  --   4) Back-sync attempts to invoice via statement-level triggers
  -- We re-enable triggers in a finally-style block to guarantee cleanup.
  -- This function is SECURITY DEFINER so it has permission to alter triggers.
  -- ============================================================
  alter table mechanic_job_items disable trigger user;
  
  -- Set sync flag (transaction-scoped, NOT savepoint-scoped)
  perform set_config('app.syncing_invoice_to_job', 'true', true);
  
  -- Delete existing job items (no triggers fire — they are disabled)
  delete from mechanic_job_items where job_id = v_job_id;
  
  -- Process each invoice item
  for v_item in select * from jsonb_array_elements(v_invoice.items)
  loop
    v_product_id := nullif(v_item->>'product_id', '')::uuid;
    v_quantity := coalesce((v_item->>'quantity')::numeric, 1);
    v_unit_price := coalesce((v_item->>'unit_price')::numeric, 0);
    v_line_total := coalesce((v_item->>'line_total')::numeric, v_quantity * v_unit_price, 0);
    v_product_name := v_item->>'product_name';

    -- Resolve job_bike_id from item JSON.
    -- If the invoice item has no bike assigned (null / empty), keep it NULL in mechanic_job_items
    -- so the item appears as "General" (not forcibly assigned to the first bike).
    v_job_bike_id := nullif(v_item->>'job_bike_id', '')::uuid;
    if v_job_bike_id is not null then
      -- Validate the bike still exists for this job; if not, clear it (don't fallback to default)
      if not exists (
        select 1 from mechanic_job_bikes 
        where id = v_job_bike_id and job_id = v_job_id
      ) then
        v_job_bike_id := null;
      end if;
    end if;
    -- v_job_bike_id remains NULL for "General / no bike" items — this is intentional.

    -- Determine product info (if exists)
    v_product_type := null;
    v_product_name := null;
    if v_product_id is not null then
      select product_type, name
      into v_product_type, v_product_name
      from products
      where id = v_product_id;
      if not found then
        v_product_type := null;
        v_product_name := null;
      end if;
    end if;

    if v_product_id is null or v_product_type = 'service' then
      v_labor_cost := v_labor_cost + v_line_total;
    else
      v_parts_cost := v_parts_cost + v_line_total;
    end if;

    -- Calculate total_price inline (BEFORE trigger trg_calculate_mechanic_job_item_total is disabled)
    if v_quantity is null or v_quantity = 0 then
      v_quantity := 1;
    end if;

    insert into mechanic_job_items (
      tenant_id,
      job_id,
      job_bike_id,
      product_id,
      product_name,
      product_sku,
      quantity,
      unit_price,
      total_price,
      notes,
      description,
      item_type,
      service_product_id,
      created_at,
      updated_at
    ) values (
      v_tenant_id,
      v_job_id,
      v_job_bike_id,
      case when v_product_type = 'service' then null else v_product_id end,
      coalesce(v_product_name, v_item->>'product_name'),
      coalesce(v_item->>'product_sku', ''),
      v_quantity,
      v_unit_price,
      v_line_total,
      coalesce(v_item->>'description', ''),
      coalesce(v_item->>'description', ''),
      case when v_product_id is null or v_product_type = 'service' then 'service' else 'product' end,
      case when v_product_id is null or v_product_type = 'service' then v_product_id else null end,
      now(),
      now()
    );
    
    v_item_count := v_item_count + 1;
  end loop;
  
  v_subtotal := v_parts_cost + v_labor_cost;
  
  -- Update job costs directly (no trigger cascades since we calculated everything)
  update mechanic_jobs
  set 
    labor_cost = v_labor_cost,
    parts_cost = v_parts_cost,
    final_cost = v_subtotal,
    estimated_cost = v_subtotal,
    total_cost = v_invoice.total,
    tax_amount = v_invoice.iva_amount,
    updated_at = now()
  where id = v_job_id;

  -- Update per-bike costs if multi-bike job
  update mechanic_job_bikes mjb
  set 
    parts_cost = coalesce(sub.parts_cost, 0),
    labor_cost = coalesce(sub.labor_cost, 0),
    subtotal = coalesce(sub.parts_cost, 0) + coalesce(sub.labor_cost, 0),
    updated_at = now()
  from (
    select 
      mji.job_bike_id,
      sum(case when coalesce(mji.item_type, 'product') <> 'service' then mji.total_price else 0 end) as parts_cost,
      sum(case when coalesce(mji.item_type, 'product') = 'service' then mji.total_price else 0 end) as labor_cost
    from mechanic_job_items mji
    where mji.job_id = v_job_id
      and mji.job_bike_id is not null
    group by mji.job_bike_id
  ) sub
  where mjb.id = sub.job_bike_id
    and mjb.job_id = v_job_id;

  -- Re-enable triggers (ALWAYS runs, even if error above would propagate)
  alter table mechanic_job_items enable trigger user;
  
  -- Clear the sync flag
  perform set_config('app.syncing_invoice_to_job', '', true);
  
  raise notice 'Synced invoice % items to job %: % items (parts: $%, labor: $%)', 
    p_invoice_id, v_job_id, v_item_count, v_parts_cost, v_labor_cost;
    
exception
  when others then
    -- CRITICAL: Re-enable triggers even on error to prevent table being stuck
    alter table mechanic_job_items enable trigger user;
    perform set_config('app.syncing_invoice_to_job', '', true);
    raise;
end;
$_$;


--
-- TOC entry 1747 (class 1255 OID 28011)
-- Name: sync_invoice_status_to_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_invoice_status_to_job(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_job_id uuid; v_invoice record; v_is_paid boolean;
begin
  if current_setting('app.syncing_invoice_to_job', true) = 'true' or current_setting('app.syncing_job_to_invoice', true) = 'true' then return; end if;
  select id into v_job_id from mechanic_jobs where invoice_id = p_invoice_id;
  if v_job_id is null then return; end if;
  select * into v_invoice from sales_invoices where id = p_invoice_id;
  if not found then return; end if;
  v_is_paid := (lower(v_invoice.status) = 'paid');
  update mechanic_jobs set is_invoiced = true, is_paid = v_is_paid, tax_treatment = v_invoice.tax_treatment, updated_at = now() where id = v_job_id;
end;
$$;


--
-- TOC entry 832 (class 1255 OID 70125)
-- Name: sync_invoice_to_job_on_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_invoice_to_job_on_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job_id uuid;
begin
  -- Skip if invoice is not linked to a pega
  -- Check if this invoice references a mechanic job
  select id into v_job_id
  from public.mechanic_jobs
  where invoice_id = NEW.id
  limit 1;
  
  if v_job_id is null then
    -- Not a pega-linked invoice, skip sync
    return NEW;
  end if;
  
  -- Skip if this UPDATE was triggered by job → invoice sync
  if current_setting('app.syncing_job_to_invoice', true) = 'true' then
    raise notice 'Skipping invoice→job sync (job→invoice sync in progress)';
    return NEW;
  end if;

  -- Prevent circular triggers (invoice → job → invoice → ...)
  -- Check if we're already inside a job sync operation
  if current_setting('app.syncing_invoice_to_job', true) = 'true' then
    raise notice 'Skipping invoice→job sync (circular prevention)';
    return NEW;
  end if;
  
  -- Set flag to prevent circular sync
  perform set_config('app.syncing_invoice_to_job', 'true', true);
  
  -- Call existing sync function to update job items from invoice
  -- Function only needs invoice_id, it finds the job internally
  perform public.sync_invoice_items_to_job(NEW.id);
  
  raise notice 'Synced invoice % changes to pega %', NEW.id, v_job_id;
  
  return NEW;
end;
$$;


