--
-- TOC entry 1844 (class 1255 OID 28328)
-- Name: sync_job_labor_to_invoice_statement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_job_labor_to_invoice_statement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job_id uuid;
  v_invoice_id uuid;
  v_syncing_flag text;
begin
  -- Check if we're currently syncing invoice → job (prevent circular sync)
  v_syncing_flag := current_setting('app.syncing_invoice_to_job', true);
  if v_syncing_flag = 'true' then
    raise notice 'sync_job_labor_to_invoice_statement: skipping due to invoice→job sync in progress';
    return null;
  end if;

  -- Handle DELETE operations - get job_id from old_table
  if TG_OP = 'DELETE' then
    for v_job_id in select distinct job_id from old_table
    loop
      -- Recalculate costs first to update job record with new totals
      perform public.recalculate_mechanic_job_costs(v_job_id);
      
      -- Find the linked invoice
      select invoice_id into v_invoice_id from mechanic_jobs where id = v_job_id;
      
      if v_invoice_id is not null then
        -- Sync this job to its invoice (will remove deleted labor)
        perform public.sync_job_to_invoice(v_job_id);
      end if;
    end loop;
    return null;
  end if;

  -- Handle INSERT and UPDATE - sync immediately since we're adding/changing items
  for v_job_id in select distinct job_id from new_table
  loop
    -- Recalculate costs first to update job record with new totals
    perform public.recalculate_mechanic_job_costs(v_job_id);
    
    -- Find the linked invoice
    select invoice_id into v_invoice_id from mechanic_jobs where id = v_job_id;
    
    if v_invoice_id is not null then
      -- Sync this job to its invoice (will recalculate fresh totals from DB)
      perform public.sync_job_to_invoice(v_job_id);
    end if;
  end loop;
  
  return null;
end;
$$;


--
-- TOC entry 588 (class 1255 OID 28054)
-- Name: sync_job_to_invoice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_job_to_invoice(p_job_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_invoice_id uuid;
  v_job record;
  v_items jsonb := '[]'::jsonb;
  v_item record;
  v_parts_cost numeric(12,2) := 0;
  v_labor_cost numeric(12,2) := 0;
  v_subtotal numeric(12,2) := 0;
  v_discount numeric(12,2) := 0;
  v_iva_amount numeric(12,2) := 0;
  v_total numeric(12,2) := 0;
  v_syncing_flag text;
  v_bike_name text;
BEGIN
  -- Check if we're currently syncing invoice → job (prevent circular sync)
  v_syncing_flag := current_setting('app.syncing_invoice_to_job', true);
  IF v_syncing_flag = 'true' THEN
    RAISE NOTICE 'sync_job_to_invoice: skipping due to invoice→job sync in progress';
    RETURN;
  END IF;

  -- Get the job and its linked invoice
  SELECT * INTO v_job
  FROM mechanic_jobs
  WHERE id = p_job_id;
  
  IF NOT FOUND THEN
    RAISE NOTICE 'Job % not found', p_job_id;
    RETURN;
  END IF;
  
  v_invoice_id := v_job.invoice_id;
  
  IF v_invoice_id IS NULL THEN
    RAISE NOTICE 'Job % has no linked invoice', p_job_id;
    RETURN;
  END IF;
  
  SELECT coalesce(discount_amount, 0)
  INTO v_discount
  FROM mechanic_jobs
  WHERE id = p_job_id;
  
  -- Build invoice items array from mechanic_job_items (products + services)
  FOR v_item IN 
    SELECT * FROM mechanic_job_items WHERE job_id = p_job_id
  LOOP
    -- Resolve bike display name from job_bike_id
    v_bike_name := NULL;
    IF v_item.job_bike_id IS NOT NULL THEN
      SELECT COALESCE(
        NULLIF(CONCAT_WS(' ', b.brand, b.model), ''),
        'Bicicleta'
      )
      INTO v_bike_name
      FROM mechanic_job_bikes mjb
      JOIN bikes b ON b.id = mjb.bike_id
      WHERE mjb.id = v_item.job_bike_id;
    END IF;

    v_items := v_items || jsonb_build_object(
      'product_id', CASE WHEN coalesce(v_item.item_type, 'product') = 'service'
                         THEN coalesce(v_item.service_product_id::text, '')
                         ELSE v_item.product_id::text
                    END,
      'product_name', v_item.product_name,
      'product_sku', coalesce(v_item.product_sku, ''),
      'description', coalesce(v_item.notes, ''),
      'item_type', coalesce(v_item.item_type, 'product'),
      'is_catalog_product', CASE WHEN v_item.item_type = 'adhoc' THEN false ELSE true END,
      'quantity', v_item.quantity,
      'unit_price', v_item.unit_price,
      'line_total', coalesce(v_item.total_price, v_item.quantity * v_item.unit_price, 0),
      'job_bike_id', v_item.job_bike_id,
      'bike_name', v_bike_name
    );

    IF coalesce(v_item.item_type, 'product') IN ('service', 'adhoc') THEN
      v_labor_cost := v_labor_cost + coalesce(v_item.total_price, v_item.quantity * v_item.unit_price, 0);
    ELSE
      v_parts_cost := v_parts_cost + coalesce(v_item.total_price, v_item.quantity * v_item.unit_price, 0);
    END IF;
  END LOOP;
  
  -- Calculate totals with FRESH data
  v_subtotal := v_parts_cost + v_labor_cost - v_discount;
  
  -- Calculate IVA based on job's tax treatment
  IF v_job.tax_treatment = 'tax_included' THEN
    v_iva_amount := round(v_subtotal - (v_subtotal / 1.19), 0);
  ELSE
    v_iva_amount := 0;
  END IF;
  
  v_total := v_subtotal;
  
  -- Update the invoice with fresh calculations
  PERFORM set_config('app.syncing_job_to_invoice', 'true', true);

  UPDATE sales_invoices
  SET
    items = v_items,
    subtotal = v_subtotal,
    iva_amount = v_iva_amount,
    net_amount = CASE 
      WHEN v_job.tax_treatment = 'tax_included' THEN v_subtotal / 1.19
      ELSE v_subtotal
    END,
    tax_treatment = v_job.tax_treatment,
    total = v_total,
    discount_amount = v_discount,
    updated_at = now()
  WHERE id = v_invoice_id;
  
  -- Let the payment recalculation function handle balance and status
  PERFORM public.recalculate_sales_invoice_payments(v_invoice_id);

  -- Clear job → invoice flag
  PERFORM set_config('app.syncing_job_to_invoice', '', true);
  
  RAISE NOTICE 'Synced job % to invoice % (% items, subtotal: $%, total: $%)', p_job_id, v_invoice_id, jsonb_array_length(v_items), v_subtotal, v_total;
END;
$_$;


--
-- TOC entry 968 (class 1255 OID 251477)
-- Name: sync_journal_entry_totals_from_lines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_journal_entry_totals_from_lines() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.recalculate_journal_entry_totals(old.entry_id);
    return old;
  end if;

  if tg_op = 'UPDATE' and old.entry_id is distinct from new.entry_id then
    perform public.recalculate_journal_entry_totals(old.entry_id);
  end if;

  perform public.recalculate_journal_entry_totals(new.entry_id);
  return new;
end;
$$;


--
-- TOC entry 1913 (class 1255 OID 59428)
-- Name: sync_product_category_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_product_category_name() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Update category_name from product_categories table
  if NEW.category_id is not null then
    select name into NEW.category_name
    from product_categories
    where id = NEW.category_id;
  else
    NEW.category_name := null;
  end if;
  
  -- Update supplier_name from suppliers table
  if NEW.supplier_id is not null then
    select name into NEW.supplier_name
    from suppliers
    where id = NEW.supplier_id;
  else
    NEW.supplier_name := null;
  end if;
  
  return NEW;
end;
$$;


--
-- TOC entry 1435 (class 1255 OID 170990)
-- Name: sync_product_service_flags(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_product_service_flags() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_old_tracks_inventory boolean := false;
  v_new_tracks_inventory boolean := false;
  v_existing_stock integer := 0;
begin
  if NEW.product_type is null then
    NEW.product_type := 'product';
  end if;

  if NEW.purchase_treatment is null or
     NEW.purchase_treatment not in ('inventory', 'workshop_consumable') then
    NEW.purchase_treatment := 'inventory';
  end if;

  NEW.is_service := (NEW.product_type = 'service');

  if TG_OP = 'UPDATE' then
    v_old_tracks_inventory :=
      coalesce(OLD.product_type, 'product') <> 'service'
      and coalesce(OLD.purchase_treatment, 'inventory') = 'inventory'
      and coalesce(OLD.track_stock, true) = true;

    v_new_tracks_inventory :=
      NEW.product_type <> 'service'
      and NEW.purchase_treatment = 'inventory'
      and coalesce(NEW.track_stock, true) = true;

    v_existing_stock := greatest(
      coalesce(OLD.inventory_qty, 0),
      coalesce(OLD.stock_quantity, 0)
    );

    if v_old_tracks_inventory
       and not v_new_tracks_inventory
       and v_existing_stock > 0 then
      raise exception
        'No se puede desactivar el control de inventario para el producto % mientras tenga stock (% unidades).',
        coalesce(NEW.name, OLD.name, 'sin nombre'),
        v_existing_stock
        using errcode = 'check_violation',
              hint = 'Primero deja el stock en 0 y reclasifica el valor contable antes de cambiarlo a consumible de taller o servicio.';
    end if;
  end if;

  if NEW.is_service then
    NEW.purchase_treatment := 'inventory';
    NEW.track_stock := false;
    NEW.inventory_qty := 0;
    NEW.stock_quantity := 0;
    NEW.min_stock_level := 0;
    NEW.max_stock_level := 0;
  elsif NEW.purchase_treatment = 'workshop_consumable' then
    NEW.track_stock := false;
    NEW.inventory_qty := 0;
    NEW.stock_quantity := 0;
    NEW.min_stock_level := 0;
    NEW.max_stock_level := 0;
  end if;

  return NEW;
end;
$$;


