--
-- TOC entry 633 (class 1255 OID 151102)
-- Name: sync_set_inventory_from_component(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_set_inventory_from_component() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_set_id UUID;
  v_new_set_stock INTEGER;
BEGIN
  -- If app.skip_sync_set_inventory is set, skip this trigger to avoid recursion loops
  -- (though strictly speaking, updating the parent set shouldn't trigger this again for the component)
  IF current_setting('app.skip_sync_set_inventory', true) = 'true' THEN
    RETURN OLD; -- Trigger is AFTER UPDATE, return value ignored but good practice
  END IF;

  -- Find all parent sets that contain this product as a component
  FOR v_set_id IN
    SELECT set_product_id
    FROM public.product_set_components
    WHERE component_product_id = NEW.id
  LOOP
    -- Calculate how many full sets can be made from ALL components now
    -- We use the existing helper function: public.get_full_sets_count(set_id)
    v_new_set_stock := public.get_full_sets_count(v_set_id);

    RAISE NOTICE 'Syncing Set %: Component % changed stock to %. New Set Stock: %', 
      v_set_id, NEW.id, NEW.stock_quantity, v_new_set_stock;

    -- Update the parent set's inventory
    -- We set app.skip_stock_adjustment_trigger to true to avoid creating stock movements for this automatic sync
    -- We also set app.skip_sync_set_inventory to true to verify no recursion happens (though unrelated)
    PERFORM set_config('app.skip_stock_adjustment_trigger', 'true', true);

    UPDATE public.products
    SET 
      inventory_qty = v_new_set_stock,
      stock_quantity = v_new_set_stock,
      updated_at = now()
    WHERE id = v_set_id
      AND (inventory_qty != v_new_set_stock OR stock_quantity != v_new_set_stock); -- Only update if changed
      
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- TOC entry 2063 (class 1255 OID 175565)
-- Name: sync_stock_adjustment_to_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_stock_adjustment_to_movement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  insert into public.stock_movements (
    tenant_id,
    product_id,
    date,
    type,
    movement_type,
    reference,
    quantity,
    notes,
    created_at
  ) values (
    NEW.tenant_id,
    NEW.product_id,
    coalesce(NEW.adjustment_date, NEW.created_at),
    case when NEW.quantity >= 0 then 'IN' else 'OUT' end,
    NEW.adjustment_type,
    NEW.reference,
    abs(NEW.quantity),
    NEW.reason,
    NEW.created_at
  );
  return NEW;
end;
$$;


--
-- TOC entry 1740 (class 1255 OID 66145)
-- Name: track_product_stock_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_product_stock_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_adjustment_type text;
  v_reason text;
  v_reference text;
  v_context text;
  v_stock_before integer;
  v_stock_after integer;
  v_adjustment_qty integer;
begin
  if coalesce(NEW.product_type, 'product') = 'service'
     or coalesce(NEW.track_stock, true) = false then
    return NEW;
  end if;

  if current_setting('app.skip_stock_adjustment_trigger', true) = 'true' then
    return NEW;
  end if;

  if (TG_OP = 'UPDATE' and OLD.stock_quantity <> NEW.stock_quantity) then
    if OLD.inventory_qty is distinct from OLD.stock_quantity
       and NEW.stock_quantity = NEW.inventory_qty then
      v_stock_before := OLD.inventory_qty;
      v_stock_after := NEW.inventory_qty;
    else
      v_stock_before := OLD.stock_quantity;
      v_stock_after := NEW.stock_quantity;
    end if;

    v_adjustment_qty := v_stock_after - v_stock_before;

    if v_adjustment_qty = 0 then
      return NEW;
    end if;

    v_context := current_setting('app.stock_adjustment_context', true);

    if v_context = 'import' then
      v_adjustment_type := 'import';
      v_reason := coalesce(current_setting('app.import_reason', true), 'Stock updated via import');
      v_reference := current_setting('app.import_reference', true);
    elsif v_context = 'purchase' then
      v_adjustment_type := 'purchase';
      v_reason := 'Compra recibida (Invoice ' || coalesce(current_setting('app.stock_adjustment_reference', true), 'Unknown') || ')';
      v_reference := current_setting('app.stock_adjustment_reference', true);
    else
      v_adjustment_type := 'manual';
      v_reason := 'Ajuste Manual';
      v_reference := null;
    end if;

    insert into stock_adjustments (
      tenant_id,
      product_id,
      adjustment_type,
      quantity,
      stock_before,
      stock_after,
      reason,
      reference,
      created_by
    ) values (
      NEW.tenant_id,
      NEW.id,
      v_adjustment_type,
      v_adjustment_qty,
      v_stock_before,
      v_stock_after,
      v_reason,
      v_reference,
      auth.uid()
    );

  elsif (TG_OP = 'INSERT' and NEW.stock_quantity > 0) then
    v_context := current_setting('app.stock_adjustment_context', true);

    if v_context = 'import' then
      v_adjustment_type := 'import';
      v_reason := coalesce(current_setting('app.import_reason', true), 'Initial stock via import');
      v_reference := current_setting('app.import_reference', true);
    else
      v_adjustment_type := 'initial';
      v_reason := 'Initial stock on product creation';
      v_reference := null;
    end if;

    insert into stock_adjustments (
      tenant_id,
      product_id,
      adjustment_type,
      quantity,
      stock_before,
      stock_after,
      reason,
      reference,
      created_by
    ) values (
      NEW.tenant_id,
      NEW.id,
      v_adjustment_type,
      NEW.stock_quantity,
      0,
      NEW.stock_quantity,
      v_reason,
      v_reference,
      auth.uid()
    );
  end if;

  return NEW;
end;
$$;


