--
-- TOC entry 2040 (class 1255 OID 99843)
-- Name: update_mechanic_job_costs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_mechanic_job_costs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_parts_cost numeric; v_labor_cost numeric; v_total_cost numeric;
begin
  if current_setting('app.syncing_invoice_to_job', true) = 'true' or current_setting('app.syncing_job_to_invoice', true) = 'true' then return coalesce(NEW, OLD); end if;
  select coalesce(sum(total_price), 0) into v_parts_cost from mechanic_job_items where job_id = coalesce(NEW.job_id, OLD.job_id) and coalesce(item_type, 'product') <> 'service';
  select coalesce(sum(total_price), 0) into v_labor_cost from mechanic_job_items where job_id = coalesce(NEW.job_id, OLD.job_id) and coalesce(item_type, 'product') = 'service';
  v_total_cost := v_parts_cost + v_labor_cost;
  update mechanic_jobs set parts_cost = v_parts_cost, labor_cost = v_labor_cost, total_cost = v_total_cost, updated_at = now() where id = coalesce(NEW.job_id, OLD.job_id);
  return coalesce(NEW, OLD);
end;
$$;


--
-- TOC entry 1385 (class 1255 OID 133810)
-- Name: update_online_order_status(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_online_order_status(p_order_id uuid, p_new_status text, p_tracking_number text DEFAULT NULL::text, p_tracking_url text DEFAULT NULL::text, p_carrier text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_order record;
  v_invoice_id uuid;
begin
  select * into v_order
  from online_orders
  where id = p_order_id
    and tenant_id = public.user_tenant_id();
    
  if v_order is null then
    raise exception 'Order not found or access denied: %', p_order_id;
  end if;
  
  if v_order.status = 'cancelled' then
    raise exception 'Cannot change status of cancelled order';
  end if;
  
  case p_new_status
    when 'confirmed' then
      if v_order.invoice_id is null and v_order.payment_status = 'paid' then
        v_invoice_id := public.process_online_order(p_order_id);
      end if;
    when 'processing' then
      if v_order.invoice_id is null then
        raise exception 'Cannot process order without invoice';
      end if;
    when 'ready_for_pickup' then
      if v_order.delivery_type != 'pickup' then
        raise exception 'Can only mark pickup orders as ready_for_pickup';
      end if;
      update online_orders set ready_for_pickup_at = now() where id = p_order_id;
    when 'shipped' then
      if v_order.delivery_type != 'shipping' then
        raise exception 'Can only ship delivery orders';
      end if;
      update online_orders
      set shipped_at = now(),
          tracking_number = coalesce(p_tracking_number, tracking_number),
          tracking_url = coalesce(p_tracking_url, tracking_url),
          shipping_carrier = coalesce(p_carrier, shipping_carrier)
      where id = p_order_id;
    when 'delivered' then
      update online_orders set delivered_at = now() where id = p_order_id;
    when 'cancelled' then
      return public.cancel_online_order(p_order_id, coalesce(p_notes, 'Cancelado'));
    else
      raise exception 'Invalid status: %', p_new_status;
  end case;
  
  update online_orders
  set status = p_new_status, notes = coalesce(p_notes, notes), updated_at = now()
  where id = p_order_id;
  
  return jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'old_status', v_order.status,
    'new_status', p_new_status,
    'invoice_id', coalesce(v_invoice_id, v_order.invoice_id)
  );
end;
$$;


