--
-- TOC entry 2103 (class 1255 OID 43560)
-- Name: upsert_company_setting(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_company_setting(p_tenant_id uuid, p_key text, p_value text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_tenant_id uuid;
begin
  -- Get user's tenant_id
  v_user_tenant_id := public.user_tenant_id();
  
  -- Verify user has access to this tenant
  if p_tenant_id != v_user_tenant_id then
    raise exception 'Access denied: tenant_id % does not match user tenant %', p_tenant_id, v_user_tenant_id;
  end if;
  
  -- Perform upsert
  insert into company_settings (tenant_id, key, value, updated_at)
  values (p_tenant_id, p_key, p_value, now())
  on conflict (tenant_id, key) 
  do update set 
    value = excluded.value,
    updated_at = now();
  
  -- Return success
  return json_build_object('success', true);
exception
  when others then
    -- Return error details
    return json_build_object(
      'success', false,
      'error', SQLERRM,
      'detail', SQLSTATE
    );
end;
$$;


