);


--
-- TOC entry 513 (class 1259 OID 155538)
-- Name: conversation_unread_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.conversation_unread_counts AS
 SELECT cp.conversation_id,
    cp.user_id,
    (COALESCE(count(m.id), (0)::bigint))::integer AS unread_count
   FROM (public.conversation_participants cp
     LEFT JOIN public.messages m ON (((m.conversation_id = cp.conversation_id) AND (m.created_at > COALESCE(cp.last_read_at, '1970-01-01 00:00:00+00'::timestamp with time zone)) AND (m.sender_id <> cp.user_id))))
  GROUP BY cp.conversation_id, cp.user_id;


