--
-- TOC entry 500 (class 1259 OID 148445)
-- Name: products_with_sets; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.products_with_sets AS
 SELECT id,
    name,
    sku,
    description,
    price,
    cost,
    tax_type,
    is_service,
    inventory_qty,
    created_at,
    category_id,
    is_active,
    updated_at,
    additional_images,
    brand,
    model,
    min_stock_level,
    image_url,
    supplier_id,
    supplier_name,
    barcode,
    stock_quantity,
    max_stock_level,
    image_urls,
    category,
    category_name,
    specifications,
    tags,
    unit,
    weight,
    track_stock,
    product_type,
    show_on_website,
    website_description,
    website_featured,
    supplier_reference,
    manufacturer,
    manufacturer_sku,
    gtin,
    hs_code,
    country_of_origin,
    color,
    size,
    material,
    dimensions,
    warranty_months,
    lifecycle_status,
    serialized,
    lot_tracking,
    expiration_tracking,
    expiry_days,
    lead_time_days,
    reorder_quantity,
    warehouse_location,
    price_currency,
    cost_currency,
    tax_rate,
    is_published,
    brand_id,
    tenant_id,
    is_google_merchant,
    supplier_code,
    is_set,
    set_type,
    parent_set_id,
    component_label,
    component_position,
        CASE
            WHEN is_set THEN ( SELECT json_agg(json_build_object('id', psc.id, 'component_product_id', psc.component_product_id, 'component_label', psc.component_label, 'component_position', psc.component_position, 'component_name', cp.name, 'component_sku', cp.sku, 'stock_quantity', COALESCE(cp.stock_quantity, cp.inventory_qty, 0), 'quantity_in_set', psc.quantity_in_set, 'cost_ratio', psc.cost_ratio, 'price_ratio', psc.price_ratio) ORDER BY psc.component_position) AS json_agg
               FROM (public.product_set_components psc
                 JOIN public.products cp ON ((cp.id = psc.component_product_id)))
              WHERE (psc.set_product_id = p.id))
            ELSE NULL::json
        END AS set_components,
        CASE
            WHEN is_set THEN public.get_full_sets_count(id)
            ELSE NULL::integer
        END AS full_sets_available,
        CASE
            WHEN is_set THEN public.is_set_partial(id)
            ELSE NULL::boolean
        END AS is_partial,
        CASE
            WHEN (parent_set_id IS NOT NULL) THEN ( SELECT json_build_object('id', ps.id, 'name', ps.name, 'sku', ps.sku) AS json_build_object
               FROM public.products ps
              WHERE (ps.id = p.parent_set_id))
            ELSE NULL::json
        END AS parent_set_info
   FROM public.products p;


