--
-- TOC entry 551 (class 1259 OID 246906)
-- Name: stock_movements_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.stock_movements_view WITH (security_invoker='on') AS
 WITH movement_documents AS (
         SELECT sm.id,
            sm.product_id,
            p.name AS product_name,
            p.sku AS product_sku,
            sm.date AS transaction_date,
            sm.type,
            sm.movement_type AS raw_movement_type,
            sm.reference,
                CASE
                    WHEN (sm.type = 'OUT'::text) THEN (- abs(sm.quantity))
                    WHEN (sm.type = 'IN'::text) THEN abs(sm.quantity)
                    ELSE sm.quantity
                END AS quantity,
            sm.notes,
            NULL::uuid AS created_by,
            sm.created_at,
            sm.tenant_id,
                CASE
                    WHEN (COALESCE(sm.reference, ''::text) ~ '^sales_invoice:[0-9a-fA-F-]{36}$'::text) THEN (split_part(sm.reference, ':'::text, 2))::uuid
                    WHEN (COALESCE(sm.reference, ''::text) ~ '^purchase_invoice:[0-9a-fA-F-]{36}$'::text) THEN (split_part(sm.reference, ':'::text, 2))::uuid
                    WHEN (COALESCE(sm.reference, ''::text) ~ '^mechanic_job:[0-9a-fA-F-]{36}$'::text) THEN (split_part(sm.reference, ':'::text, 2))::uuid
                    ELSE NULL::uuid
                END AS document_id,
                CASE
                    WHEN (COALESCE(sm.reference, ''::text) ~~ 'sales_invoice:%'::text) THEN 'sales_invoice'::text
                    WHEN (COALESCE(sm.reference, ''::text) ~~ 'purchase_invoice:%'::text) THEN 'purchase_invoice'::text
                    WHEN (COALESCE(sm.reference, ''::text) ~~ 'mechanic_job:%'::text) THEN 'mechanic_job'::text
                    ELSE NULL::text
                END AS document_type
           FROM (public.stock_movements sm
             LEFT JOIN public.products p ON ((((NULLIF((sm.product_id)::text, ''::text))::uuid = p.id) AND (sm.tenant_id = p.tenant_id))))
        ), movements_with_resolution AS (
         SELECT md.id,
            md.product_id,
            md.product_name,
            md.product_sku,
            md.transaction_date,
                CASE
                    WHEN (md.document_type = 'sales_invoice'::text) THEN 'sale'::text
                    WHEN (md.document_type = 'purchase_invoice'::text) THEN 'purchase'::text
                    WHEN (md.document_type = 'mechanic_job'::text) THEN 'sale'::text
                    WHEN (COALESCE(md.raw_movement_type, ''::text) = ANY (ARRAY['purchase'::text, 'purchase_invoice'::text, 'purchase_invoice_reversal'::text, 'manual_purchase'::text])) THEN 'purchase'::text
                    WHEN (COALESCE(md.raw_movement_type, ''::text) = ANY (ARRAY['sale'::text, 'sales_invoice'::text, 'sales_invoice_component'::text, 'sales_invoice_reversal'::text, 'manual_sale'::text])) THEN 'sale'::text
                    WHEN (COALESCE(md.raw_movement_type, ''::text) = ANY (ARRAY['transfer'::text, 'transfer_in'::text, 'transfer_out'::text])) THEN 'transfer'::text
                    WHEN (COALESCE(md.raw_movement_type, ''::text) = ANY (ARRAY['manual'::text, 'correction'::text, 'initial'::text, 'damage'::text, 'loss'::text, 'found'::text, 'import'::text, 'adjustment'::text, 'inventory_adjust'::text, 'inventory_adjustment'::text, 'count_gain'::text, 'count_loss'::text, 'theft'::text, 'internal_use'::text])) THEN 'adjustment'::text
                    ELSE 'adjustment'::text
                END AS movement_type,
                CASE
                    WHEN ((md.document_type = 'sales_invoice'::text) AND (COALESCE(md.raw_movement_type, ''::text) = 'sales_invoice_reversal'::text)) THEN 'sales_invoice_reversal'::text
                    WHEN (md.document_type = 'sales_invoice'::text) THEN COALESCE(si.source, 'sale'::text)
                    WHEN ((md.document_type = 'purchase_invoice'::text) AND (COALESCE(md.raw_movement_type, ''::text) = 'purchase_invoice_reversal'::text)) THEN 'purchase_invoice_reversal'::text
                    WHEN (md.document_type = 'purchase_invoice'::text) THEN 'purchase_invoice'::text
                    WHEN (md.document_type = 'mechanic_job'::text) THEN 'mechanic_job'::text
                    WHEN (NULLIF(TRIM(BOTH FROM COALESCE(md.raw_movement_type, ''::text)), ''::text) IS NOT NULL) THEN md.raw_movement_type
                    ELSE 'manual'::text
                END AS source,
                CASE
                    WHEN (md.document_type = ANY (ARRAY['sales_invoice'::text, 'purchase_invoice'::text, 'mechanic_job'::text])) THEN md.document_id
                    WHEN (sa.id IS NOT NULL) THEN sa.id
                    ELSE NULL::uuid
                END AS reference_id,
                CASE
                    WHEN (md.document_type = 'sales_invoice'::text) THEN COALESCE(NULLIF(si.invoice_number, ''::text), md.reference)
                    WHEN (md.document_type = 'purchase_invoice'::text) THEN COALESCE(NULLIF(pi.invoice_number, ''::text), md.reference)
                    WHEN (md.document_type = 'mechanic_job'::text) THEN COALESCE(NULLIF(mj.job_number, ''::text), md.reference)
                    WHEN (sa.id IS NOT NULL) THEN COALESCE(NULLIF(sa.reference, ''::text), NULLIF(TRIM(BOTH FROM COALESCE(md.reference, ''::text)), ''::text), NULLIF(TRIM(BOTH FROM COALESCE(md.notes, ''::text)), ''::text), NULL::text)
                    WHEN (NULLIF(TRIM(BOTH FROM COALESCE(md.reference, ''::text)), ''::text) IS NOT NULL) THEN md.reference
                    WHEN (NULLIF(TRIM(BOTH FROM COALESCE(md.notes, ''::text)), ''::text) IS NOT NULL) THEN md.notes
                    ELSE NULL::text
                END AS reference_number,
            md.quantity,
            md.notes,
            sa.adjustment_origin,
            COALESCE(md.created_by, sa.created_by) AS created_by,
            md.created_at,
            md.tenant_id
           FROM ((((movement_documents md
             LEFT JOIN public.sales_invoices si ON (((md.document_type = 'sales_invoice'::text) AND (md.document_id = si.id) AND (md.tenant_id = si.tenant_id))))
             LEFT JOIN public.purchase_invoices pi ON (((md.document_type = 'purchase_invoice'::text) AND (md.document_id = pi.id) AND (md.tenant_id = pi.tenant_id))))
             LEFT JOIN public.mechanic_jobs mj ON (((md.document_type = 'mechanic_job'::text) AND (md.document_id = mj.id) AND (md.tenant_id = mj.tenant_id))))
             LEFT JOIN public.stock_adjustments sa ON (((md.document_type IS NULL) AND (md.tenant_id = sa.tenant_id) AND (md.product_id = sa.product_id) AND (md.created_at = sa.created_at) AND (md.quantity = (sa.quantity)::numeric) AND (COALESCE(md.raw_movement_type, ''::text) = sa.adjustment_type))))
        ), movements_with_running_stock AS (
         SELECT m.id,
            m.product_id,
            m.product_name,
            m.product_sku,
            m.transaction_date,
            m.movement_type,
            m.source,
            m.reference_id,
            m.reference_number,
            m.quantity,
            m.notes,
            m.adjustment_origin,
            m.created_by,
            m.created_at,
            m.tenant_id,
            GREATEST(COALESCE(p.stock_quantity, 0), COALESCE(p.inventory_qty, 0)) AS current_stock,
            (GREATEST(COALESCE(p.stock_quantity, 0), COALESCE(p.inventory_qty, 0)) - (COALESCE(sum(m.quantity) OVER (PARTITION BY m.product_id, m.tenant_id ORDER BY m.transaction_date DESC NULLS LAST, m.created_at DESC, m.id DESC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), (0)::numeric))::integer) AS calculated_stock_after
           FROM (movements_with_resolution m
             LEFT JOIN public.products p ON ((((NULLIF((m.product_id)::text, ''::text))::uuid = p.id) AND (m.tenant_id = p.tenant_id))))
        )
 SELECT id,
    product_id,
    product_name,
    product_sku,
    transaction_date,
    movement_type,
    source,
    reference_id,
    reference_number,
    quantity,
    (((calculated_stock_after)::numeric - quantity))::integer AS stock_before,
    calculated_stock_after AS stock_after,
    notes,
    adjustment_origin,
    created_by,
    created_at,
    tenant_id
   FROM movements_with_running_stock;


